package com.matthewmariner.entourage;

import javax.annotation.Nullable;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Constants;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * The {@link WorldView} methods this plugin and {@code LocalPoint.fromWorld} need: the
 * plane, the scene rectangle, the view id, and the collision maps.
 *
 * <p>{@link #around} places the scene the way the client does — a
 * {@link Constants#SCENE_SIZE}-tile square with the player's chunk in the middle — so a
 * tile near the player resolves to a {@code LocalPoint} for the same reason it does in
 * game rather than because the fake is permissive.
 *
 * <p><b>{@link #rectangular} is the fixture {@link #around} cannot replace.</b> Every
 * <i>top-level</i> scene the client builds is square — 104 a side, or
 * {@link Constants#EXTENDED_SCENE_SIZE} on an extended one — and centred, and the
 * centring arithmetic gives a tile near {@code (3221, 3218)} a base of {@code 3168} on
 * <i>both</i> axes. On numbers like those a reader cannot tell {@code getBaseX()} from
 * {@code getBaseY()}, {@code getSizeX()} from {@code getSizeY()}, or
 * {@code flags[sceneX][sceneY]} from {@code flags[sceneY][sceneX]}; those three
 * confusions are exactly the mistakes {@link WalkableStep} and {@link FollowerAnchor}
 * are one keystroke from making, in code that reads the two axes separately on purpose.
 * So this factory takes two bases and two sizes and insists they differ.
 *
 * <p>It is not a shape out of nowhere. The client's world-view constructor takes
 * {@code sizeX} and {@code sizeY} as separate arguments and a {@code WorldEntity}'s view
 * really is whatever rectangle that entity is — a boat is longer than it is wide. What
 * is true is that the top-level view, the only one this plugin will read from today, is
 * always square. That makes this fixture the shape of a case currently refused rather
 * than a shape that cannot exist, and either way it is the only place a transposed axis
 * has to fail.
 *
 * <p><b>Collision defaults to open ground and is allocated lazily.</b> Zero means
 * walkable in the client's own convention, so a test that does not care about collision
 * gets a scene a follower can cross, and pays nothing for it.
 */
final class FakeWorldView extends StubWorldView
{
	private final int baseX;
	private final int baseY;
	private final int sizeX;
	private final int sizeY;
	private int plane;

	/** Which world view this is. 0 is {@link WorldView#TOPLEVEL}. */
	private int id = WorldView.TOPLEVEL;

	/**
	 * One map per plane, matching the client's own four-slot array, or {@code null} for
	 * a view that will not hand any over. The injected client always hands them over —
	 * see {@link #withoutCollisionData} — so this models an implementation of the
	 * interface rather than a moment in the real one's life.
	 */
	@Nullable
	private FakeCollisionData[] collisionMaps;

	private boolean collisionDataAvailable = true;

	/**
	 * Whether this is a private copy of an area — a raid, a quest cutscene, a Player
	 * Owned House. False by default, which is the overworld and every other test's
	 * assumption.
	 */
	private boolean instance;

	private FakeWorldView(int baseX, int baseY, int sizeX, int sizeY, int plane)
	{
		this.baseX = baseX;
		this.baseY = baseY;
		this.sizeX = sizeX;
		this.sizeY = sizeY;
		this.plane = plane;
	}

	/** A scene centred on the given tile's chunk, the way the client centres it. */
	static FakeWorldView around(WorldPoint centre)
	{
		return new FakeWorldView(
			chunkAlignedBase(centre.getX()), chunkAlignedBase(centre.getY()),
			Constants.SCENE_SIZE, Constants.SCENE_SIZE, centre.getPlane());
	}

	/**
	 * A scene whose two axes cannot be mistaken for each other — see the class javadoc.
	 *
	 * @param baseX the west edge, which must differ from {@code baseY}
	 * @param baseY the south edge
	 * @param sizeX the width in tiles, which must differ from {@code sizeY}
	 * @param sizeY the height in tiles
	 * @param plane the plane this scene is on; {@code LocalPoint.fromWorld} refuses a
	 *              {@code WorldPoint} on any other, so every tile a test uses with this
	 *              view has to be on it too
	 * @throws IllegalArgumentException if either pair matches, because a fixture that
	 * quietly went back to being square would take the whole point of it with it
	 */
	static FakeWorldView rectangular(int baseX, int baseY, int sizeX, int sizeY, int plane)
	{
		if (baseX == baseY || sizeX == sizeY)
		{
			throw new IllegalArgumentException(
				"this fixture exists to be asymmetric: base " + baseX + "," + baseY
					+ " size " + sizeX + "," + sizeY);
		}
		return new FakeWorldView(baseX, baseY, sizeX, sizeY, plane);
	}

	private static int chunkAlignedBase(int coordinate)
	{
		// The client's own arithmetic: the centre chunk sits six chunks in.
		return ((coordinate / Constants.CHUNK_SIZE) - 6) * Constants.CHUNK_SIZE;
	}

	/** @return the world tile at the given scene coordinates in this view */
	WorldPoint tileAt(int sceneX, int sceneY)
	{
		return new WorldPoint(baseX + sceneX, baseY + sceneY, plane);
	}

	void setPlane(int plane)
	{
		this.plane = plane;
	}

	@Override
	public int getPlane()
	{
		return plane;
	}

	@Override
	public int getBaseX()
	{
		return baseX;
	}

	@Override
	public int getBaseY()
	{
		return baseY;
	}

	@Override
	public int getSizeX()
	{
		return sizeX;
	}

	@Override
	public int getSizeY()
	{
		return sizeY;
	}

	@Override
	public int getId()
	{
		return id;
	}

	/**
	 * {@code isTopLevel()} in the injected client is compiled to {@code getId() == 0},
	 * so this derives from the id rather than being a second settable flag that could
	 * disagree with it.
	 */
	@Override
	public boolean isTopLevel()
	{
		return id == WorldView.TOPLEVEL;
	}

	/**
	 * Makes this a {@code WorldEntity}'s view rather than the top-level one — the case
	 * where the client's collision map is origin-shifted and cannot be read with scene
	 * coordinates. See {@link WalkableStep}.
	 */
	FakeWorldView asWorldEntityView()
	{
		this.id = 7;
		return this;
	}

	/**
	 * Makes this scene a private copy of an area. Independent of
	 * {@link #asWorldEntityView()}, and deliberately so: an instance is still the
	 * top-level view — a raid is where the player is, not a boat they are standing on —
	 * so the anchor resolves there exactly as it does outside and the only thing that
	 * refuses to draw is the instance setting itself.
	 */
	FakeWorldView asInstance()
	{
		this.instance = true;
		return this;
	}

	@Override
	public boolean isInstance()
	{
		return instance;
	}

	// --- Collision ------------------------------------------------------------

	@Override
	@Nullable
	public CollisionData[] getCollisionMaps()
	{
		return collisionDataAvailable ? maps() : null;
	}

	/**
	 * Fills a tile in outright — a wall, a counter, or open water.
	 *
	 * @throws IllegalArgumentException if the tile is outside this scene, so a fixture
	 * that thought it was blocking something and was not fails loudly rather than
	 * passing for the wrong reason
	 */
	FakeWorldView block(WorldPoint tile)
	{
		return setFlags(tile, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
	}

	/** ORs an arbitrary flag mask into one tile — a wall along one of its edges. */
	FakeWorldView setFlags(WorldPoint tile, int mask)
	{
		int sceneX = tile.getX() - baseX;
		int sceneY = tile.getY() - baseY;
		if (sceneX < 0 || sceneX >= sizeX || sceneY < 0 || sceneY >= sizeY)
		{
			throw new IllegalArgumentException(
				"tile " + tile + " is outside the fake scene at " + baseX + "," + baseY
					+ " sized " + sizeX + "x" + sizeY);
		}

		maps()[tile.getPlane()].set(sceneX, sceneY, mask);
		return this;
	}

	/**
	 * A view that hands back no collision maps at all.
	 *
	 * <p><b>Not a state the injected client is ever in.</b> Its {@code gc[]} field has
	 * exactly one assignment — {@code new gc[4]} in the world view's constructor — so
	 * {@code getCollisionMaps()} never returns {@code null} there. {@code WorldView} is
	 * an interface this plugin does not implement, though, and the raw API's answer for
	 * this case is {@code false}, i.e. "blocked", which is the wrong answer to act on.
	 * The branch exists so that the wrong answer cannot reach a follower; this is what
	 * proves the branch is wired up.
	 */
	FakeWorldView withoutCollisionData()
	{
		collisionDataAvailable = false;
		return this;
	}

	/**
	 * The array exists but this plane's map does not.
	 *
	 * <p>Also not the injected client's state — the same constructor fills all four
	 * slots in a loop before it returns — and here the raw API's answer is an NPE out of
	 * a game-tick handler rather than a wrong verdict. Same reasoning: the check is
	 * cheap, the interface is not ours, and this is what keeps it honest.
	 */
	FakeWorldView withoutCollisionMapFor(int planeToDrop)
	{
		maps()[planeToDrop] = null;
		return this;
	}

	private FakeCollisionData[] maps()
	{
		if (collisionMaps == null)
		{
			// Four, because the client allocates one map per plane.
			collisionMaps = new FakeCollisionData[4];
			for (int i = 0; i < collisionMaps.length; i++)
			{
				// Sized off this view's own rectangle, the way the client allocates it,
				// so a rectangular scene really does have a rectangular flags array.
				collisionMaps[i] = new FakeCollisionData(sizeX, sizeY);
			}
		}
		return collisionMaps;
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * One follower's line: which one, and for how long.
 *
 * <p>Nothing here touches the client, so a thousand ticks of cadence costs nothing and
 * every claim about the randomness is a claim about a seeded stream rather than about
 * luck.
 */
public class FollowerRemarksTest
{
	private static final List<String> FOUR =
		Collections.unmodifiableList(Arrays.asList("one", "two", "three", "four"));

	private static FollowerRemarks remarks()
	{
		return new FollowerRemarks(EntourageFigure.ROGUE, 0);
	}

	@Test
	public void aFollowerStartsWithNothingToSay()
	{
		FollowerRemarks remarks = remarks();

		assertFalse(remarks.isTalking());
		assertNull(remarks.text());
	}

	@Test
	public void aLineStaysUpForItsDwellAndNotATickLonger()
	{
		FollowerRemarks remarks = remarks();
		remarks.say(10, 8, FOUR);

		assertTrue(remarks.isTalking());
		assertFalse("the tick before it is due to end", remarks.expire(17));
		assertTrue("still up", remarks.isTalking());

		assertTrue("and gone on the tick it expires", remarks.expire(18));
		assertFalse(remarks.isTalking());
		assertNull(remarks.text());
	}

	@Test
	public void expiringSomethingThatIsNotThereIsHarmless()
	{
		assertFalse(remarks().expire(1000));
	}

	@Test
	public void clearingStopsItTalkingAtOnce()
	{
		FollowerRemarks remarks = remarks();
		remarks.say(0, 1000, FOUR);
		assertTrue(remarks.isTalking());

		remarks.clear();

		assertFalse(remarks.isTalking());
		assertNull(remarks.text());
	}

	@Test
	public void everythingItSaysIsOneOfTheLinesItWasGiven()
	{
		FollowerRemarks remarks = remarks();

		for (int i = 0; i < 500; i++)
		{
			remarks.say(i, 1, FOUR);
			assertTrue("said something that was not on the list: " + remarks.text(),
				FOUR.contains(remarks.text()));
		}
	}

	/**
	 * <b>Never the same line twice running.</b> Not "rarely": the pick draws from the
	 * other lines and skips the last one, so a repeat is impossible rather than unlikely.
	 * A follower with four lines that said one of them twice in a row reads as the feature
	 * being broken rather than as a coincidence — and with a re-roll instead of a skip
	 * this test would pass most of the time and fail on somebody else's machine.
	 */
	@Test
	public void itNeverSaysTheSameLineTwiceRunning()
	{
		FollowerRemarks remarks = remarks();
		remarks.say(0, 1, FOUR);
		String previous = remarks.text();

		for (int i = 1; i < 2000; i++)
		{
			remarks.say(i, 1, FOUR);
			assertNotEquals("said \"" + previous + "\" twice in a row at " + i,
				previous, remarks.text());
			previous = remarks.text();
		}
	}

	@Test
	public void everyLineComesUpSoonerOrLater()
	{
		FollowerRemarks remarks = remarks();
		Set<String> heard = new HashSet<>();

		for (int i = 0; i < 200; i++)
		{
			remarks.say(i, 1, FOUR);
			heard.add(remarks.text());
		}

		assertEquals("a line nothing ever picks is a line nobody wrote", FOUR.size(), heard.size());
	}

	/** A single line is all it has, so it says that — the no-repeat rule cannot apply. */
	@Test
	public void oneLineIsSaidOverAndOver()
	{
		FollowerRemarks remarks = remarks();
		List<String> only = Collections.singletonList("hello");

		remarks.say(0, 1, only);
		remarks.say(1, 1, only);

		assertEquals("hello", remarks.text());
	}

	/**
	 * A user emptying the custom-lines box while the follower is standing there leaves the
	 * remembered index pointing past the end of the new list. That must be a fresh draw
	 * rather than an {@code IndexOutOfBoundsException} inside a game-tick handler.
	 */
	@Test
	public void aShorterListThanLastTimeIsHandledRatherThanIndexedPastTheEnd()
	{
		FollowerRemarks remarks = remarks();

		// Long enough that the remembered index is very likely past the end of the pair
		// below, and repeated so that it certainly is at least once.
		List<String> many = new ArrayList<>();
		for (int i = 0; i < 12; i++)
		{
			many.add("line " + i);
		}
		List<String> two = Arrays.asList("a", "b");

		for (int i = 0; i < 200; i++)
		{
			remarks.say(i * 2, 1, many);
			remarks.say(i * 2 + 1, 1, two);
			assertTrue(two.contains(remarks.text()));
		}
	}

	@Test
	public void anEmptyListLeavesItSayingNothingRatherThanThrowing()
	{
		FollowerRemarks remarks = remarks();

		remarks.say(0, 10, Collections.emptyList());

		assertFalse(remarks.isTalking());
	}

	/**
	 * <b>The same figure says the same things in the same order every session.</b> Seeded
	 * from the figure rather than from the clock, so a street reads as a place rather than
	 * as a random generator — and so every other test in this file can assert something
	 * about two thousand draws.
	 */
	@Test
	public void theOrderIsTheSameEverySession()
	{
		assertEquals(sequence(new FollowerRemarks(EntourageFigure.VANNAKA, 0), 40),
			sequence(new FollowerRemarks(EntourageFigure.VANNAKA, 0), 40));
	}

	/**
	 * <b>Two figures draw from two streams, and this is the test that is here for a roster
	 * that does not exist yet.</b> With one follower it only says that the seed depends on
	 * the figure; with five it is the difference between five companions and five copies
	 * of one, saying the same line at the same moment forever. A shared {@link
	 * java.util.Random} — or a seed that ignored the figure — passes every other test in
	 * this file.
	 */
	@Test
	public void twoFiguresDoNotSayTheirLinesInLockstep()
	{
		List<String> rogue = sequence(new FollowerRemarks(EntourageFigure.ROGUE, 0), 40);
		List<String> hans = sequence(new FollowerRemarks(EntourageFigure.HANS, 0), 40);

		assertNotEquals("two figures drawing the same sequence is one stream, not two",
			rogue, hans);
	}

	/**
	 * The same claim for whose turn it is to speak. Two followers becoming due on the same
	 * tick would, with a cap of one, mean the second one never spoke at all.
	 */
	@Test
	public void twoFiguresAreNotDueOnTheSameTicks()
	{
		FollowerRemarks rogue = remarks();
		FollowerRemarks hans = new FollowerRemarks(EntourageFigure.HANS, 0);
		int interval = EntourageSettings.DEFAULT_DIALOGUE_INTERVAL_TICKS;

		boolean everDiffered = false;
		for (int tick = 0; tick < interval * 4; tick++)
		{
			if (rogue.dueAt(tick, interval) != hans.dueAt(tick, interval))
			{
				everDiffered = true;
			}
		}

		assertTrue("two figures due on exactly the same ticks are one figure twice", everDiffered);
	}

	/**
	 * <b>The same claim again, for the roster the user can actually build: five copies of
	 * one figure.</b> Nothing stops somebody putting the Rogue in all five slots, and the
	 * figure's name hash is the same number five times — so on the figure alone all five
	 * would share one stream and say the same line at the same moment forever. The two
	 * tests above cannot see it, because both of them use two <i>different</i> figures.
	 */
	@Test
	public void twoCopiesOfOneFigureDoNotSayTheirLinesInLockstep()
	{
		List<String> first = sequence(new FollowerRemarks(EntourageFigure.ROGUE, 0), 40);
		List<String> second = sequence(new FollowerRemarks(EntourageFigure.ROGUE, 1), 40);

		assertNotEquals("two Rogues drawing the same sequence is one stream, not two",
			first, second);
	}

	/**
	 * <b>And whose turn it is to speak, which is the half that actually bites.</b> With
	 * {@link EntourageChatter#MAX_CONCURRENT_LINES} at one, five identical figures becoming
	 * due on exactly the same tick means the first of them takes every turn and the other
	 * four never say a word for the whole session — a bug that looks, from outside, like
	 * four followers with no dialogue.
	 *
	 * <p>Checked at both ends of the cadence: the stagger is taken modulo the interval, so
	 * a stride that separated five followers nicely at a hundred ticks could still fold
	 * them together at ten.
	 */
	@Test
	public void fiveCopiesOfOneFigureAreDueOnFiveDifferentTicks()
	{
		for (int interval : new int[]{
			EntourageSettings.MIN_DIALOGUE_INTERVAL_TICKS,
			EntourageSettings.DEFAULT_DIALOGUE_INTERVAL_TICKS,
			EntourageSettings.MAX_DIALOGUE_INTERVAL_TICKS})
		{
			Set<Integer> dueTicks = new HashSet<>();

			for (int index = 0; index < EntourageSettings.MAX_FOLLOWERS; index++)
			{
				FollowerRemarks remarks = new FollowerRemarks(EntourageFigure.ROGUE, index);

				Integer due = null;
				for (int tick = 1; tick <= interval && due == null; tick++)
				{
					if (remarks.dueAt(tick, interval))
					{
						due = tick;
					}
				}

				assertNotNull("copy " + index + " is never due at interval " + interval, due);
				assertTrue("copies " + index + " and an earlier one are due on tick " + due
					+ " at interval " + interval, dueTicks.add(due));
			}

			assertEquals(EntourageSettings.MAX_FOLLOWERS, dueTicks.size());
		}
	}

	/**
	 * The first slot's stream is exactly what a lone follower's always was. The stagger is
	 * added to the figure's hash, so position zero adds nothing — which is what keeps a
	 * single follower's order of lines the same as it was before the roster existed.
	 */
	@Test
	public void theFirstSlotIsUnchangedByTheRosterExisting()
	{
		assertEquals(sequence(new FollowerRemarks(EntourageFigure.VANNAKA, 0), 40),
			sequence(new FollowerRemarks(EntourageFigure.VANNAKA, 0), 40));
		assertNotEquals("and the second slot is not the first one twice",
			sequence(new FollowerRemarks(EntourageFigure.VANNAKA, 0), 40),
			sequence(new FollowerRemarks(EntourageFigure.VANNAKA, 1), 40));
	}

	/**
	 * Due exactly once per interval — no more, which would be a follower talking over
	 * itself, and no less, which would be a cadence setting that does not mean what it
	 * says.
	 */
	@Test
	public void aFollowerIsDueExactlyOncePerInterval()
	{
		FollowerRemarks remarks = remarks();
		int interval = 25;
		int due = 0;

		for (int tick = 0; tick < interval * 40; tick++)
		{
			if (remarks.dueAt(tick, interval))
			{
				due++;
			}
		}

		assertEquals(40, due);
	}

	/**
	 * Every figure gets a turn, whichever way its hash fell.
	 *
	 * <p><b>And a correction, because a mutation pass earned it.</b> This javadoc used to
	 * claim that {@code Math.floorMod} was load-bearing here — that with a plain {@code %}
	 * a figure whose hash is positive would never become due. That is wrong, and replacing
	 * the floor-mod with a remainder leaves every test in this file green: the result is
	 * only ever compared against zero, and {@code a % n == 0} is exactly
	 * {@code floorMod(a, n) == 0} for any positive {@code n}. The floor-mod stays because
	 * it says what is meant and because it is the version that survives somebody changing
	 * the comparison, not because a test can tell the difference. What this test really
	 * holds is the property in its name.
	 */
	@Test
	public void everyFigureBecomesDueWithinOneIntervalOfStarting()
	{
		int interval = EntourageSettings.DEFAULT_DIALOGUE_INTERVAL_TICKS;

		for (EntourageFigure figure : EntourageFigure.presets())
		{
			FollowerRemarks remarks = new FollowerRemarks(figure, 0);
			boolean due = false;

			for (int tick = 1; tick <= interval; tick++)
			{
				due |= remarks.dueAt(tick, interval);
			}

			assertTrue(figure + " is never due — its stagger fell outside the interval", due);
		}
	}

	private static List<String> sequence(FollowerRemarks remarks, int draws)
	{
		List<String> said = new ArrayList<>(draws);
		for (int i = 0; i < draws; i++)
		{
			remarks.say(i, 1, FOUR);
			said.add(remarks.text());
		}
		return said;
	}
}

package com.matthewmariner.entourage;

import java.util.LinkedHashSet;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * Which way a follower that has stopped walking points.
 *
 * <p><b>Every tile in this file has a different x from its y.</b> The class under test
 * subtracts two coordinates from two others and hands the pair to a lookup table indexed
 * {@code [dx][dy]}, which is exactly where an x and a y get swapped by accident — and on
 * a tile like {@code (3200, 3200)} a transposed pair comes out identical and nothing
 * fails. This is the same discipline {@link FakeWorldView#rectangular} exists for one
 * layer down; there is no world view here to make rectangular, because nothing in
 * {@link FollowerFacing} reads a scene.
 */
public class FollowerFacingTest
{
	/** The follower's tile. x and y differ, and so do their digits. */
	private static final WorldPoint FOLLOWER = new WorldPoint(3221, 3218, 0);

	/** A facing that is not one of the eight, so a rounded answer cannot pass as a copy. */
	private static final int BETWEEN_COMPASS_POINTS = 1300;

	@Test
	public void atMeLooksAtThePlayerFromEveryDirection()
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx == 0 && dy == 0)
				{
					continue;
				}

				WorldPoint player = FOLLOWER.dx(dx).dy(dy);
				assertEquals("player " + dx + "," + dy,
					StepOrientation.forStep(dx, dy),
					FollowerFacing.AT_ME.orientationFor(player, 0, FOLLOWER));
			}
		}
	}

	/**
	 * <b>Reduced to the eight, not an exact bearing.</b> A player five tiles east and one
	 * north is east, because the client's own actors only face those eight — and because
	 * the same table has to answer for a step, where "five east one north" is not a
	 * direction anything can walk in.
	 */
	@Test
	public void atMeIsOneOfTheEightRatherThanAnExactBearing()
	{
		WorldPoint player = FOLLOWER.dx(5).dy(1);

		assertEquals(StepOrientation.forStep(1, 1),
			FollowerFacing.AT_ME.orientationFor(player, 0, FOLLOWER));
	}

	/**
	 * The one answerless case. {@link Follower} keeps the facing it had rather than
	 * handing {@code setOrientation} the {@code -1} that means "not moving".
	 */
	@Test
	public void atMeHasNoAnswerWhenThePlayerIsOnTheFollowersOwnTile()
	{
		assertEquals(StepOrientation.NOT_MOVING,
			FollowerFacing.AT_ME.orientationFor(FOLLOWER, 0, FOLLOWER));
	}

	/**
	 * <b>The player's own facing, copied exactly.</b> Not rounded to the eight: the client
	 * turns a player in smaller increments than a compass point, and a follower that
	 * snapped would jump between facings while the player turned smoothly.
	 */
	@Test
	public void theWayIAmIsThePlayersOwnOrientationUnchanged()
	{
		assertEquals(BETWEEN_COMPASS_POINTS, FollowerFacing.AS_I_AM
			.orientationFor(FOLLOWER.dx(3).dy(-2), BETWEEN_COMPASS_POINTS, FOLLOWER));

		for (int compass = 0; compass < StepOrientation.TURN_UNITS; compass += 256)
		{
			assertEquals(compass,
				FollowerFacing.AS_I_AM.orientationFor(FOLLOWER.dx(1), compass, FOLLOWER));
		}
	}

	/**
	 * And it depends on nothing else. Two followers on opposite sides of the same player
	 * face the same way, which is the whole of what "stand alongside and look where I
	 * look" means.
	 */
	@Test
	public void theWayIAmIgnoresWhereEitherOfThemIsStanding()
	{
		WorldPoint player = FOLLOWER.dx(4).dy(-3);

		int east = FollowerFacing.AS_I_AM
			.orientationFor(player, BETWEEN_COMPASS_POINTS, player.dx(1));
		int west = FollowerFacing.AS_I_AM
			.orientationFor(player, BETWEEN_COMPASS_POINTS, player.dx(-1).dy(2));

		assertEquals(BETWEEN_COMPASS_POINTS, east);
		assertEquals(east, west);
	}

	/**
	 * An orientation from outside 0..2047 is brought inside it rather than passed on.
	 * {@code Actor} is an interface this plugin does not implement, and a figure handed a
	 * negative orientation is one the renderer was never given.
	 */
	@Test
	public void theWayIAmNormalisesAnAngleFromOutsideOneTurn()
	{
		assertEquals(512, FollowerFacing.AS_I_AM
			.orientationFor(FOLLOWER.dx(1), StepOrientation.TURN_UNITS + 512, FOLLOWER));
		assertEquals("a negative angle is a facing, not a sentinel",
			StepOrientation.TURN_UNITS - 512,
			FollowerFacing.AS_I_AM.orientationFor(FOLLOWER.dx(1), -512, FOLLOWER));
	}

	/**
	 * <b>The eight fixed facings are eight different answers, and each is the direction it
	 * is named after.</b> Checked against {@link StepOrientation} rather than against
	 * numbers written out again here — that table is already held to the geometry by its
	 * own test, and a second copy of the numbers would only ever agree with itself.
	 */
	@Test
	public void eachCompassEntryIsTheDirectionItIsNamedAfter()
	{
		assertEquals(StepOrientation.forStep(0, 1), fixed(FollowerFacing.NORTH));
		assertEquals(StepOrientation.forStep(1, 1), fixed(FollowerFacing.NORTH_EAST));
		assertEquals(StepOrientation.forStep(1, 0), fixed(FollowerFacing.EAST));
		assertEquals(StepOrientation.forStep(1, -1), fixed(FollowerFacing.SOUTH_EAST));
		assertEquals(StepOrientation.forStep(0, -1), fixed(FollowerFacing.SOUTH));
		assertEquals(StepOrientation.forStep(-1, -1), fixed(FollowerFacing.SOUTH_WEST));
		assertEquals(StepOrientation.forStep(-1, 0), fixed(FollowerFacing.WEST));
		assertEquals(StepOrientation.forStep(-1, 1), fixed(FollowerFacing.NORTH_WEST));

		Set<Integer> facings = new LinkedHashSet<>();
		for (FollowerFacing facing : FollowerFacing.values())
		{
			if (facing != FollowerFacing.AT_ME && facing != FollowerFacing.AS_I_AM)
			{
				assertTrue(facing + " points the same way as another entry", facings.add(fixed(facing)));
			}
		}
		assertEquals("eight compass points, all different", 8, facings.size());
	}

	/**
	 * A fixed facing is fixed: neither the player's position nor the player's own facing
	 * moves it. Without this, "North" could be quietly wired to the same code as
	 * {@link FollowerFacing#AT_ME} and pass every test that happens to put the player
	 * north.
	 */
	@Test
	public void aFixedFacingIgnoresThePlayerEntirely()
	{
		WorldPoint playerSouth = FOLLOWER.dy(-4);

		assertEquals(StepOrientation.forStep(0, 1),
			FollowerFacing.NORTH.orientationFor(playerSouth, BETWEEN_COMPASS_POINTS, FOLLOWER));
		assertNotEquals("which is not where the player is",
			FollowerFacing.AT_ME.orientationFor(playerSouth, 0, FOLLOWER),
			FollowerFacing.NORTH.orientationFor(playerSouth, 0, FOLLOWER));
	}

	/** No entry may answer with the not-moving sentinel except the one that has to. */
	@Test
	public void onlyAtMeCanFailToAnswer()
	{
		WorldPoint sameTile = FOLLOWER;

		for (FollowerFacing facing : FollowerFacing.values())
		{
			int answer = facing.orientationFor(sameTile, 0, FOLLOWER);
			if (facing == FollowerFacing.AT_ME)
			{
				assertEquals(StepOrientation.NOT_MOVING, answer);
				continue;
			}

			assertNotEquals(facing + " must always have an answer",
				StepOrientation.NOT_MOVING, answer);
			assertTrue(facing + " answered outside one turn",
				answer >= 0 && answer < StepOrientation.TURN_UNITS);
		}
	}

	/** The settings panel renders an enum by its {@code toString()}. */
	@Test
	public void everyEntryHasItsOwnLabel()
	{
		Set<String> labels = new LinkedHashSet<>();
		for (FollowerFacing facing : FollowerFacing.values())
		{
			assertTrue("two entries share a label: " + facing, labels.add(facing.toString()));
			assertLabelled(facing.toString());
		}
		assertEquals(FollowerFacing.values().length, labels.size());
	}

	private static int fixed(FollowerFacing facing)
	{
		// A player standing on the follower's own tile, which is the one arrangement that
		// gives AT_ME no answer — so a fixed facing wired to it would be caught here too.
		return facing.orientationFor(FOLLOWER, 0, FOLLOWER);
	}

	private static void assertLabelled(String label)
	{
		assertTrue("an entry with no label is a blank row in the dropdown",
			label != null && !label.trim().isEmpty());
	}
}

package com.matthewmariner.entourage;

import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * A local player that is somewhere.
 *
 * <p>Two constructors on purpose, and the difference between them is the whole point of
 * {@link FollowerAnchor}:
 *
 * <ul>
 *   <li>{@link #standingOn} puts the render position at the centre of a tile, which is
 *       where a stationary player is drawn;</li>
 *   <li>{@link #partWayFrom} puts it part-way between two tiles <i>and</i> lets the
 *       test set a different {@code getWorldLocation()}, which is what the client does
 *       for the whole of every step: the world location comes off the head of the
 *       movement queue, the render position off the actor's own coordinates.</li>
 * </ul>
 *
 * A fake that could only do the first would make an anchor built from the wrong field
 * indistinguishable from one built from the right one.
 */
final class FakePlayer extends StubPlayer
{
	/**
	 * What {@link #getCurrentOrientation()} always answers: a value no test ever asks a
	 * player to face.
	 *
	 * <p>The two orientation accessors are different fields of the client's actor —
	 * {@code getOrientation()} is the facing the player has settled on and
	 * {@code getCurrentOrientation()} is how far round the body has turned towards it —
	 * and a fake that answered the same number for both would make reading the wrong one
	 * indistinguishable from reading the right one. This number is deliberately not one
	 * of {@link StepOrientation}'s eight, so it cannot coincide with an expected facing
	 * either.
	 */
	static final int INTERPOLATED_ORIENTATION = 1234;

	private final LocalPoint localLocation;
	private final WorldPoint worldLocation;

	private int worldLocationReads;

	/** The target facing, {@code getOrientation()}. South until a test says otherwise. */
	private int orientation;

	private FakePlayer(LocalPoint localLocation, WorldPoint worldLocation)
	{
		this.localLocation = localLocation;
		this.worldLocation = worldLocation;
	}

	/** A player drawn in the middle of a tile, with a matching world location. */
	static FakePlayer standingOn(WorldView view, WorldPoint tile)
	{
		return new FakePlayer(centreOf(view, tile), tile);
	}

	/**
	 * A player drawn {@code fraction} of the way from one tile to the next, whose
	 * {@code getWorldLocation()} already reads as the tile it is heading for — the
	 * client's own behaviour while an actor is moving.
	 */
	static FakePlayer partWayFrom(WorldView view, WorldPoint from, WorldPoint to, float fraction)
	{
		LocalPoint a = centreOf(view, from);
		LocalPoint b = centreOf(view, to);
		LocalPoint drawn = new LocalPoint(
			a.getX() + Math.round((b.getX() - a.getX()) * fraction),
			a.getY() + Math.round((b.getY() - a.getY()) * fraction),
			view);
		return new FakePlayer(drawn, to);
	}

	/** A player whose render position carries a world view id nobody else is holding. */
	static FakePlayer inForeignWorldView(WorldView view, WorldPoint tile, int foreignViewId)
	{
		LocalPoint centre = centreOf(view, tile);
		return new FakePlayer(
			new LocalPoint(centre.getX(), centre.getY(), foreignViewId), tile);
	}

	/** A player whose render position is off the edge of the loaded scene. */
	static FakePlayer outsideTheScene(WorldView view, WorldPoint claimedTile)
	{
		return new FakePlayer(new LocalPoint(-1, -1, view), claimedTile);
	}

	/**
	 * A player drawn in the middle of the tile at the given <i>scene</i> coordinates,
	 * whether or not that tile is inside the view's rectangle.
	 *
	 * <p>Built from the coordinates rather than through {@code LocalPoint.fromWorld},
	 * which returns {@code null} off the scene and so cannot express a player one row
	 * past the edge — which is the case {@link FollowerAnchor}'s bounds check exists for
	 * and the only way to prove it tests {@code sceneY} against {@code getSizeY()} rather
	 * than against {@code getSizeX()}.
	 */
	static FakePlayer atSceneTile(WorldView view, int sceneX, int sceneY)
	{
		// The centre of a tile, which is what LocalPoint.fromScene builds: (scene << 7) + 64.
		return new FakePlayer(
			new LocalPoint((sceneX << 7) + 64, (sceneY << 7) + 64, view),
			new WorldPoint(view.getBaseX() + sceneX, view.getBaseY() + sceneY, view.getPlane()));
	}

	private static LocalPoint centreOf(WorldView view, WorldPoint tile)
	{
		LocalPoint point = LocalPoint.fromWorld(view, tile);
		if (point == null)
		{
			throw new IllegalArgumentException("tile " + tile + " is not in the fake scene");
		}
		return point;
	}

	@Override
	public LocalPoint getLocalLocation()
	{
		return localLocation;
	}

	/**
	 * The server tile — the head of the movement queue, which is what the injected
	 * client builds this from.
	 *
	 * <p>Answered rather than thrown, and counted. {@code StubPlayer} would throw here,
	 * and a throw would make "the anchor never asked" and "the anchor asked and happened
	 * to get the right answer" the same observation, which is exactly the distinction
	 * {@code FollowerAnchorTest} exists to make.
	 */
	@Override
	public WorldPoint getWorldLocation()
	{
		worldLocationReads++;
		return worldLocation;
	}

	/** @return how many times anything asked for the server tile */
	int worldLocationReads()
	{
		return worldLocationReads;
	}

	/** Points this player somewhere. The target facing, which is the one that matters. */
	FakePlayer facing(int orientation)
	{
		this.orientation = orientation;
		return this;
	}

	/** The facing the player has settled on — the field {@link FollowerAnchor} reads. */
	@Override
	public int getOrientation()
	{
		return orientation;
	}

	/**
	 * How far round the body has turned towards it. Answered rather than thrown, and
	 * always with {@link #INTERPOLATED_ORIENTATION}, so that a plugin reading this
	 * accessor instead of the other one fails an assertion with the wrong number in it
	 * rather than blowing up with a stack trace that says nothing about which was
	 * intended.
	 */
	@Override
	public int getCurrentOrientation()
	{
		return INTERPOLATED_ORIENTATION;
	}
}

package com.matthewmariner.entourage;

import java.io.ByteArrayOutputStream;

/**
 * Builds the bytes of one NPC cache record, the way the cache stores it.
 *
 * <p><b>Every test in {@link NpcRecordTest} that proves a width works the same way:</b>
 * write the opcode under test with a payload, then write opcode 13 with a value nothing
 * else in the record uses, then the terminator — and assert the standing animation comes
 * back as that value. A skip that is one byte short or one byte long puts the cursor
 * inside the wrong field, so 13 is read as something else and the assertion fails. That
 * makes "the payload width is right" observable from outside, which a decoder that
 * discards the payload otherwise is not.
 *
 * <p>Big-endian, matching {@code net.runelite.cache.io.InputStream}.
 */
final class NpcRecordBytes
{
	private final ByteArrayOutputStream out = new ByteArrayOutputStream();

	static NpcRecordBytes record()
	{
		return new NpcRecordBytes();
	}

	/** One raw byte — an opcode, a length, or a one-byte payload field. */
	NpcRecordBytes u8(int value)
	{
		out.write(value & 0xFF);
		return this;
	}

	/** Two bytes, big-endian. */
	NpcRecordBytes u16(int value)
	{
		out.write((value >> 8) & 0xFF);
		out.write(value & 0xFF);
		return this;
	}

	/** Four bytes, big-endian. */
	NpcRecordBytes i32(int value)
	{
		out.write((value >> 24) & 0xFF);
		out.write((value >> 16) & 0xFF);
		out.write((value >> 8) & 0xFF);
		out.write(value & 0xFF);
		return this;
	}

	/** A string as the cache stores one: the characters, then a zero byte. */
	NpcRecordBytes str(String value)
	{
		for (int i = 0; i < value.length(); i++)
		{
			out.write(value.charAt(i) & 0xFF);
		}
		out.write(0);
		return this;
	}

	/** Filler, for the payloads whose contents are never read. */
	NpcRecordBytes fill(int count)
	{
		for (int i = 0; i < count; i++)
		{
			out.write(0xAB);
		}
		return this;
	}

	/** Opcode 13 with a value, which is what the width tests look for on the far side. */
	NpcRecordBytes standing(int animationId)
	{
		return u8(13).u16(animationId);
	}

	/** Opcode 14 with a value. */
	NpcRecordBytes walking(int animationId)
	{
		return u8(14).u16(animationId);
	}

	/** The record's own terminator. */
	byte[] end()
	{
		out.write(0);
		return out.toByteArray();
	}

	/** The bytes so far, with no terminator — a truncated record. */
	byte[] unterminated()
	{
		return out.toByteArray();
	}
}

package com.matthewmariner.entourage;

import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * The animation ids, pinned twice over.
 *
 * <p>Once against the {@code gameval} constant, which is what {@link EntourageAnimation}
 * actually names — that catches a constant being renamed underneath the enum. And once
 * against the literal number, which catches the id being <i>renumbered</i>: the constant
 * would still compile, the follower would play whatever animation now sits at that id,
 * and nothing else in the build would notice. Neither assertion is redundant with the
 * other, and the second is the one that would have caught the failure that killed
 * {@code ../lively-cities}' predecessor plugin.
 */
public class EntourageAnimationTest
{
	private final EnumSet<EntourageAnimation> pinned = EnumSet.noneOf(EntourageAnimation.class);

	@Test
	public void everyIdIsTheConstantAndTheNumber()
	{
		// The human rig's own three.
		pin(EntourageAnimation.HUMAN_STAND, AnimationID.HUMAN_READY, 808);
		pin(EntourageAnimation.HUMAN_WALK, AnimationID.HUMAN_WALK_F, 819);
		pin(EntourageAnimation.HUMAN_RUN, AnimationID.HUMAN_RUNNING, 824);

		// Stands and walks for bodies that are holding something.
		pin(EntourageAnimation.STAFF_STAND, AnimationID.HUMAN_STAFFREADY, 813);
		pin(EntourageAnimation.WEAPON_STAND, AnimationID.HUMAN_DH_WEAPON_READY, 2561);
		pin(EntourageAnimation.SWORD_STAND, AnimationID.DH_SWORD_UPDATE_READY, 7053);
		pin(EntourageAnimation.WALKING_STICK_WALK, AnimationID.WALK_WALKINGSTICK, 1146);
		pin(EntourageAnimation.HALBERD_WALK, AnimationID.HUMAN_HALBERDWALK_F, 1205);
		pin(EntourageAnimation.WEAPON_WALK, AnimationID.HUMAN_DH_WEAPON_WALK, 2562);
		pin(EntourageAnimation.SWORD_WALK, AnimationID.DH_SWORD_UPDATE_WALK, 7052);

		// Poses.
		pin(EntourageAnimation.POSE_DANCE, AnimationID.EMOTE_DANCE_LOOP, 10048);
		pin(EntourageAnimation.POSE_CHEER, AnimationID.EMOTE_CHEER_LOOP, 196);
		pin(EntourageAnimation.POSE_WAVE, AnimationID.EMOTE_WAVE_LOOP, 197);
		pin(EntourageAnimation.POSE_SHRUG, AnimationID.EMOTE_SHRUG_LOOP, 12056);
		pin(EntourageAnimation.POSE_FLEX, AnimationID.EMOTE_FLEX_LOOP, 12064);
		pin(EntourageAnimation.POSE_SIT, AnimationID.EMOTE_SIT_LOOP, 10061);
		pin(EntourageAnimation.POSE_CLAP, AnimationID.EMOTE_CLAP_LOOP, 3193);
		pin(EntourageAnimation.POSE_PANIC, AnimationID.EMOTE_PANIC_LOOP, 12050);
		pin(EntourageAnimation.POSE_BOW, AnimationID.EMOTE_BOW_LOOP, 192);
		pin(EntourageAnimation.POSE_LEAN, AnimationID.HUMAN_LEAN_READY, 916);
		pin(EntourageAnimation.POSE_CROSSED_ARMS, AnimationID.RD_KNIGHT_CROSSED_ARMS, 2256);
		pin(EntourageAnimation.POSE_SMUG, AnimationID.HUMAN_SMUG_IDLE, 14000);
		pin(EntourageAnimation.POSE_NERVOUS, AnimationID.NERVOUS_IDLE, 10680);

		assertEquals("an animation with no line above is one nobody has checked the id of",
			EntourageAnimation.values().length, pinned.size());
	}

	private void pin(EntourageAnimation animation, int constant, int literal)
	{
		assertEquals(animation + " names a different gameval constant than documented",
			constant, animation.getId());
		assertEquals(animation + ": that constant has been renumbered under the enum",
			literal, animation.getId());
		assertTrue(animation + " is pinned twice", pinned.add(animation));
	}

	/**
	 * The forward walk, specifically. This plugin turns a follower to face its direction
	 * of travel before it moves, so it is always walking forwards; the backwards and
	 * sideways walks would make a figure moon-walk.
	 */
	@Test
	public void theWalkIsTheForwardOneAndNotOneOfItsThreeNeighbours()
	{
		int walk = EntourageAnimation.HUMAN_WALK.getId();
		assertNotEquals("backwards", AnimationID.HUMAN_WALK_B, walk);
		assertNotEquals("left", AnimationID.HUMAN_WALK_L, walk);
		assertNotEquals("right", AnimationID.HUMAN_WALK_R, walk);
	}

	/**
	 * The same claim for the halberd walk, which the cache also ships in four
	 * directions. A follower that walked forwards with the halberd's <i>backwards</i>
	 * animation is a figure moon-walking with a polearm, which is a worse version of the
	 * exact failure the plain walk's neighbours test exists to prevent.
	 */
	@Test
	public void theHalberdWalkIsTheForwardOneToo()
	{
		int walk = EntourageAnimation.HALBERD_WALK.getId();
		assertEquals(AnimationID.HUMAN_HALBERDWALK_F, walk);
		assertNotEquals("backwards", AnimationID.HUMAN_HALBERDWALK_B, walk);
		assertNotEquals("left", AnimationID.HUMAN_HALBERDWALK_L, walk);
		assertNotEquals("right", AnimationID.HUMAN_HALBERDWALK_R, walk);
	}

	/**
	 * A figure whose idle and walk are the same id is a figure that is not animated by
	 * moving, which is the exact failure this whole class exists to prevent.
	 */
	@Test
	public void everyAnimationIsDistinct()
	{
		Set<Integer> ids = new HashSet<>();
		for (EntourageAnimation animation : EntourageAnimation.values())
		{
			assertTrue(animation + " duplicates an id already in the enum", ids.add(animation.getId()));
		}
		assertEquals(EntourageAnimation.values().length, ids.size());
	}

	@Test
	public void everyIdIsPlausible()
	{
		for (EntourageAnimation animation : EntourageAnimation.values())
		{
			// Zero is the client's own "no animation", and it is a real trap: it looks
			// like a valid id, loads as null, and leaves a figure static forever.
			assertTrue(animation + " has a non-positive id", animation.getId() > 0);
			assertTrue(animation + " is outside the cache's sequence range",
				animation.getId() < 30_000);
		}
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/**
 * A {@link ModelData} that records what was done to it on the way to becoming a model.
 *
 * <p>Four of those records matter, and each is a real bug this plugin could have:
 * whether {@code cloneColors()} was called before the first {@code recolor()} (without
 * it, repainting a merged model can reach through the client's own cache and repaint
 * every instance of that model in the world), which recolour pairs were applied,
 * whether lighting happened at all, and <b>which of the two lighting overloads was
 * used</b>.
 *
 * <p><b>The last one is why {@link #light()} records itself rather than delegating.</b>
 * The no-argument overload is the interface rig — disassembled from the 1.12.38 injected
 * client, it is a single call to {@code light(64, 768, -50, -10, -50)} — and a figure
 * standing in the world wants the world rig instead. If this fake forwarded one to the
 * other, "it was lit" would be all a test could see and the difference between an
 * interface model and a world model would be invisible to every assertion in the suite.
 */
final class FakeModelData extends StubModelData
{
	private final List<int[]> recolours = new ArrayList<>();

	private boolean colorsCloned;
	private boolean recolouredBeforeClone;
	private boolean lit;

	/** The five arguments the five-argument overload was given, or {@code null}. */
	private int[] lighting;

	@Override
	public ModelData cloneColors()
	{
		colorsCloned = true;
		return this;
	}

	@Override
	public ModelData recolor(short find, short replace)
	{
		if (!colorsCloned)
		{
			recolouredBeforeClone = true;
		}
		recolours.add(new int[]{find, replace});
		return this;
	}

	@Override
	public Model light()
	{
		lit = true;
		// Deliberately not recorded as lighting[]: this overload's arguments are the
		// client's, not the plugin's, and a test asking "what did the plugin ask for?"
		// must be able to tell that it asked for nothing.
		return new StubModel();
	}

	@Override
	public Model light(int ambient, int contrast, int x, int y, int z)
	{
		lit = true;
		lighting = new int[]{ambient, contrast, x, y, z};
		return new StubModel();
	}

	boolean wasLit()
	{
		return lit;
	}

	/**
	 * @return the five lighting arguments, or {@code null} if the model was lit through
	 * the no-argument overload — which is the interface rig, and is the bug.
	 */
	@Nullable
	int[] lighting()
	{
		return lighting;
	}

	boolean colorsCloned()
	{
		return colorsCloned;
	}

	boolean recolouredBeforeClone()
	{
		return recolouredBeforeClone;
	}

	List<int[]> recolours()
	{
		return recolours;
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.IndexDataBase;

/**
 * The config index, as far as this plugin uses it.
 *
 * <p>{@code IndexDataBase} has three methods — {@code isOverlayOutdated()},
 * {@code getFileIds(int)} and {@code loadData(int, int)} — so this is the whole
 * interface rather than a subset of a generated stub, and it needs no {@code StubClient}
 * equivalent.
 *
 * <p><b>Modelled on the real one's failure shapes.</b> {@code getFileIds} answers
 * {@code null} for an archive it does not have, not an empty array; {@code loadData}
 * answers {@code null} for a group that is not resident, which is a fetch being enqueued
 * rather than an error. Both of those are the cases {@link NpcArchive} routes differently,
 * so a permissive fake would make the routing untestable.
 *
 * <p>{@link #getFileIds(int)} hands back the same array instance every time it is asked,
 * on purpose: the real one returns the client's own, and a fake that copied would hide a
 * caller that mutated it.
 */
final class FakeIndexDataBase implements IndexDataBase
{
	/** Archive id to its file ids, in the order the fake was told about them. */
	private final Map<Integer, int[]> fileIds = new HashMap<>();

	/** Archive and file to its bytes. Keyed as {@code archive:file}. */
	private final Map<String, byte[]> groups = new HashMap<>();

	/** Files that exist but are not in memory — {@code loadData} answers null for these. */
	private final Set<String> notResident = new HashSet<>();

	/** Archives whose {@code getFileIds} blows up. */
	private final Set<Integer> throwingArchives = new HashSet<>();

	/** Files whose {@code loadData} blows up. */
	private final Set<String> throwingGroups = new HashSet<>();

	/** Every {@code loadData} call, as {@code archive:file}, in order. */
	private final List<String> loads = new ArrayList<>();

	/** Registers one NPC record, and its id in the archive's file list. */
	FakeIndexDataBase withNpc(int npcId, byte[] data)
	{
		addFileId(NpcArchive.NPC_ARCHIVE_ID, npcId);
		groups.put(key(NpcArchive.NPC_ARCHIVE_ID, npcId), data);
		return this;
	}

	/** The id is in the archive's file list but its bytes are not in memory yet. */
	FakeIndexDataBase withNpcNotResident(int npcId)
	{
		addFileId(NpcArchive.NPC_ARCHIVE_ID, npcId);
		notResident.add(key(NpcArchive.NPC_ARCHIVE_ID, npcId));
		return this;
	}

	/** The archive exists but has no file list yet, which is what a bad archive id also gets. */
	FakeIndexDataBase withNoFileList()
	{
		fileIds.clear();
		return this;
	}

	FakeIndexDataBase withThrowingFileIds()
	{
		throwingArchives.add(NpcArchive.NPC_ARCHIVE_ID);
		return this;
	}

	FakeIndexDataBase withThrowingLoad(int npcId)
	{
		addFileId(NpcArchive.NPC_ARCHIVE_ID, npcId);
		throwingGroups.add(key(NpcArchive.NPC_ARCHIVE_ID, npcId));
		return this;
	}

	/** @return every {@code loadData} call made, as {@code archive:file}, in order */
	List<String> loads()
	{
		return loads;
	}

	@Override
	public boolean isOverlayOutdated()
	{
		throw new UnsupportedOperationException(
			"FakeIndexDataBase does not implement isOverlayOutdated() — this plugin has never needed it");
	}

	@Override
	@Nullable
	public int[] getFileIds(int archiveId)
	{
		if (throwingArchives.contains(archiveId))
		{
			throw new IllegalStateException("archive " + archiveId + " blew up on the way out");
		}

		// The real one hands back the client's own array — the same instance, not a copy.
		return fileIds.get(archiveId);
	}

	@Override
	@Nullable
	public byte[] loadData(int archiveId, int fileId)
	{
		String key = key(archiveId, fileId);
		loads.add(key);

		if (throwingGroups.contains(key))
		{
			throw new IllegalStateException("group " + key + " blew up on the way out");
		}

		if (notResident.contains(key))
		{
			// The client enqueues a fetch and answers null in the meantime.
			return null;
		}

		return groups.get(key);
	}

	private void addFileId(int archiveId, int fileId)
	{
		int[] existing = fileIds.get(archiveId);
		if (existing == null)
		{
			fileIds.put(archiveId, new int[]{fileId});
			return;
		}

		int[] grown = new int[existing.length + 1];
		System.arraycopy(existing, 0, grown, 0, existing.length);
		grown[existing.length] = fileId;
		fileIds.put(archiveId, grown);
	}

	private static String key(int archiveId, int fileId)
	{
		return archiveId + ":" + fileId;
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Constants;
import net.runelite.api.GameState;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The plugin's own lifecycle: the two clocks, and the teardown promise.
 *
 * <p>Constructed directly rather than through Guice. {@code startUp()} and
 * {@code shutDown()} are {@code protected}, which same-package test code can call
 * without a subclass, and the three collaborators are package-private fields for the
 * same reason — Guice injects a package-private field exactly as it injects a private
 * one, and the alternative is a mocking framework (none on the classpath) or reflection
 * (banned).
 */
public class EntouragePluginLifecycleTest
{
	private static final int CLIENT_TICKS_PER_GAME_TICK =
		Constants.GAME_TICK_LENGTH / Constants.CLIENT_TICK_LENGTH;

	private static final WorldPoint STANDING = new WorldPoint(3221, 3218, 0);

	private FakeClient client;
	private FakeWorldView view;
	private InlineClientThread clientThread;
	private FakeConfig config;
	private RecordingOverlayRegistry overlays;
	private RecordingSidePanel sidebar;

	@Before
	public void setUp()
	{
		client = new FakeClient().withRosterNpcs();
		view = FakeWorldView.around(STANDING);
		client.setTopLevelWorldView(view);
		client.setLocalPlayer(FakePlayer.standingOn(view, STANDING));
		clientThread = new InlineClientThread();
		config = new FakeConfig();
		overlays = new RecordingOverlayRegistry();
		sidebar = new RecordingSidePanel();
	}

	private RecordingScene recordingScene()
	{
		return new RecordingScene(client, config);
	}

	private EntourageScene scene()
	{
		return new EntourageScene(client, config);
	}

	private static GameStateChanged stateChanged(GameState state)
	{
		GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		return event;
	}

	private static ConfigChanged configChanged(String group)
	{
		ConfigChanged event = new ConfigChanged();
		event.setGroup(group);
		return event;
	}

	private static ConfigChanged configChanged(String group, String key)
	{
		ConfigChanged event = configChanged(group);
		event.setKey(key);
		return event;
	}

	private EntouragePlugin plugin(EntourageScene scene)
	{
		EntouragePlugin plugin = new EntouragePlugin();
		plugin.client = client;
		plugin.clientThread = clientThread;
		plugin.scene = scene;
		plugin.overlayRegistry = overlays;
		plugin.sidePanel = sidebar;
		plugin.config = config;
		plugin.writer = config;

		// A null plugin reference, which is what Overlay(Plugin) is given here and in
		// ../lively-cities' own overlay tests: the base class keeps it for the settings
		// panel's benefit and nothing in this test path reads it.
		plugin.overlay = new EntourageOverlay(null, client, scene, config);
		return plugin;
	}

	// --- The teardown promise ------------------------------------------------

	/**
	 * The non-negotiable, against the client's own registered-object list and with real
	 * followers really spawned first. A teardown test that shuts down an empty plugin
	 * passes whether or not the teardown does anything at all.
	 *
	 * <p><b>The overlay and the sidebar button are held to the same standard as the
	 * objects</b>, and for the same reason: an overlay left in the {@code OverlayManager}
	 * goes on being drawn after the plugin that owns it has stopped, over a roster that has
	 * been emptied underneath it, and a navigation button left in the {@code ClientToolbar}
	 * opens a panel that goes on writing settings for a plugin that is not running. Both are
	 * counted off recording implementations rather than off {@code shutDown()} being read.
	 */
	@Test
	public void shutDownLeavesZeroRegisteredObjects()
	{
		EntourageScene scene = scene();
		EntouragePlugin plugin = plugin(scene);

		plugin.startUp();
		plugin.onGameTick(new GameTick());
		assertTrue("the figures have to be there before the teardown means anything",
			client.registeredCount() > 0);
		assertEquals("and so does the overlay", 1, overlays.registered.size());
		assertTrue("and so does the sidebar button", sidebar.isShown());

		plugin.shutDown();

		assertEquals("a leaked RuneLiteObject is a figure nothing owns", 0, client.registeredCount());
		assertTrue(scene.getFollowers().isEmpty());
		assertTrue("an overlay left registered goes on drawing after shutdown",
			overlays.registered.isEmpty());
		assertFalse("a button left in the toolbar opens a panel for a plugin that is not running",
			sidebar.isShown());
	}

	/**
	 * The sidebar button, added exactly once and taken away exactly once.
	 *
	 * <p>{@code ClientToolbar} keys its navigation off the button <i>instance</i>, so a
	 * {@code @Provides} that built a fresh one on the way back in would leave the old one
	 * behind — and a plugin toggled five times would leave five buttons in the toolbar, four
	 * of them dead. The counts are what catch that; a boolean would not, because "added
	 * twice, removed once" and "added once, removed never" both read as "still there".
	 */
	@Test
	public void theSidebarButtonIsAddedOnceAndTakenAwayOnce()
	{
		EntouragePlugin plugin = plugin(scene());

		plugin.startUp();
		assertEquals(1, sidebar.showCount());
		assertEquals(0, sidebar.hideCount());

		plugin.shutDown();
		assertEquals("one add and one remove, not a rebuild", 1, sidebar.showCount());
		assertEquals(1, sidebar.hideCount());
	}

	/**
	 * <b>Enabling at the login screen still puts the button there.</b> The first tick pass
	 * is skipped when nobody is logged in — there is no world to spawn into — and it would be
	 * easy to skip the button with it. A plugin whose only visible surface appears once you
	 * log in is a plugin that looks broken from the login screen, which is where somebody
	 * enabling it is standing.
	 */
	@Test
	public void theButtonAppearsEvenWithNobodyLoggedIn()
	{
		RecordingScene scene = recordingScene();
		client.setGameState(GameState.LOGIN_SCREEN);

		plugin(scene).startUp();

		assertEquals(0, scene.gameTicks);
		assertTrue("the button is not conditional on a world being loaded", sidebar.isShown());
	}

	/**
	 * A dial moved in RuneLite's own settings screen reaches the panel.
	 *
	 * <p>The panel writes through {@link ConfigWriter} and redraws itself, so this handler
	 * exists for the other direction only — and without it the panel would sit showing the
	 * previous figure under the current one's name for as long as it stayed open.
	 */
	@Test
	public void aSettingChangedElsewhereRedrawsThePanel()
	{
		EntouragePlugin plugin = plugin(scene());

		plugin.onConfigChanged(configChanged(EntourageConfig.GROUP));

		assertEquals(1, sidebar.refreshCount());
	}

	/**
	 * And a setting belonging to some other plugin does not.
	 *
	 * <p>{@code ConfigChanged} fires for every setting in the client, including one per
	 * keystroke in somebody else's text field, so an unfiltered handler is a Swing panel
	 * rebuilt a few hundred times for nothing.
	 */
	@Test
	public void somebodyElsesSettingDoesNotRedrawThePanel()
	{
		EntouragePlugin plugin = plugin(scene());

		plugin.onConfigChanged(configChanged("runelite"));
		plugin.onConfigChanged(configChanged("entourage-something-else"));

		assertEquals(0, sidebar.refreshCount());
	}

	/**
	 * <b>And the same promise with the roster the owner actually asked for.</b> The test
	 * above spawns whatever a fresh profile spawns, which is one figure — so a teardown
	 * that deactivated the first follower and stopped would pass it and leave four figures
	 * standing in the world that nothing owns and nothing short of a client restart can
	 * remove. Five is written out rather than taken from {@code MAX_FOLLOWERS}: a cap
	 * somebody lowered to one would otherwise make this test the weaker one again while
	 * still passing.
	 */
	@Test
	public void shutDownLeavesZeroRegisteredObjectsWithAFullRoster()
	{
		config.setRoster(EntourageFigure.ROGUE, EntourageFigure.HANS, EntourageFigure.VANNAKA,
			EntourageFigure.PIRATE, EntourageFigure.TURAEL);

		EntourageScene scene = scene();
		EntouragePlugin plugin = plugin(scene);

		plugin.startUp();
		plugin.onGameTick(new GameTick());
		assertEquals("all five have to be on the client's list first", 5, client.registeredCount());
		assertEquals(5, scene.getFollowers().size());

		plugin.shutDown();

		assertEquals("four leaked figures look exactly like a teardown that worked, minus four",
			0, client.registeredCount());
		assertTrue(scene.getFollowers().isEmpty());
		assertTrue(overlays.registered.isEmpty());
	}

	/**
	 * <b>And with a typed NPC id in the first slot.</b> A custom body reaches the spawn
	 * path through a branch no preset takes — the cache is read before the models are, and
	 * the id can be refused halfway through — so the teardown promise is asserted against
	 * it rather than inferred from the presets passing.
	 */
	@Test
	public void shutDownLeavesZeroRegisteredObjectsWithATypedNpcId()
	{
		client.withNpc(4931, FakeNpcComposition.of("Cave goblin guard", 60_001))
			.withIndexConfig(new FakeIndexDataBase()
				.withNpc(4931, NpcRecordBytes.record().standing(5101).walking(5102).end()));
		config.setRoster(EntourageFigure.ROGUE, EntourageFigure.HANS, EntourageFigure.VANNAKA,
			EntourageFigure.PIRATE, EntourageFigure.TURAEL)
			.setCustomNpcId(4931);

		EntourageScene scene = scene();
		EntouragePlugin plugin = plugin(scene);

		plugin.startUp();
		plugin.onGameTick(new GameTick());
		assertEquals("all five have to be on the client's list first", 5, client.registeredCount());
		assertTrue("and the first of them has to be wearing the typed id",
			scene.getFollowers().get(0).getBody().isCustom());

		plugin.shutDown();

		assertEquals("a leaked RuneLiteObject is a figure nothing owns", 0, client.registeredCount());
		assertTrue(scene.getFollowers().isEmpty());
		assertTrue(overlays.registered.isEmpty());
	}

	/**
	 * The overlay that comes back out is the one that went in.
	 *
	 * <p>{@code OverlayManager.remove} is an identity removal, so a {@code shutDown} that
	 * built a second instance to hand back — or handed back a different overlay entirely
	 * — would leave the first one drawing forever while looking, from the outside, exactly
	 * like a teardown that worked. The list emptying is not enough on its own to catch
	 * that; the identity is.
	 */
	@Test
	public void theOverlayRemovedIsTheOverlayThatWasAdded()
	{
		EntourageScene scene = scene();
		EntouragePlugin plugin = plugin(scene);

		plugin.startUp();
		assertSame(plugin.overlay, overlays.registered.get(0));

		plugin.shutDown();

		assertEquals("one add and one remove, not a rebuild", 1, overlays.adds);
		assertEquals(1, overlays.removes);
		assertSame("and it is the same object that came back out", plugin.overlay, overlays.lastRemoved);
	}

	@Test
	public void shutDownWithoutAStartUpIsHarmless()
	{
		EntourageScene scene = scene();
		plugin(scene).shutDown();

		assertEquals(0, client.registeredCount());
		assertTrue(overlays.registered.isEmpty());
	}

	@Test
	public void aSecondShutDownStillLeavesNothing()
	{
		EntourageScene scene = scene();
		EntouragePlugin plugin = plugin(scene);
		plugin.startUp();
		plugin.onGameTick(new GameTick());

		plugin.shutDown();
		plugin.shutDown();

		assertEquals(0, client.registeredCount());
		assertTrue(overlays.registered.isEmpty());
	}

	// --- Startup -------------------------------------------------------------

	@Test
	public void enablingThePluginMidSessionRunsAPassWithoutWaitingForATick()
	{
		RecordingScene scene = recordingScene();
		client.setGameState(GameState.LOGGED_IN);

		plugin(scene).startUp();

		assertEquals(1, scene.gameTicks);
		assertEquals("through the client thread, not straight off the EDT", 1, clientThread.invocations);
	}

	@Test
	public void enablingItAtTheLoginScreenRunsNothing()
	{
		RecordingScene scene = recordingScene();
		client.setGameState(GameState.LOGIN_SCREEN);

		plugin(scene).startUp();

		assertEquals(0, scene.gameTicks);
		assertEquals(0, clientThread.invocations);
	}

	// --- The two clocks ------------------------------------------------------

	@Test
	public void aGameTickIsAGameTickAndAFrameIsAFrame()
	{
		RecordingScene scene = recordingScene();
		EntouragePlugin plugin = plugin(scene);

		plugin.onGameTick(new GameTick());
		plugin.onBeforeRender(new BeforeRender());

		assertEquals(1, scene.gameTicks);
		assertEquals(1, scene.frames);
	}

	@Test
	public void theFrameFractionRunsFromZeroToOneAcrossAGameTick()
	{
		RecordingScene scene = recordingScene();
		EntouragePlugin plugin = plugin(scene);

		client.setGameCycle(1000);
		plugin.onGameTick(new GameTick());

		plugin.onBeforeRender(new BeforeRender());
		assertEquals("the frame the tick arrived on is the start of the step",
			0f, scene.fractions.get(0), 0.0001f);

		client.advanceGameCycle(CLIENT_TICKS_PER_GAME_TICK / 2);
		plugin.onBeforeRender(new BeforeRender());
		assertEquals(0.5f, scene.fractions.get(1), 0.0001f);

		client.advanceGameCycle(CLIENT_TICKS_PER_GAME_TICK / 2);
		plugin.onBeforeRender(new BeforeRender());
		assertEquals(1f, scene.fractions.get(2), 0.0001f);
	}

	@Test
	public void aLateGameTickDoesNotSendFollowersSlidingPastTheirTile()
	{
		RecordingScene scene = recordingScene();
		EntouragePlugin plugin = plugin(scene);

		client.setGameCycle(1000);
		plugin.onGameTick(new GameTick());
		client.advanceGameCycle(CLIENT_TICKS_PER_GAME_TICK * 4);
		plugin.onBeforeRender(new BeforeRender());

		assertEquals(1f, scene.fractions.get(0), 0.0001f);
	}

	@Test
	public void aFrameBeforeItsGameTickDoesNotDragThemBack()
	{
		RecordingScene scene = recordingScene();
		EntouragePlugin plugin = plugin(scene);

		client.setGameCycle(1000);
		plugin.onGameTick(new GameTick());
		client.setGameCycle(990);
		plugin.onBeforeRender(new BeforeRender());

		assertEquals(0f, scene.fractions.get(0), 0.0001f);
	}

	/**
	 * {@code getGameCycle()} is an {@code int} counting 20ms ticks, so it wraps after
	 * about 497 days of client uptime. Two's-complement {@code int} subtraction wraps
	 * with it, which makes the elapsed count come out right across the seam; promoting
	 * either side to {@code long} would turn that one frame into a huge negative elapsed
	 * and freeze every follower mid-step until the next game tick.
	 */
	@Test
	public void theFractionSurvivesTheGameCycleWrappingRoundTheIntegerSeam()
	{
		RecordingScene scene = recordingScene();
		EntouragePlugin plugin = plugin(scene);

		client.setGameCycle(Integer.MAX_VALUE - 5);
		plugin.onGameTick(new GameTick());

		// Ten client ticks later, which crosses the seam.
		client.setGameCycle(Integer.MIN_VALUE + 4);
		plugin.onBeforeRender(new BeforeRender());

		assertEquals(10 / (float) CLIENT_TICKS_PER_GAME_TICK, scene.fractions.get(0), 0.0001f);
	}

	@Test
	public void aFrameWithNoWorldViewDoesNothingRatherThanThrowing()
	{
		RecordingScene scene = recordingScene();
		client.setTopLevelWorldView(null);

		plugin(scene).onBeforeRender(new BeforeRender());

		assertEquals(0, scene.frames);
	}

	// --- Game state ----------------------------------------------------------

	@Test
	public void everyStateThatReplacesTheSceneInvalidatesIt()
	{
		RecordingScene scene = recordingScene();
		EntouragePlugin plugin = plugin(scene);

		for (GameState state : new GameState[]{
			GameState.LOADING, GameState.HOPPING, GameState.LOGGING_IN,
			GameState.LOGIN_SCREEN, GameState.LOGIN_SCREEN_AUTHENTICATOR, GameState.CONNECTION_LOST})
		{
			plugin.onGameStateChanged(stateChanged(state));
		}

		assertEquals(6, scene.invalidations.size());
		assertTrue(scene.invalidations.contains("LOADING"));
		assertTrue(scene.invalidations.contains("HOPPING"));
	}

	/**
	 * {@code LOGGED_IN} fires before the world is usable — {@code getLocalPlayer()} is
	 * still null at that point — so there is deliberately no work on it. Invalidating
	 * there would also throw away the scene the tick handler is about to use.
	 */
	@Test
	public void loggedInDoesNothing()
	{
		RecordingScene scene = recordingScene();
		plugin(scene).onGameStateChanged(stateChanged(GameState.LOGGED_IN));

		assertTrue(scene.invalidations.isEmpty());
		assertEquals(0, scene.gameTicks);
	}

	/**
	 * The {@code OverlayManager}, minus the manager — see {@link OverlayRegistry} for why
	 * the real one cannot be stood in for.
	 *
	 * <p>It keeps the list rather than only counting, because "added once and removed
	 * once" and "left registered" are the same pair of counts when the removal takes the
	 * wrong overlay.
	 */
	private static final class RecordingOverlayRegistry implements OverlayRegistry
	{
		private final List<net.runelite.client.ui.overlay.Overlay> registered = new ArrayList<>();

		private net.runelite.client.ui.overlay.Overlay lastRemoved;
		private int adds;
		private int removes;

		@Override
		public void add(net.runelite.client.ui.overlay.Overlay overlay)
		{
			adds++;
			registered.add(overlay);
		}

		@Override
		public void remove(net.runelite.client.ui.overlay.Overlay overlay)
		{
			removes++;
			lastRemoved = overlay;
			registered.remove(overlay);
		}
	}

	/** The real {@link ClientThread}, minus the thread. */
	private static final class InlineClientThread extends ClientThread
	{
		private int invocations;

		@Override
		public void invoke(Runnable runnable)
		{
			invocations++;
			runnable.run();
		}
	}

	/**
	 * The real {@link EntourageScene} with every entry point counted and none of them
	 * doing anything. Nothing is stubbed out that the plugin does not call, so a new call
	 * from the plugin lands on the real implementation rather than being silently
	 * swallowed.
	 */
	private static final class RecordingScene extends EntourageScene
	{
		private final List<Float> fractions = new ArrayList<>();
		private final List<String> invalidations = new ArrayList<>();

		private int gameTicks;
		private int frames;

		private RecordingScene(net.runelite.api.Client client, EntourageConfig config)
		{
			super(client, config);
		}

		@Override
		void onGameTick()
		{
			gameTicks++;
		}

		@Override
		void onFrame(WorldView worldView, float fraction)
		{
			frames++;
			fractions.add(fraction);
		}

		@Override
		void invalidate(String reason)
		{
			invalidations.add(reason);
		}

		@Override
		int shutdown()
		{
			return 0;
		}
	}

	// --- the dropdown and the typed id ----------------------------------------

	/**
	 * <b>An id typed into RuneLite's own settings screen flips that slot's dropdown to
	 * "Custom NPC id".</b> The panel writes both halves itself; the settings screen writes
	 * one, and this handler is the only place that can write the other.
	 */
	@Test
	public void anIdTypedInTheSettingsScreenSetsTheDropdownToCustom()
	{
		EntouragePlugin plugin = plugin(scene());
		config.setCustomNpcId(4931).clearWrites();
		// ConfigManager answers every write with another ConfigChanged, synchronously and
		// on the posting thread, so the sync's own write comes straight back through here.
		config.echoWritesTo(key -> plugin.onConfigChanged(configChanged(EntourageConfig.GROUP, key)));

		plugin.onConfigChanged(configChanged(EntourageConfig.GROUP, EntourageConfig.KEY_CUSTOM_NPC_ID));

		assertEquals(java.util.Collections.singletonList("figure=CUSTOM"), config.writes());
		assertSame(EntourageFigure.CUSTOM, EntourageSettings.storedFigureAt(config, 0));
		assertEquals("and the panel is told once per event: the typed id, then the sync's own write",
			2, sidebar.refreshCount());
	}

	/**
	 * <b>The profile switch that would have lost an id.</b> {@code ConfigManager.switchProfile}
	 * posts one {@code ConfigChanged} per key that differs, in hash order, with the new
	 * profile already readable — so a profile from before the marker existed can announce
	 * its dropdown before its id. Through the real handler, with every write echoed back
	 * as the client echoes it, the id has to survive both orders.
	 */
	@Test
	public void aProfileSwitchedUnderneathKeepsItsTypedIdWhicheverEventLandsFirst()
	{
		EntouragePlugin plugin = plugin(scene());
		config.echoWritesTo(key -> plugin.onConfigChanged(configChanged(EntourageConfig.GROUP, key)));
		String[][] orders = {
			{EntourageConfig.KEY_FIGURE, EntourageConfig.KEY_CUSTOM_NPC_ID},
			{EntourageConfig.KEY_CUSTOM_NPC_ID, EntourageConfig.KEY_FIGURE},
		};

		for (String[] order : orders)
		{
			config.setFigure(EntourageFigure.THIEF).setCustomNpcId(2215).clearWrites();

			for (String key : order)
			{
				plugin.onConfigChanged(configChanged(EntourageConfig.GROUP, key));
			}

			String state = String.join(" then ", order);
			assertEquals(state + ": the id survives", 2215, config.view().getSlot(0).getCustomNpcId());
			assertSame(state, EntourageFigure.CUSTOM, EntourageSettings.storedFigureAt(config, 0));
			assertEquals(state, java.util.Collections.singletonList("figure=CUSTOM"), config.writes());
		}
	}

	/**
	 * The settings screen cannot clear an id by picking a preset over it: from inside the
	 * event that is indistinguishable from a profile switch, and the box wins. The panel's
	 * picker clears it, in {@code RosterEdit#assign}, because the panel knows a pick is a
	 * pick.
	 */
	@Test
	public void aPresetPickedInTheSettingsScreenOverAnIdIsCorrectedBackToCustom()
	{
		EntouragePlugin plugin = plugin(scene());
		config.setFigure(EntourageFigure.CUSTOM).setCustomNpcId(4931);
		config.setFigure(EntourageFigure.GHOMMAL).clearWrites();
		config.echoWritesTo(key -> plugin.onConfigChanged(configChanged(EntourageConfig.GROUP, key)));

		plugin.onConfigChanged(configChanged(EntourageConfig.GROUP, EntourageConfig.KEY_FIGURE));

		assertEquals(java.util.Collections.singletonList("figure=CUSTOM"), config.writes());
		assertEquals("the id is untouched", 4931, config.view().getSlot(0).getCustomNpcId());
	}

	/** The group filter guards the write as well as the redraw. */
	@Test
	public void somebodyElsesSettingDoesNotTouchTheRoster()
	{
		EntouragePlugin plugin = plugin(scene());
		config.setCustomNpcId(4931).clearWrites();

		plugin.onConfigChanged(configChanged("runelite", EntourageConfig.KEY_CUSTOM_NPC_ID));

		assertTrue(config.writes().isEmpty());
	}

	/**
	 * <b>Start-up is the migration.</b> A profile from before the dropdown could say "Custom
	 * NPC id" — an id under a preset — is brought up to date before the first tick reads it,
	 * and a profile that already agrees with itself is left alone.
	 */
	@Test
	public void startUpBringsAnOldProfileUpToDate()
	{
		config.setFigure(EntourageFigure.WISE_OLD_MAN).setCustomNpcId(3162).clearWrites();
		client.setGameState(GameState.LOGIN_SCREEN);
		EntouragePlugin plugin = plugin(scene());

		plugin.startUp();

		assertEquals(java.util.Collections.singletonList("figure=CUSTOM"), config.writes());
		assertSame(EntourageFigure.CUSTOM, EntourageSettings.storedFigureAt(config, 0));
		assertEquals(3162, config.view().getSlot(0).getCustomNpcId());

		config.clearWrites();
		plugin.shutDown();
		plugin.startUp();
		assertTrue("a second start-up has nothing left to do", config.writes().isEmpty());
	}
}

package com.matthewmariner.entourage;

import javax.annotation.Nullable;

/**
 * An NPC composition with a name, some models and some recolour pairs.
 *
 * <p><b>Nulls are first-class here.</b> Every one of the four accessors this plugin
 * reads compiles, in the injected client, to a bare {@code getfield} on a field the
 * constructor only assigns for a composition whose cache entry carried that opcode — so
 * a real composition can hand back {@code null} from any of them, and
 * {@link FollowerAppearance} has to survive it. A fake that always returned arrays would
 * make those null checks untestable.
 */
final class FakeNpcComposition extends StubNpcComposition
{
	@Nullable
	private final String name;

	@Nullable
	private final int[] models;

	@Nullable
	private final short[] find;

	@Nullable
	private final short[] replace;

	private FakeNpcComposition(
		@Nullable String name,
		@Nullable int[] models,
		@Nullable short[] find,
		@Nullable short[] replace)
	{
		this.name = name;
		this.models = models;
		this.find = find;
		this.replace = replace;
	}

	/** A plain composition: a name, some models, no recolours. */
	static FakeNpcComposition of(String name, int... models)
	{
		return new FakeNpcComposition(name, models, new short[0], new short[0]);
	}

	/** The same, plus a matched set of recolour pairs. */
	static FakeNpcComposition recoloured(String name, int[] models, short[] find, short[] replace)
	{
		return new FakeNpcComposition(name, models, find, replace);
	}

	/** A composition the cache produced with one or more of its arrays absent. */
	static FakeNpcComposition withNulls(
		@Nullable String name,
		@Nullable int[] models,
		@Nullable short[] find,
		@Nullable short[] replace)
	{
		return new FakeNpcComposition(name, models, find, replace);
	}

	@Override
	@Nullable
	public String getName()
	{
		return name;
	}

	@Override
	@Nullable
	public int[] getModels()
	{
		return models;
	}

	@Override
	@Nullable
	public short[] getColorToReplace()
	{
		return find;
	}

	@Override
	@Nullable
	public short[] getColorToReplaceWith()
	{
		return replace;
	}
}

package com.matthewmariner.entourage;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * The shipped lines: that every figure has some, that none of them is too long to draw,
 * and that the set is a set rather than a list with the same line in it twice.
 *
 * <p><b>What this file cannot check is the one thing that matters most</b> — whether a
 * line is really what that NPC says. No test can: the wiki is not on this classpath and
 * this plugin does not make network calls. The provenance is stated per figure in
 * {@link FigureLines}, with the transcript URL beside each sourced set, and stated again
 * in the README so that a user can tell the game's wording from ours. What is held here
 * is everything downstream of that.
 */
public class FigureLinesTest
{
	/**
	 * <b>Three and seven are literals here, not {@link FigureLines#MIN_LINES} and
	 * {@link FigureLines#MAX_LINES}.</b> An assertion that takes its expected value from
	 * the constant it is checking proves only that the data agrees with whatever the
	 * constant currently says: dropping {@code MIN_LINES} to zero would leave a figure
	 * with nothing to say passing a test named for catching exactly that. "Three to seven"
	 * is the requirement, so it is written down as the requirement.
	 */
	@Test
	public void everyFigureInTheRosterHasBetweenThreeAndSevenLines()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			List<String> lines = FigureLines.of(figure);

			assertTrue(figure + " has " + lines.size() + " lines — fewer than three, and a "
					+ "figure with nothing to say is a dialogue setting that silently does "
					+ "nothing for whoever picked it",
				lines.size() >= 3);
			assertTrue(figure + " has " + lines.size() + " lines, more than seven",
				lines.size() <= 7);
		}
	}

	/** And the constants the rest of the class reasons with agree with the requirement. */
	@Test
	public void theShippedBoundsAreTheThreeToSevenThatWasAskedFor()
	{
		assertEquals(3, FigureLines.MIN_LINES);
		assertEquals(7, FigureLines.MAX_LINES);
	}

	/**
	 * A line longer than a custom one is allowed to be would be a banner across the
	 * viewport — the overlay draws it centred over the head without wrapping — and would
	 * also be a preset a user could not retype into the box.
	 */
	@Test
	public void noShippedLineIsLongerThanTheOverlayWillDraw()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			for (String line : FigureLines.of(figure))
			{
				assertTrue(figure + ": \"" + line + "\" is " + line.length() + " characters",
					line.length() <= EntourageSettings.MAX_CUSTOM_LINE_LENGTH);
			}
		}
	}

	/**
	 * <b>Within a figure the lines are distinct.</b> {@link FollowerRemarks} never repeats
	 * the line it just said, so a duplicate would defeat that guard by being a different
	 * index carrying the same words — the follower would look like it had repeated itself
	 * and nothing would be able to tell.
	 *
	 * <p>Across figures they are deliberately <i>not</i> distinct: the six slayer masters
	 * really do share a script in game, which is the next test.
	 */
	@Test
	public void aFigureNeverShipsTheSameLineTwice()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			Set<String> seen = new HashSet<>();
			for (String line : FigureLines.of(figure))
			{
				assertTrue(figure + " ships \"" + line + "\" twice", seen.add(line));
			}
		}
	}

	/**
	 * <b>The shared slayer-master template is shared on purpose, and this pins that it is
	 * a decision.</b> Nieve, Duradel and Mazchna have essentially nothing else short
	 * enough on their transcripts. Anybody who reads this as a copy-paste mistake and
	 * "fixes" it by writing them something distinctive would be inventing dialogue and
	 * shipping it as the game's — which is the one thing {@link FigureLines} exists not to
	 * do. If they are ever given their own lines, those lines have to move to the "ours"
	 * block with the rest.
	 */
	@Test
	public void theSlayerMastersShareTheScriptTheGameGivesThem()
	{
		String template = "'Ello, and what are you after then?";

		for (EntourageFigure master : new EntourageFigure[]{
			EntourageFigure.VANNAKA, EntourageFigure.NIEVE, EntourageFigure.STEVE,
			EntourageFigure.TURAEL, EntourageFigure.DURADEL, EntourageFigure.MAZCHNA})
		{
			// Turael is the exception: his own transcript is well enough stocked that he
			// does not need the template at all.
			if (master == EntourageFigure.TURAEL)
			{
				assertFalse("Turael has his own lines and should not be carrying the template",
					FigureLines.of(master).contains(template));
				continue;
			}

			assertTrue(master + " should carry the greeting every slayer master shares",
				FigureLines.of(master).contains(template));
		}
	}

	/**
	 * Nothing blank, nothing padded, and nothing with a line break in it. A line is drawn
	 * with {@code drawString}, which renders a newline as a box glyph rather than as a
	 * second line.
	 */
	@Test
	public void everyLineIsOneTrimmedNonEmptyLine()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			for (String line : FigureLines.of(figure))
			{
				assertFalse(figure + " ships an empty line", line.trim().isEmpty());
				assertEquals(figure + ": \"" + line + "\" has whitespace around it",
					line, line.trim());

				for (int i = 0; i < line.length(); i++)
				{
					if (Character.isISOControl(line.charAt(i)))
					{
						fail(figure + ": \"" + line + "\" contains a control character");
					}
				}
			}
		}
	}

	/**
	 * <b>The lists are shared, so they had better be unmodifiable.</b> One list per figure
	 * is handed to every follower that ever wears it and to
	 * {@link EntourageSettings#linesFor}; a caller that could edit it would be editing the
	 * roster for the rest of the session.
	 */
	@Test
	public void theShippedListsCannotBeEditedByTheirCallers()
	{
		try
		{
			FigureLines.of(EntourageFigure.ROGUE).add("...and I would have got away with it");
			fail("a shared list that can be added to is a roster any caller can rewrite");
		}
		catch (UnsupportedOperationException expected)
		{
			// The point of the test.
		}
	}

	/**
	 * A figure with no entry gets an empty list rather than a null. The roster test above
	 * makes this unreachable today, and it is the branch that keeps the unreachable case
	 * from being a null dereference inside a game-tick handler if it ever is.
	 */
	@Test
	public void aFigureWithNoEntryAnswersEmptyRatherThanNull()
	{
		assertTrue(FigureLines.of(null).isEmpty());
	}
}

