package com.matthewmariner.entourage;

import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The idle-pose dropdown: which animation each entry holds, and the one rule that makes
 * an entry safe to be in it.
 *
 * <p><b>The rule is "it has to loop", and it cannot be checked by looking at the id.</b>
 * A one-shot emote and a looping one are both positive integers; the difference is in
 * what the cache authored, and the only trace of it available at compile time is the
 * constant's name. Reflection is banned in this repo, so the enforceable version of the
 * rule is the pinning test below: every pose has to be named here against a {@code _LOOP}
 * emote or a {@code _READY}/{@code _IDLE} held pose, and a new entry with no line here
 * fails. That turns "is this loopable?" into a question a reviewer is made to answer
 * rather than one that can be skipped.
 */
public class EntouragePoseTest
{
	private final EnumSet<EntouragePose> pinned = EnumSet.noneOf(EntouragePose.class);

	@Test
	public void everyPoseHoldsTheLoopingAnimationItIsDocumentedAsHolding()
	{
		// The nine _LOOP emotes. The cache's own suffix is what says these repeat.
		pin(EntouragePose.DANCE, EntourageAnimation.POSE_DANCE, AnimationID.EMOTE_DANCE_LOOP, 10048);
		pin(EntouragePose.CHEER, EntourageAnimation.POSE_CHEER, AnimationID.EMOTE_CHEER_LOOP, 196);
		pin(EntouragePose.WAVE, EntourageAnimation.POSE_WAVE, AnimationID.EMOTE_WAVE_LOOP, 197);
		pin(EntouragePose.CLAP, EntourageAnimation.POSE_CLAP, AnimationID.EMOTE_CLAP_LOOP, 3193);
		pin(EntouragePose.BOW, EntourageAnimation.POSE_BOW, AnimationID.EMOTE_BOW_LOOP, 192);
		pin(EntouragePose.SHRUG, EntourageAnimation.POSE_SHRUG, AnimationID.EMOTE_SHRUG_LOOP, 12056);
		pin(EntouragePose.FLEX, EntourageAnimation.POSE_FLEX, AnimationID.EMOTE_FLEX_LOOP, 12064);
		pin(EntouragePose.PANIC, EntourageAnimation.POSE_PANIC, AnimationID.EMOTE_PANIC_LOOP, 12050);
		pin(EntouragePose.SIT, EntourageAnimation.POSE_SIT, AnimationID.EMOTE_SIT_LOOP, 10061);

		// The four held poses, which are not emotes at all — a _READY or an _IDLE is a
		// pose the cache expects to be held rather than played through.
		pin(EntouragePose.LEAN, EntourageAnimation.POSE_LEAN, AnimationID.HUMAN_LEAN_READY, 916);
		pin(EntouragePose.CROSSED_ARMS, EntourageAnimation.POSE_CROSSED_ARMS,
			AnimationID.RD_KNIGHT_CROSSED_ARMS, 2256);
		pin(EntouragePose.SMUG, EntourageAnimation.POSE_SMUG, AnimationID.HUMAN_SMUG_IDLE, 14000);
		pin(EntouragePose.NERVOUS, EntourageAnimation.POSE_NERVOUS, AnimationID.NERVOUS_IDLE, 10680);

		assertEquals("a pose with no line above is one nobody has checked loops",
			EntouragePose.values().length - 1, pinned.size());
	}

	private void pin(EntouragePose pose, EntourageAnimation animation, int constant, int literal)
	{
		assertSame(pose + " does not hold the animation it is documented as holding",
			animation, pose.getAnimation());
		assertEquals(pose + " names a different gameval constant than documented",
			constant, animation.getId());
		assertEquals(pose + ": that constant has been renumbered",
			literal, animation.getId());
		assertTrue(pose + " is pinned twice", pinned.add(pose));
	}

	/**
	 * <b>The structural half of the loop rule.</b> A pose that reached for a walk or a
	 * run would be a figure playing a locomotion cycle while standing perfectly still —
	 * running on the spot — and one that reached for a figure's stand would silently
	 * duplicate {@link EntouragePose#FIGURE_DEFAULT} under a different name. Keeping the
	 * two sets of animations disjoint is the version of that a test can check.
	 */
	@Test
	public void noPoseBorrowsAnAnimationAFigureMovesWith()
	{
		Set<EntourageAnimation> figureAnimations = new HashSet<>();
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			figureAnimations.add(figure.getIdleAnimation());
			figureAnimations.add(figure.getWalkAnimation());
			figureAnimations.add(figure.getRunAnimation());
		}

		for (EntouragePose pose : EntouragePose.values())
		{
			EntourageAnimation animation = pose.getAnimation();
			if (animation == null)
			{
				continue;
			}
			assertFalse(pose + " holds " + animation + ", which is a figure's own animation",
				figureAnimations.contains(animation));
		}
	}

	@Test
	public void figureDefaultIsTheOnlyEntryWithNoAnimationOfItsOwn()
	{
		assertNull(EntouragePose.FIGURE_DEFAULT.getAnimation());

		for (EntouragePose pose : EntouragePose.values())
		{
			if (pose != EntouragePose.FIGURE_DEFAULT)
			{
				assertNotNull(pose + " has nothing to hold", pose.getAnimation());
			}
		}
	}

	/**
	 * <b>The behaviour the setting actually has.</b> {@code FIGURE_DEFAULT} has to
	 * follow the figure, and every other pose has to override it — checked against two
	 * figures whose own stands differ, because a resolver that always returned the
	 * figure's stand and one that always returned the pose's are indistinguishable on a
	 * single figure whose stand happens to match.
	 */
	@Test
	public void figureDefaultFollowsTheFigureAndEveryOtherPoseOverridesIt()
	{
		assertNotEquals("this test needs two figures that stand differently",
			EntourageFigure.ROGUE.getIdleAnimation(), EntourageFigure.NIEVE.getIdleAnimation());

		assertSame(EntourageFigure.ROGUE.getIdleAnimation(),
			EntouragePose.FIGURE_DEFAULT.animationFor(EntourageFigure.ROGUE));
		assertSame(EntourageFigure.NIEVE.getIdleAnimation(),
			EntouragePose.FIGURE_DEFAULT.animationFor(EntourageFigure.NIEVE));

		for (EntouragePose pose : EntouragePose.values())
		{
			if (pose == EntouragePose.FIGURE_DEFAULT)
			{
				continue;
			}

			assertSame(pose + " on a rogue", pose.getAnimation(),
				pose.animationFor(EntourageFigure.ROGUE));
			assertSame(pose + " on Nieve", pose.getAnimation(),
				pose.animationFor(EntourageFigure.NIEVE));
		}
	}

	/**
	 * Never {@code null}, whatever is asked. {@link Follower} tells "the cache has not
	 * warmed up" from "there is no pose" by the controller being null, and a pose that
	 * resolved to nothing would collapse that distinction — one is retried and the other
	 * is permanent.
	 */
	@Test
	public void everyPoseResolvesToSomethingForEveryFigure()
	{
		for (EntouragePose pose : EntouragePose.values())
		{
			for (EntourageFigure figure : EntourageFigure.presets())
			{
				assertNotNull(pose + " on " + figure.name(), pose.animationFor(figure));
			}
		}
	}

	@Test
	public void everyPoseHasItsOwnPlayerFacingName()
	{
		Set<String> names = new HashSet<>();
		for (EntouragePose pose : EntouragePose.values())
		{
			String name = pose.toString();
			assertFalse(pose.name() + " has no display name", name.isEmpty());
			assertNotEquals(pose.name() + " is showing its enum constant to the user",
				pose.name(), name);
			assertTrue(pose.name() + " shares a display name with another pose", names.add(name));
		}
	}

	@Test
	public void theDefaultPoseIsTheFiguresOwn()
	{
		assertEquals(EntouragePose.FIGURE_DEFAULT, new FakeConfig().idlePose());
		assertEquals("and it is first in the dropdown",
			EntouragePose.FIGURE_DEFAULT, EntouragePose.values()[0]);
	}
}

package com.matthewmariner.entourage;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.util.Arrays;

/**
 * The one part of the roster panel that is Swing, exercised without a windowing system.
 *
 * <p>Every <em>decision</em> the panel draws is somewhere else and already under test —
 * {@link RosterView} for the cards, {@link RosterEdit} for what a change writes,
 * {@link FigureSearch} for the list. What is left is wiring, and wiring is exactly the part
 * that is invisible to all three and fatal to the feature: a mouse listener attached to the
 * wrong component, an action drawn on a card that must not have one, a control that writes
 * a setting nothing reads.
 *
 * <p><b>Headless throughout.</b> {@code JPanel} and its children construct fine without a
 * display — it is {@code Frame} and {@code Window} that do not — so this runs on a build
 * machine. Nothing here paints, and nothing here touches the client, which is the panel's
 * own rule rather than this test's convenience: {@code PluginManager} drives the real thing
 * from the event dispatch thread, where a client read throws.
 */
public class EntourageRosterPanelTest
{
	private final FakeConfig config = new FakeConfig();

	/**
	 * Knows no names unless a test teaches it one, which is what a cold cache and the login
	 * screen both look like — so every assertion below that reads "NPC 4931" is asserting the
	 * fallback the panel is supposed to draw rather than merely the absence of a feature.
	 */
	private final FakeNpcNames npcNames = new FakeNpcNames();

	/** Remembers what the footer asked to open, since a build machine has no browser. */
	private final FakeLinkOpener links = new FakeLinkOpener();

	/** Built on the event dispatch thread, because that is where the real one is built. */
	private EntourageRosterPanel panel()
	{
		final EntourageRosterPanel[] built = new EntourageRosterPanel[1];
		onSwing(() -> built[0] = new EntourageRosterPanel(config, config, npcNames, links));
		return built[0];
	}

	// --- walking the panel, rather than adding seams to it ---------------------

	private static void collect(Container root, List<Component> into)
	{
		for (Component child : root.getComponents())
		{
			into.add(child);
			if (child instanceof Container)
			{
				collect((Container) child, into);
			}
		}
	}

	private static List<Component> all(Container root)
	{
		List<Component> found = new ArrayList<>();
		collect(root, found);
		return found;
	}

	/** Every piece of text on screen, including the one inside a card's own children. */
	private static List<String> textOf(Container root)
	{
		List<String> text = new ArrayList<>();
		for (Component child : all(root))
		{
			if (child instanceof JLabel)
			{
				text.add(strip(((JLabel) child).getText()));
			}
		}
		return text;
	}

	/**
	 * The muted paragraphs are HTML, because a plain label does not wrap. Comparing against
	 * the markup would make every assertion below a restatement of the layout, so it comes
	 * off here.
	 */
	private static String strip(String label)
	{
		if (label == null)
		{
			return "";
		}

		return label.replaceAll("<[^>]*>", "");
	}

	private static boolean shows(Container root, String text)
	{
		for (String found : textOf(root))
		{
			if (found.contains(text))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Presses everything that has a mouse listener and reads as {@code label} — either
	 * because it is that label or because it contains one.
	 *
	 * @return how many things were pressed, so a test can insist there was exactly one
	 */
	private static int click(Container root, String label)
	{
		final int[] pressed = {0};
		onSwing(() ->
		{
			for (Component child : all(root))
			{
				if (child.getMouseListeners().length == 0 || !reads(child, label))
				{
					continue;
				}
				for (MouseListener listener : child.getMouseListeners())
				{
					listener.mousePressed(new MouseEvent(child, MouseEvent.MOUSE_PRESSED,
						0L, 0, 1, 1, 1, false));
				}
				pressed[0]++;
			}
		});
		return pressed[0];
	}

	private static boolean reads(Component child, String label)
	{
		if (child instanceof JLabel && strip(((JLabel) child).getText()).equals(label))
		{
			return true;
		}

		return child instanceof Container && textOf((Container) child).contains(label);
	}

	/**
	 * The smallest thing on screen that carries {@code label} and can be pressed.
	 *
	 * <p>Found by climbing from the label rather than by searching downwards, because
	 * searching downwards finds the whole body first: every container from the panel outward
	 * "contains" every label, so a match on subtree text alone would press the top of the
	 * tree and hit whichever card happened to be first. Climbing stops at the nearest
	 * ancestor that has a mouse listener, which is the card the label is on.
	 */
	private static Container pressableFor(Container root, String label)
	{
		for (Component child : all(root))
		{
			if (!(child instanceof JLabel) || !strip(((JLabel) child).getText()).equals(label))
			{
				continue;
			}

			for (Component up = child; up != null; up = up.getParent())
			{
				if (up.getMouseListeners().length > 0 && up instanceof Container)
				{
					return (Container) up;
				}
			}
		}

		fail("nothing pressable reads \"" + label + "\"");
		return null;
	}

	/** The row of a labelled control — the one holding the label and its buttons. */
	private static Container rowFor(Container root, String label)
	{
		for (Component child : all(root))
		{
			if (child instanceof JLabel && strip(((JLabel) child).getText()).equals(label))
			{
				return child.getParent();
			}
		}

		fail("no row reads \"" + label + "\"");
		return null;
	}

	private static void press(Component target)
	{
		onSwing(() ->
		{
			for (MouseListener listener : target.getMouseListeners())
			{
				listener.mousePressed(new MouseEvent(target, MouseEvent.MOUSE_PRESSED,
					0L, 0, 1, 1, 1, false));
			}
		});
	}

	/** Presses the card carrying a given title — the whole card is the "change this" target. */
	private static void clickCard(Container root, String title)
	{
		assertEquals("exactly one card reading \"" + title + "\"", 1, click(root, title));
	}

	/** Presses the × on the card carrying a given title. */
	private static void removeCard(Container root, String title)
	{
		Container card = pressableFor(root, title);
		for (Component child : all(card))
		{
			if (child instanceof JLabel && "×".equals(((JLabel) child).getText()))
			{
				press(child);
				return;
			}
		}

		fail("the card reading \"" + title + "\" has no remove action");
	}

	/** How many of the cards on screen offer a remove action. */
	private static int removableCards(Container root)
	{
		int removable = 0;
		for (Component child : all(root))
		{
			if (child instanceof JLabel && "×".equals(((JLabel) child).getText()))
			{
				removable++;
			}
		}
		return removable;
	}

	private static void type(Container root, String query)
	{
		onSwing(() ->
		{
			for (Component child : all(root))
			{
				if (child instanceof IconTextField)
				{
					// RuneLite's own IconTextField.setText asserts it is on this thread, and
					// the test JVM runs with assertions on.
					((IconTextField) child).setText(query);
					return;
				}
			}
			fail("the panel has no search box");
		});
	}

	private static void typeIntoIdBox(Container root, String text)
	{
		onSwing(() ->
		{
			for (Component child : all(root))
			{
				// Not merely "the parent is not an IconTextField": that component nests a
				// FlatTextField around its own JTextField, so the search box's inner field
				// passes that check and swallows the whole test.
				if (!(child instanceof JTextField) || insideTheSearchBox(child))
				{
					continue;
				}

				JTextField field = (JTextField) child;
				field.setText(text);
				for (java.awt.event.ActionListener listener : field.getActionListeners())
				{
					listener.actionPerformed(new java.awt.event.ActionEvent(
						field, java.awt.event.ActionEvent.ACTION_PERFORMED, ""));
				}
				return;
			}
			fail("the picker has no id box");
		});
	}

	/**
	 * Puts text in the id box without pressing Enter — the state of somebody who has typed
	 * a number and is deciding what to do with it.
	 */
	private static void putInIdBox(Container root, String text)
	{
		onSwing(() ->
		{
			for (Component child : all(root))
			{
				if (!(child instanceof JTextField) || insideTheSearchBox(child))
				{
					continue;
				}
				((JTextField) child).setText(text);
				return;
			}
			fail("the picker has no id box");
		});
	}

	/** @return what the picker's id box holds — the number somebody typed, or the slot's. */
	private static String idBoxText(Container root)
	{
		for (Component child : all(root))
		{
			if (child instanceof JTextField && !insideTheSearchBox(child))
			{
				return ((JTextField) child).getText();
			}
		}
		fail("the picker has no id box");
		return null;
	}

	private static boolean insideTheSearchBox(Component child)
	{
		for (Component up = child; up != null; up = up.getParent())
		{
			if (up instanceof IconTextField)
			{
				return true;
			}
		}
		return false;
	}

	@SuppressWarnings("unchecked")
	private static void chooseFormation(Container root, EntourageFormation formation)
	{
		onSwing(() ->
		{
			for (Component child : all(root))
			{
				if (child instanceof JComboBox)
				{
					((JComboBox<EntourageFormation>) child).setSelectedItem(formation);
					return;
				}
			}
			fail("the quick settings have no formation control");
		});
	}

	/** Runs on the event dispatch thread and waits, so a failure inside it is this test's. */
	private static void onSwing(Runnable work)
	{
		try
		{
			SwingUtilities.invokeAndWait(work);
		}
		catch (InvocationTargetException thrown)
		{
			throw thrown.getCause() instanceof AssertionError
				? (AssertionError) thrown.getCause()
				: new AssertionError(thrown.getCause());
		}
		catch (InterruptedException interrupted)
		{
			Thread.currentThread().interrupt();
			throw new AssertionError(interrupted);
		}
	}

	private static void settle()
	{
		onSwing(() ->
		{
		});
	}

