		FakeWorldView boxedIn = scene();
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					boxedIn.block(stuck.dx(dx).dy(dy));
				}
			}
