	/**
	 * <b>The recall is suppressed, and this is the test that stops somebody "fixing" it.</b>
	 *
	 * <p>The recall exists to rescue a follower stranded behind a wall: past
	 * {@code getRecallDistance()} — twelve tiles by default — it is put back on the player's
	 * own tile. Parking the entourage against a wall at God Wars and then walking into the
	 * boss room is far further than twelve tiles, so a freeze that left the recall running
	 * would teleport the whole group into the fight. That is not a bug the feature has to
	 * tolerate; it is the feature inverted.
	 *
	 * <p>Written at four times the recall distance so that no plausible change to the
	 * threshold makes this pass by accident.
	 */
	@Test
	public void aParkedFollowerIsNeverRecalledHoweverFarThePlayerGoes()
	{
		FakeWorldView view = scene();
		FollowerWalk walk = new FollowerWalk(START);
		EntourageSettings settings = parked();

		WorldPoint faraway = START.dx(settings.getRecallDistance() * 4);
		for (int tick = 0; tick < 20; tick++)
		{
			walk.tick(faraway, view, settings);
		}

		assertEquals("it stayed where it was parked", START, walk.currentTile());
		assertTrue("and the player really is well past the recall distance",
			faraway.distanceTo(START) > settings.getRecallDistance());
	}

	/**
	 * And the same follower, unparked, <i>is</i> recalled — because at that distance a recall
	 * is exactly the right thing. Without this the test above would also pass on a walk that
	 * had simply lost the ability to recall at all.
	 */
	@Test
	public void thatSameFollowerIsRecalledTheMomentItIsUnparked()
	{
		FakeWorldView view = scene();
		FollowerWalk walk = new FollowerWalk(START);

		WorldPoint faraway = START.dx(FakeConfig.defaults().getRecallDistance() * 4);
		walk.tick(faraway, view, parked());
		assertEquals(START, walk.currentTile());

		walk.tick(faraway, view, defaults());

		assertEquals("unparked, a follower that far behind is put back on the player",
			faraway, walk.currentTile());
	}

	/**
	 * <b>Parking mid-stride ends on a whole tile, not half of one.</b> The step in flight is
	 * closed out at the top of the tick — the drawn position has caught up with the tile it
	 * was walking to — so there is no half-played walk cycle and nothing to slide.
	 */
	@Test
	public void parkingMidWalkFinishesTheTileItWasWalkingToAndStops()
	{
		FakeWorldView view = scene();
		FollowerWalk walk = new FollowerWalk(START);

		walk.tick(START.dx(6), view, collinear());
		assertTrue("the fixture needs it to actually be walking", walk.isMoving());
		WorldPoint midStride = walk.currentTile();

		walk.tick(START.dx(6), view, new FakeConfig()
			.setFormation(EntourageFormation.LEFT).setStayPut(true).settings());

		assertEquals("it kept the tile it was walking to", midStride, walk.currentTile());
		assertFalse("and it is standing, which is what selects the idle pose",
			walk.isMoving());
		assertEquals("with nothing left to interpolate", walk.currentTile(),
			walk.stepStartTile());
	}

	/**
	 * <b>The heading is still tracked while parked.</b> A group parked while the player walks
	 * a lap of the room has to form up on the right side of them the moment it is unparked —
	 * not on a heading from whenever it was parked, which would put the whole formation
	 * behind the wrong shoulder for one tick.
	 */
	@Test
	public void aParkedFollowerStillWatchesWhichWayThePlayerIsGoing()
	{
		FakeWorldView view = scene();
		FollowerWalk walk = new FollowerWalk(START);
		EntourageSettings settings = parked();

		// The player walks west, twice, so there are two consecutive observations to take a
		// heading from.
		walk.tick(START.dx(-1), view, settings);
		walk.tick(START.dx(-2), view, settings);

		assertEquals("westward", -1, walk.getHeadingX());
		assertEquals(0, walk.getHeadingY());
		assertEquals("and it still has not moved", START, walk.currentTile());
	}

	/** Unparking puts it back on its station through the ordinary follow. */
	@Test
	public void unparkingResumesTheOrdinaryWalk()
	{
		FakeWorldView view = scene();
		FollowerWalk walk = new FollowerWalk(START);

		walk.tick(START.dx(3), view, new FakeConfig()
			.setFormation(EntourageFormation.LEFT).setStayPut(true).settings());
		assertEquals(START, walk.currentTile());

		WorldPoint station = walk.stationTile(START.dx(3), collinear());
		for (int tick = 0; tick < 10; tick++)
		{
			walk.tick(START.dx(3), view, collinear());
		}

		assertEquals("it walked back to where it belongs", station, walk.currentTile());
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Who speaks, when, and how many at once.
 *
 * <p>The followers here are real ones bound to real {@code RuneLiteObject}s, because the
 * pass turns on {@link Follower#isActive()} — which asks the client — and a fake that
 * answered from its own bookkeeping would make "a follower nobody can see is silent"
 * untestable.
 */
public class EntourageChatterTest
{
	private static final WorldPoint STANDING = new WorldPoint(3221, 3218, 0);

	private FakeClient client;
	private FakeWorldView view;

	@Before
	public void setUp()
	{
		client = new FakeClient().withRosterNpcs();
		view = FakeWorldView.around(STANDING);
		client.setTopLevelWorldView(view);
	}

	/** A follower that is spawned and standing on screen, first in the roster. */
	private Follower spawned(EntourageFigure figure)
	{
		return spawned(figure, 0);
	}

	/** The same, in a named roster position — which is what staggers whose turn it is. */
	private Follower spawned(EntourageFigure figure, int index)
	{
		Follower follower = new Follower(client, FollowerBody.preset(figure), index, STANDING);
		FollowerAnchor anchor = FollowerAnchor.of(FakePlayer.standingOn(view, STANDING), view);
		follower.onGameTick(anchor, view, FakeConfig.defaults());
		assertTrue("the fixture has to actually spawn", follower.isActive());
		return follower;
	}

	/** Five followers, numbered as the scene numbers them. */
	private List<Follower> fullRoster(EntourageFigure... figures)
	{
		List<Follower> roster = new ArrayList<>(figures.length);
		for (int index = 0; index < figures.length; index++)
		{
			roster.add(spawned(figures[index], index));
		}
		return roster;
	}

	private static EntourageSettings settings()
	{
		return FakeConfig.defaults();
	}

	@Test
	public void aFollowerOnScreenSaysSomethingWithinOneInterval()
	{
		Follower follower = spawned(EntourageFigure.VANNAKA);
		List<Follower> roster = Collections.singletonList(follower);
		EntourageChatter chatter = new EntourageChatter();
		EntourageSettings settings = settings();

		String said = null;
		for (int tick = 0; tick < settings.getDialogueIntervalTicks() + 1 && said == null; tick++)
		{
			chatter.onGameTick(roster, settings);
			said = follower.getRemarks().text();
		}

		assertNotNull("a follower that never speaks is a feature that does nothing", said);
		assertTrue("and what it said is one of Vannaka's own lines: " + said,
			FigureLines.of(EntourageFigure.VANNAKA).contains(said));
	}

	@Test
	public void aLineStaysUpForTheDwellAndThenClears()
	{
		Follower follower = spawned(EntourageFigure.ROGUE);
		List<Follower> roster = Collections.singletonList(follower);
		EntourageChatter chatter = new EntourageChatter();
		EntourageSettings settings = settings();

		int spokeAt = tickUntilTalking(chatter, roster, settings);
		String line = follower.getRemarks().text();

		for (int i = 1; i < settings.getDialogueDwellTicks(); i++)
		{
			chatter.onGameTick(roster, settings);
			assertEquals("the line must not change mid-dwell", line, follower.getRemarks().text());
		}

		chatter.onGameTick(roster, settings);

		assertFalse("a line that outlasts its dwell is a label, not a remark",
			follower.getRemarks().isTalking());
		assertTrue("this test needs the line to have gone up at all", spokeAt > 0);
	}

	/**
	 * <b>The hard off switch clears what is up rather than merely stopping the next
	 * one.</b> The difference is "off" against "off in a minute", which is the complaint
	 * this whole feature is shaped around avoiding.
	 */
	@Test
	public void theOffSwitchEmptiesWhateverIsAlreadyOnScreen()
	{
		Follower follower = spawned(EntourageFigure.ROGUE);
		List<Follower> roster = Collections.singletonList(follower);
		EntourageChatter chatter = new EntourageChatter();

		tickUntilTalking(chatter, roster, settings());

		int talking = chatter.onGameTick(roster, new FakeConfig().setDialogue(false).settings());

		assertEquals(0, talking);
		assertFalse(follower.getRemarks().isTalking());
		assertNull(follower.getRemarks().text());
	}

	/**
	 * <b>Two claims, and the second one needs more than a tick.</b> A line already up on a
	 * follower that has left the screen is cleared, and — this is the half a single tick
	 * cannot show — one that has left the screen never starts a new line either. The first
	 * version of this test ticked once, which is a tick the follower was almost certainly
	 * not due on: deleting the {@code isActive()} check from the pass that starts lines
	 * left it green.
	 */
	@Test
	public void aFollowerThatIsNotOnScreenNeitherSpeaksNorKeepsALine()
	{
		Follower follower = spawned(EntourageFigure.ROGUE);
		List<Follower> roster = Collections.singletonList(follower);
		EntourageChatter chatter = new EntourageChatter();
		EntourageSettings settings = settings();

		tickUntilTalking(chatter, roster, settings);

		// Taken off the screen, and then the line put back by hand — so that the only
		// thing between a stale line and text drawn over empty ground is the chatter's own
		// isActive() check. That despawn() clears the line itself is a separate promise,
		// pinned in FollowerTest; without this the two would be indistinguishable.
		follower.despawn();
		assertFalse("the fixture has to actually despawn it", follower.isActive());
		follower.getRemarks().say(0, 1000, FigureLines.of(EntourageFigure.ROGUE));
		assertTrue("and the line has to be back up", follower.getRemarks().isTalking());

		int talking = chatter.onGameTick(roster, settings);

		assertEquals(0, talking);
		assertFalse("a figure the client is not drawing is not saying anything",
			follower.getRemarks().isTalking());

		// Long enough to cover several of its turns to speak, so "it was not due" cannot
		// be why it stayed quiet.
		for (int tick = 0; tick < settings.getDialogueIntervalTicks() * 3; tick++)
		{
			assertEquals("a figure nobody can see must not start talking either",
				0, chatter.onGameTick(roster, settings));
			assertFalse(follower.getRemarks().isTalking());
		}
	}

	/**
	 * <b>The cap, which is the reason this class exists.</b> Written against the full
	 * roster of five, at the tightest cadence the settings allow, where each of them wants
	 * to be talking for nine ticks in every ten and an overlap is a certainty rather than a
	 * possibility. Without a cap this is five lines stacked over five heads standing within
	 * two tiles of each other — the wall of text {@code ../lively-cities} shipped a dial to
	 * prevent.
	 *
	 * <p><b>Five rather than the two this used to use.</b> Two followers is a fixture that
	 * cannot tell a cap of one from a cap of two, and a cap of two at five followers is a
	 * pair of lines drawn over adjacent heads — which is the failure the cap is for. The
	 * roster is also numbered 0..4, as the scene numbers it, because that is what staggers
	 * whose turn it is; a fixture that built five followers all at index zero would be
	 * measuring a much easier problem.
	 *
	 * <p><b>The number below is a literal, and that is the whole point of an earlier
	 * revision.</b> It used to read {@code talking <= EntourageChatter.MAX_CONCURRENT_LINES}
	 * — an assertion that takes its expected value from the constant it is checking, so it
	 * proves the implementation honours whatever the constant says and nothing about what
	 * the constant says. Setting {@code MAX_CONCURRENT_LINES} to 99 left it green: two
	 * followers talking over each other, the wall of text on screen, and a test named for
	 * preventing exactly that passing. A literal cannot be moved by the mutation it exists
	 * to catch. The same reasoning is why {@code EntourageSceneTest.ROSTER_SIZE} is written
	 * out rather than derived.
	 */
	@Test
	public void neverMoreThanOneFollowerIsTalkingAtOnce()
	{
		List<Follower> roster = fullRoster(EntourageFigure.ROGUE, EntourageFigure.HANS,
			EntourageFigure.VANNAKA, EntourageFigure.PIRATE, EntourageFigure.TURAEL);
		EntourageChatter chatter = new EntourageChatter();

		EntourageSettings tightest = new FakeConfig()
			.setDialogueIntervalTicks(EntourageSettings.MIN_DIALOGUE_INTERVAL_TICKS)
			.setDialogueDwellTicks(EntourageSettings.MAX_DIALOGUE_DWELL_TICKS)
			.settings();

		assertTrue("this fixture needs a dwell that fills most of the interval",
			tightest.getDialogueDwellTicks() >= tightest.getDialogueIntervalTicks() - 1);

		int spoke = 0;
		for (int tick = 0; tick < 500; tick++)
		{
			int talking = chatter.onGameTick(roster, tightest);

			// A literal, not the constant — see the javadoc.
			assertTrue("two followers were talking at once at tick " + tick, talking <= 1);

			int actuallyUp = 0;
			for (Follower follower : roster)
			{
				if (follower.getRemarks().isTalking())
				{
					actuallyUp++;
				}
			}

			// This one is data-driven on purpose: the claim is that the count handed back
			// is the count on screen, whatever either of them is.
			assertEquals("the count returned has to be the count on screen", talking, actuallyUp);
			assertTrue("and two lines are two lines however they were counted", actuallyUp <= 1);
			spoke += talking;
		}

		assertTrue("this fixture has to produce some talking to be measuring anything", spoke > 0);
	}

	/**
	 * <b>What the cap is set to, pinned separately and with a literal.</b>
	 *
	 * <p>The test above says "at most one follower talks" as a fact about behaviour; this
	 * says the shipped constant agrees with it. Raising the cap is a perfectly reasonable
	 * thing to do when the roster grows — it should just be a deliberate act that turns
	 * two tests red and makes somebody re-read what the behavioural one is asserting,
	 * rather than a one-character edit that quietly widens a guarantee.
	 *
	 * <p><b>This assertion alone would not be enough.</b> A {@code static final int} is a
	 * compile-time constant, so its value is inlined into this class file at compilation,
	 * and whether a mutation of it can reach here at all depends on the build recompiling
	 * the test source set — a property of Gradle rather than of the code. Measured rather
	 * than assumed: setting the constant to 99 and running {@code ./gradlew test} does
	 * turn this red, so the incremental compiler does recompile dependents when a constant
	 * changes. The behavioural literal above has no such dependency either way — it fails
	 * because two figures are talking, not because a number moved.
	 */
	@Test
	public void theShippedCapIsOneVoiceAtATime()
	{
		assertEquals(1, EntourageChatter.MAX_CONCURRENT_LINES);
	}

	/**
	 * Every follower gets turns rather than the first in the list holding the slot forever.
	 *
	 * <p>With a cap of one and five followers, the way this goes wrong is not subtle: if
	 * their turns to speak fell on the same tick, follower zero would win the pass every
	 * time and the other four would be figures with no dialogue for the whole session.
	 * That is what {@code FollowerRemarks}' per-position stagger is for, and this is where
	 * it is checked end to end.
	 */
	@Test
	public void theCapDoesNotBelongToWhicheverFollowerIsFirstInTheRoster()
	{
		List<Follower> roster = fullRoster(EntourageFigure.ROGUE, EntourageFigure.HANS,
			EntourageFigure.VANNAKA, EntourageFigure.PIRATE, EntourageFigure.TURAEL);
		EntourageChatter chatter = new EntourageChatter();
		EntourageSettings settings = settings();

		boolean[] spoke = new boolean[roster.size()];
		for (int tick = 0; tick < settings.getDialogueIntervalTicks() * 8; tick++)
		{
			chatter.onGameTick(roster, settings);
			for (int index = 0; index < roster.size(); index++)
			{
				spoke[index] |= roster.get(index).getRemarks().isTalking();
			}
		}

		for (int index = 0; index < spoke.length; index++)
		{
			assertTrue("follower " + index + " never gets a word in", spoke[index]);
		}
	}

	/**
	 * <b>And the same, for the roster a user can build by accident: five copies of one
	 * figure.</b> The line stream and the stagger are seeded from the figure's name, so
	 * five Rogues are five identical seeds unless the roster position is mixed in — and
	 * then the cap of one means follower zero speaks forever and the other four never do.
	 * The test above cannot see it, because its five figures are five different names.
	 */
	@Test
	public void fiveCopiesOfOneFigureStillTakeTurns()
	{
		List<Follower> roster = fullRoster(EntourageFigure.ROGUE, EntourageFigure.ROGUE,
			EntourageFigure.ROGUE, EntourageFigure.ROGUE, EntourageFigure.ROGUE);
		EntourageChatter chatter = new EntourageChatter();
		EntourageSettings settings = settings();

		boolean[] spoke = new boolean[roster.size()];
		for (int tick = 0; tick < settings.getDialogueIntervalTicks() * 8; tick++)
		{
			chatter.onGameTick(roster, settings);
			for (int index = 0; index < roster.size(); index++)
			{
				spoke[index] |= roster.get(index).getRemarks().isTalking();
			}
		}

		for (int index = 0; index < spoke.length; index++)
		{
			assertTrue("copy " + index + " of the same figure never gets a word in", spoke[index]);
		}
	}

	/**
	 * The custom-lines box replaces the presets — the choice is documented on
	 * {@link EntourageSettings#linesFor} and this is where it is enforced end to end.
	 */
	@Test
	public void aFollowerSaysTheUsersOwnLinesWhenThereAreSome()
	{
		Follower follower = spawned(EntourageFigure.VANNAKA);
		List<Follower> roster = Collections.singletonList(follower);
		EntourageChatter chatter = new EntourageChatter();
		// One line, so the assertion is about replacement rather than about which of
		// several was drawn. What a comma does to that box is pinned in
		// EntourageSettingsTest.
		EntourageSettings mine = new FakeConfig()
			.setDialogueLines("Mind the step")
			.settings();

		tickUntilTalking(chatter, roster, mine);

		assertEquals("Mind the step", follower.getRemarks().text());
		assertFalse("and not one of the figure's own",
			FigureLines.of(EntourageFigure.VANNAKA).contains(follower.getRemarks().text()));
	}

	@Test
	public void theCadenceIsTheIntervalSetting()
	{
		Follower follower = spawned(EntourageFigure.ROGUE);
		List<Follower> roster = Collections.singletonList(follower);
		EntourageChatter chatter = new EntourageChatter();

		EntourageSettings brisk = new FakeConfig()
			.setDialogueIntervalTicks(20)
			.setDialogueDwellTicks(EntourageSettings.MIN_DIALOGUE_DWELL_TICKS)
			.settings();

		int lines = 0;
		String previous = null;
		for (int tick = 0; tick < 400; tick++)
		{
			chatter.onGameTick(roster, brisk);
			String now = follower.getRemarks().text();
			if (now != null && !now.equals(previous))
			{
				lines++;
			}
			previous = now;
		}

		assertEquals("four hundred ticks at one line per twenty is twenty lines", 20, lines);
	}

	/**
	 * A scene load starts a fresh phase and leaves nothing on screen. Without the reset a
	 * follower would inherit a cadence from the world it was in before, and — worse — a
	 * line said in it.
	 */
	@Test
	public void resettingForgetsBothTheClockAndTheLine()
	{
		Follower follower = spawned(EntourageFigure.ROGUE);
		List<Follower> roster = Collections.singletonList(follower);
		EntourageChatter chatter = new EntourageChatter();

		tickUntilTalking(chatter, roster, settings());
		assertTrue(chatter.getTick() > 0);

		chatter.reset(roster);

		assertEquals(0, chatter.getTick());
		assertFalse(follower.getRemarks().isTalking());
	}

	private static int tickUntilTalking(EntourageChatter chatter, List<Follower> roster,
		EntourageSettings settings)
	{
		for (int tick = 1; tick <= settings.getDialogueIntervalTicks() * 4; tick++)
		{
			chatter.onGameTick(roster, settings);
			if (roster.get(0).getRemarks().isTalking())
			{
				return tick;
			}
		}

		throw new AssertionError("the fixture never produced a line to work with");
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.Animation;
import net.runelite.api.GameState;
import net.runelite.api.IndexDataBase;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;

/**
 * A client that keeps the registered-object list and the model cache in fields.
 *
 * <p>This is what makes the lifecycle testable without a game running. In 1.12.38
 * (verified by disassembling the API jar) {@code RuneLiteObject} is not a black box:
 * {@code isActive()} is exactly {@code client.isRuneLiteObjectRegistered(this)} and
 * {@code setActive(b)} is exactly {@code client.registerRuneLiteObject(this)} /
 * {@code removeRuneLiteObject(this)}. So a {@link Set} standing in for the client's list
 * turns "did teardown actually deactivate anything?" into an assertion, and the objects
 * under test are real {@code RuneLiteObject}s running their real code.
 *
 * <p>Everything this plugin does not call is inherited from {@link StubClient} and
 * throws.
 *
 * <p>{@link #getNpcDefinition(int)} is modelled on the real one's <i>failure</i> shape
 * rather than on convenience — an unknown id throws. See that method.
 */
final class FakeClient extends StubClient
{
	/** Stands in for the client's registered-object list. */
	private final Set<RuneLiteObjectController> registered = new LinkedHashSet<>();

	/** Model ids that resolve to nothing, whatever the cache is doing. */
	private final Set<Integer> unloadableModels = new HashSet<>();

	/** Animation ids that resolve to nothing. */
	private final Set<Integer> unloadableAnimations = new HashSet<>();

	/**
	 * Animation ids whose load blows up rather than returning null.
	 *
	 * <p>{@code new AnimationController(client, id)} calls {@code client.loadAnimation}
	 * straight through, so this is a real path by which a throw reaches
	 * {@code Follower.onGameTick} from outside its own try/catch — which is what
	 * {@code EntourageSceneTest} needs in order to prove the scene's pass survives one.
	 */
	private final Set<Integer> throwingAnimations = new HashSet<>();

	/** NPC compositions this client knows about, keyed by id. */
	private final Map<Integer, NPCComposition> npcCompositions = new HashMap<>();

	/** NPC ids whose lookup returns null rather than throwing. */
	private final Set<Integer> nullNpcCompositions = new HashSet<>();

	/** Animation ids that were asked for, in order. */
	private final List<Integer> animationsLoaded = new ArrayList<>();

	/** Model ids that were asked for, in order. */
	private final List<Integer> modelsLoaded = new ArrayList<>();

	/** NPC ids that were asked about, in order. */
	private final List<Integer> npcDefinitionsRequested = new ArrayList<>();

	/** True while the cache is pretending to be cold: models, animations and NPCs miss. */
	private boolean cacheCold;

	/** Accepts the register call and does nothing with it. */
	private boolean refuseRegistration;

	/** Throws out of {@code removeRuneLiteObject}, leaving the object registered. */
	private boolean throwFromRemoval;

	/** Throws out of {@code isRuneLiteObjectRegistered}. */
	private boolean throwFromRegistrationCheck;

	private FakeRuneLiteObject lastObject;
	private FakeModelData lastMerged;
	private int mergeCalls;
	private int lastMergePartCount;

	private int gameCycle;
	private GameState gameState = GameState.LOGGED_IN;

	@Nullable
	private Player localPlayer;

	@Nullable
	private WorldView topLevelWorldView;

	// --- The registered-object list ------------------------------------------

	@Override
	public RuneLiteObject createRuneLiteObject()
	{
		lastObject = new FakeRuneLiteObject(this);
		return lastObject;
	}

	/** @return the most recently created object, for the tests that ask it what happened */
	FakeRuneLiteObject lastObject()
	{
		return lastObject;
	}

	@Override
	public void registerRuneLiteObject(RuneLiteObjectController controller)
	{
		if (refuseRegistration)
		{
			return;
		}
		registered.add(controller);
	}

	@Override
	public void removeRuneLiteObject(RuneLiteObjectController controller)
	{
		removalAttempts++;
		if (throwFromRemoval)
		{
			throw new IllegalStateException("the client will not let go of this object");
		}
		registered.remove(controller);
	}

	/**
	 * @return how many times anything asked the client to deactivate an object,
	 * successful or not.
	 *
	 * <p>Counted because "we gave up trying" is otherwise unobservable. A retirement that
	 * could not let go of its object has to stop retrying — a scene which noticed the
	 * same figure mismatch on every tick would attempt a deactivation, and log a warning,
	 * 100 times a minute for the rest of the session — and the only trace of the latch
	 * that stops it is the call that does not happen.
	 */
	int removalAttempts()
	{
		return removalAttempts;
	}

	private int removalAttempts;

	@Override
	public boolean isRuneLiteObjectRegistered(RuneLiteObjectController controller)
	{
		if (throwFromRegistrationCheck)
		{
			throw new IllegalStateException("the client will not say whether it has this object");
		}
		return registered.contains(controller);
	}

	/** @return how many objects the client currently has registered */
	int registeredCount()
	{
		return registered.size();
	}

	/** The client takes {@code setActive(true)} and does not register the object. */
	FakeClient refusingRegistration()
	{
		refuseRegistration = true;
		return this;
	}

	/**
	 * {@code setActive(false)} blows up and the object stays registered — the state in
	 * which forgetting a follower leaks the object it was holding. No realistic in-client
	 * trigger for this is known; it is here because the teardown promise is unconditional,
	 * and a promise nothing can falsify is not one.
	 */
	FakeClient refusingDeactivation()
	{
		throwFromRemoval = true;
		return this;
	}

	/** The client will not even say whether it has an object. */
	FakeClient withThrowingRegistrationChecks()
	{
		throwFromRegistrationCheck = true;
		return this;
	}

	// --- The model and animation cache ---------------------------------------

	@Override
	@Nullable
	public ModelData loadModelData(int id)
	{
		modelsLoaded.add(id);
		return cacheCold || unloadableModels.contains(id) ? null : new FakeModelData();
	}

	@Override
	@Nullable
	public ModelData mergeModels(ModelData[] parts, int count)
	{
		mergeCalls++;
		lastMergePartCount = count;
		lastMerged = new FakeModelData();
		return lastMerged;
	}

	@Override
	@Nullable
	public Animation loadAnimation(int id)
	{
		animationsLoaded.add(id);

		if (throwingAnimations.contains(id))
		{
			throw new IllegalStateException("animation " + id + " blew up on the way out of the cache");
		}

		return cacheCold || unloadableAnimations.contains(id) ? null : new FakeAnimation(id);
	}

	/**
	 * {@code Client.getNpcDefinition(int)} as 1.12.38 actually behaves.
	 *
	 * <p>Three outcomes, and each is one this plugin has to cope with:
	 * <ul>
	 *   <li><b>Known id</b> — the composition that was registered.</li>
	 *   <li><b>Explicitly null</b> — see {@link #withNullNpcComposition}. The accessor is
	 *       a cache read, so a null is possible even though it is not the usual
	 *       failure.</li>
	 *   <li><b>Anything else, including while the cache is cold</b> — throws. That is the
	 *       real path for an id whose archive entry is absent: the composition
	 *       constructor is handed a null buffer inside the client's own
	 *       {@code catch (RuntimeException)} and rethrown wrapped. A permissive fake here
	 *       would make {@link FollowerAppearance}'s try/catch dead code that no test
	 *       could tell from an empty method body.</li>
	 * </ul>
	 */
	@Override
	@Nullable
	public NPCComposition getNpcDefinition(int id)
	{
		npcDefinitionsRequested.add(id);

		if (nullNpcCompositions.contains(id))
		{
			return null;
		}

		NPCComposition composition = cacheCold ? null : npcCompositions.get(id);
		if (composition == null)
		{
			throw new IllegalStateException("no NPC composition for id " + id);
		}
		return composition;
	}

	FakeClient withNpc(int id, NPCComposition composition)
	{
		npcCompositions.put(id, composition);
		return this;
	}

	/** Registers a working composition for every figure in the roster. */
	FakeClient withRosterNpcs()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			withNpc(figure.getNpcId(), FakeNpcComposition.of(figure.name(), 100 + figure.ordinal()));
		}
		return this;
	}

	FakeClient withNullNpcComposition(int id)
	{
		nullNpcCompositions.add(id);
		return this;
	}

	FakeClient withUnloadableModels(int... ids)
	{
		for (int id : ids)
		{
			unloadableModels.add(id);
		}
		return this;
	}

	FakeClient withUnloadableAnimations(int... ids)
	{
		for (int id : ids)
		{
			unloadableAnimations.add(id);
		}
		return this;
	}

	void clearUnloadableAnimations()
	{
		unloadableAnimations.clear();
	}

	FakeClient withThrowingAnimations(int... ids)
	{
		for (int id : ids)
		{
			throwingAnimations.add(id);
		}
		return this;
	}

	// --- The config index ----------------------------------------------------

	/**
	 * The config index, or {@code null} — which is what the real client answers before
	 * one is up, and is therefore the honest default for a client nobody has logged into.
	 * A test that wants {@link NpcArchive} to get anywhere has to say so.
	 */
	@Nullable
	private FakeIndexDataBase indexConfig;

	private boolean throwFromIndexConfig;

	@Override
	@Nullable
	public IndexDataBase getIndexConfig()
	{
		if (throwFromIndexConfig)
		{
			throw new IllegalStateException("the config index is not available");
		}
		return indexConfig;
	}

	FakeClient withIndexConfig(FakeIndexDataBase index)
	{
		this.indexConfig = index;
		return this;
	}

	FakeClient withThrowingIndexConfig()
	{
		throwFromIndexConfig = true;
		return this;
	}

	/**
	 * {@code Perspective.getTileHeight} asks the client for the world view by id, so
	 * this is a throw that reaches the frame pass from inside
	 * {@code RuneLiteObject.setLocation}.
	 */
	FakeClient withThrowingWorldViewLookup()
	{
		throwFromGetWorldView = true;
		return this;
	}

	private boolean throwFromGetWorldView;

	/** Nothing at all comes out of the cache, which is a cold login. */
	void setCacheCold(boolean cold)
	{
		cacheCold = cold;
	}

	List<Integer> animationsLoaded()
	{
		return animationsLoaded;
	}

	List<Integer> modelsLoaded()
	{
		return modelsLoaded;
	}

	List<Integer> npcDefinitionsRequested()
	{
		return npcDefinitionsRequested;
	}

	int mergeCalls()
	{
		return mergeCalls;
	}

	int lastMergePartCount()
	{
		return lastMergePartCount;
	}

	@Nullable
	FakeModelData lastMerged()
	{
		return lastMerged;
	}

	// --- The world -----------------------------------------------------------

	/**
	 * {@code RuneLiteObject.setLocation} runs
	 * {@code Perspective.getTileHeight(client, ..)}, which asks the client for the world
	 * view by id and returns height 0 when there is none. Null is therefore the honest
	 * answer for a scene that only exists as numbers, and it keeps the real
	 * {@code setLocation} on its real code path.
	 */
	@Override
	@Nullable
	public WorldView getWorldView(int id)
	{
		if (throwFromGetWorldView)
		{
			throw new IllegalStateException("the scene is being swapped out from under you");
		}
		return null;
	}

	@Override
	@Nullable
	public WorldView getTopLevelWorldView()
	{
		return topLevelWorldView;
	}

	void setTopLevelWorldView(@Nullable WorldView worldView)
	{
		this.topLevelWorldView = worldView;
	}

	@Override
	@Nullable
	public Player getLocalPlayer()
	{
		return localPlayer;
	}

	void setLocalPlayer(@Nullable Player player)
	{
		this.localPlayer = player;
	}

	@Override
	public GameState getGameState()
	{
		return gameState;
	}

	/**
	 * Public and {@code @Override} because {@code Client} declares it — the real client
	 * has a setter here too, and a package-private one would be a narrowing.
	 */
	@Override
	public void setGameState(GameState gameState)
	{
		this.gameState = gameState;
	}

	/**
	 * The client's 20ms clock. An {@code int} on purpose — it is one in the API, and the
	 * plugin's fraction arithmetic has to survive it wrapping.
	 */
	@Override
	public int getGameCycle()
	{
		return gameCycle;
	}

	void setGameCycle(int gameCycle)
	{
		this.gameCycle = gameCycle;
	}

	void advanceGameCycle(int clientTicks)
	{
		gameCycle += clientTicks;
	}
}

package com.matthewmariner.entourage;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The one overlay, and the two bug classes its shape is meant to make impossible: text
 * floating with nobody under it, and text drifting off the figure it belongs to.
 *
 * <p>Both come from a renderer with its own list of what to draw and its own idea of
 * where, so both are tested here as claims about the loop — it walks the live roster, it
 * asks the client whether each follower is still registered, and it re-projects the
 * object's own position every frame.
 *
 * <p><b>The projection is a seam, and it has to be.</b>
 * {@code Perspective.getCanvasTextLocation} reads the live camera, and this repo has no
 * mocking framework and does not use reflection. {@link RecordingOverlay} overrides it.
 * The one test that does <i>not</i> override it is
 * {@link #aProjectionThatFailsDrawsNothingRatherThanThrowing()}, which runs the real
 * {@code Perspective} call against {@link FakeClient} — whose {@code getWorldView(int)}
 * returns null, exactly as the real client's does for a view that has gone.
 *
 * <p><b>The font is a seam for a different reason:</b> {@link DialogueFont#getFont()}
 * reaches {@code FontManager}, whose static initialiser registers three TrueType faces
 * with the local graphics environment and lists a directory under the user's home. That
 * is not something a unit test should set off, so the mapping of three constants onto
 * three faces is the one piece of this feature only a live client can confirm.
 */
public class EntourageOverlayTest
{
	private static final WorldPoint STANDING = new WorldPoint(3221, 3218, 0);

	/** Where {@link RecordingOverlay} pretends the camera puts the text. */
	private static final Point PROJECTED = new Point(100, 200);

	private FakeClient client;
	private FakeWorldView view;
	private FakeConfig config;
	private EntourageScene scene;
	private Graphics2D graphics;

	@Before
	public void setUp()
	{
		client = new FakeClient().withRosterNpcs();
		view = FakeWorldView.around(STANDING);
		client.setTopLevelWorldView(view);
		client.setLocalPlayer(FakePlayer.standingOn(view, STANDING));
		config = new FakeConfig();
		scene = new EntourageScene(client, config);

		// A real Graphics2D off a 1x1 image: getFontMetrics() has to work, and a stub
		// Graphics2D would be four hundred throwing methods for no gain.
		graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	/** One follower, spawned and standing on screen. */
	private Follower spawn()
	{
		scene.onGameTick();
		assertEquals("the fixture has to actually spawn something", 1, client.registeredCount());
		return scene.getFollowers().get(0);
	}

	private static void say(Follower follower, String line)
	{
		follower.getRemarks().say(0, Integer.MAX_VALUE, Collections.singletonList(line));
		assertEquals(line, follower.getRemarks().text());
	}

	@Test
	public void aTalkingFollowerGetsOneLineAndASilentOneGetsNothing()
	{
		Follower follower = spawn();
		RecordingOverlay overlay = new RecordingOverlay();

		overlay.render(graphics);
		assertTrue("a follower with nothing to say draws nothing", overlay.drawn.isEmpty());

		say(follower, "Busy today.");
		overlay.render(graphics);

		assertEquals(1, overlay.drawn.size());
		assertEquals("Busy today.", overlay.drawn.get(0));
	}

	/**
	 * The hard off switch on the frame path. Checked here as well as in
	 * {@link EntourageChatter} so that unticking the box empties the screen on the same
	 * frame rather than on the next game tick, up to 600ms later.
	 */
	@Test
	public void theOffSwitchStopsTheOverlayDrawingAnything()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);
		assertEquals("the fixture has to draw something first", 1, overlay.drawn.size());

		config.setDialogue(false);
		overlay.drawn.clear();
		overlay.projections = 0;
		overlay.render(graphics);

		assertTrue("nothing may be drawn with overhead lines off", overlay.drawn.isEmpty());
		assertEquals("and nothing may even be projected — the check is the first line",
			0, overlay.projections);
	}

	@Test
	public void theNameLabelIsTheFiguresOwnName()
	{
		config.setFigure(EntourageFigure.VANNAKA).setDialogue(false).setNameLabel(true);
		spawn();

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(1, overlay.drawn.size());
		assertEquals(EntourageFigure.VANNAKA.getDisplayName(), overlay.drawn.get(0));
	}

	/**
	 * <b>A typed NPC id is named after that NPC.</b> The name label is the only
	 * confirmation the custom-id feature has that a user can see without opening a log —
	 * the NPC's own name over the figure means the id took, and the dropdown figure's name
	 * means it was refused.
	 */
	@Test
	public void theNameLabelOfACustomBodyIsTheNpcsOwnName()
	{
		client.withNpc(4931, FakeNpcComposition.of("Cave goblin guard", 60_001))
			.withIndexConfig(new FakeIndexDataBase()
				.withNpc(4931, NpcRecordBytes.record().standing(5101).walking(5102).end()));
		config.setCustomNpcId(4931).setDialogue(false).setNameLabel(true);
		spawn();

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(1, overlay.drawn.size());
		assertEquals("Cave goblin guard", overlay.drawn.get(0));
	}

	/**
	 * <b>The loop walks the whole roster, not the first of it.</b> Until there were five
	 * followers this was unfalsifiable: with one on screen, a render that drew
	 * {@code followers.get(0)} and returned is indistinguishable from one that iterates.
	 * Five different figures with the name label on is five different strings, so a loop
	 * that stopped early both draws too few and draws the wrong set.
	 */
	@Test
	public void everyFollowerInTheRosterIsDrawnRatherThanJustTheFirst()
	{
		EntourageFigure[] roster = {
			EntourageFigure.ROGUE, EntourageFigure.HANS, EntourageFigure.VANNAKA,
			EntourageFigure.PIRATE, EntourageFigure.TURAEL
		};
		config.setRoster(roster).setDialogue(false).setNameLabel(true);

		scene.onGameTick();
		assertEquals("the fixture has to spawn all five", 5, client.registeredCount());

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(5, overlay.drawn.size());
		for (int index = 0; index < roster.length; index++)
		{
			assertEquals("follower " + index + "'s name is missing or out of order",
				roster[index].getDisplayName(), overlay.drawn.get(index));
		}
	}

	/**
	 * <b>The two switches are two switches.</b> The early return only fires when
	 * <i>both</i> are off, so with the name label on and dialogue off there is a live
	 * follower, a live overlay, and a line that must not be drawn — which is the one
	 * arrangement that tells the per-follower dialogue check apart from the early return.
	 * A mutation pass deleting that check went green until this existed: every other test
	 * here turns dialogue off with the name label off as well.
	 */
	@Test
	public void aNameLabelWithDialogueOffDrawsTheNameAndNotTheLine()
	{
		config.setDialogue(false).setNameLabel(true);
		Follower follower = spawn();
		say(follower, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(1, overlay.drawn.size());
		assertEquals("only the name, whatever the follower is holding",
			EntourageFigure.ROGUE.getDisplayName(), overlay.drawn.get(0));
	}

	/**
	 * With both on, the line sits above the name — the order a speech bubble and a name
	 * plate go in everywhere else. The lift is in pixels rather than world units, because
	 * the text does not scale with distance and a world-space gap would close up as the
	 * follower walked away.
	 */
	@Test
	public void aTalkingFollowerWithANameDrawsTheLineAboveIt()
	{
		config.setNameLabel(true);
		Follower follower = spawn();
		say(follower, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(2, overlay.drawn.size());
		assertEquals("the name is drawn at head height",
			EntourageFigure.ROGUE.getDisplayName(), overlay.drawn.get(0));
		assertEquals(PROJECTED.getY(), overlay.drawnAt.get(0).getY());

		assertEquals("Busy today.", overlay.drawn.get(1));
		assertTrue("a line drawn at or below the name overlaps it",
			overlay.drawnAt.get(1).getY() < overlay.drawnAt.get(0).getY());
	}

	/** With no name to sit above, the line takes head height itself. */
	@Test
	public void aTalkingFollowerWithNoNameDrawsTheLineAtHeadHeight()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(1, overlay.drawn.size());
		assertEquals(PROJECTED.getY(), overlay.drawnAt.get(0).getY());
	}

	/**
	 * A follower the client no longer has registered contributes nothing, on the very next
	 * frame.
	 *
	 * <p>The line is deliberately put back on the follower here. In the running plugin
	 * {@code despawn()} clears it, and {@code FollowerTest} pins that; this puts it back
	 * behind the overlay's back so that the only thing standing between a stale line and
	 * text drawn over empty ground is the overlay's own {@code isActive()} check.
	 */
	@Test
	public void aDespawnedFollowersTextVanishesOnTheNextFrame()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);
		assertEquals(1, overlay.drawn.size());

		follower.despawn();
		say(follower, "Busy today.");
		overlay.drawn.clear();
		overlay.render(graphics);

		assertTrue("text must never be drawn for a figure the client is not rendering",
			overlay.drawn.isEmpty());
	}

	/**
	 * The position comes from the object, every frame, not from anywhere this overlay
	 * remembers. This is the drifting-text half: a walking follower's text has to walk
	 * with it.
	 */
	@Test
	public void theTextFollowsTheObjectsOwnLivePosition()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);
		LocalPoint first = overlay.projectedAt.get(0);
		assertEquals(follower.getRenderLocation().getX(), first.getX());
		assertEquals(follower.getRenderLocation().getY(), first.getY());

		// Walk it: the player moves east, the follower steps after him and the frame pass
		// places the object part way through the step.
		client.setLocalPlayer(FakePlayer.standingOn(view, STANDING.dx(6)));
		scene.onGameTick();
		scene.onFrame(view, 0.5f);
		say(follower, "Busy today.");

		overlay.projectedAt.clear();
		overlay.render(graphics);

		LocalPoint moved = overlay.projectedAt.get(0);
		assertTrue("the text stayed where the follower used to be", moved.getX() != first.getX());
		assertEquals(follower.getRenderLocation().getX(), moved.getX());
	}

	@Test
	public void theColourIsTheOneTheSettingNames()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");
		config.setDialogueColour(DialogueColour.GREEN);

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(DialogueColour.GREEN.getColour(), overlay.colours.get(0));
	}

	/**
	 * <b>The graphics context is handed back the way it was found.</b>
	 * {@code OverlayRenderer.safeRender} sets the font before every overlay it draws, so
	 * ours cannot leak into anybody else's — but that is a reading of the client's
	 * internals rather than a contract, and putting it back costs one field write per
	 * frame.
	 */
	@Test
	public void theFontIsPutBackAfterDrawing()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");

		Font before = new Font(Font.MONOSPACED, Font.PLAIN, 11);
		graphics.setFont(before);

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals("the fixture has to have actually drawn something", 1, overlay.drawn.size());
		assertSame("the overlay's own font was left on a Graphics2D it does not own",
			before, graphics.getFont());
	}

	/** The font the overlay draws with is the one the setting names. */
	@Test
	public void theFontAskedForIsTheOneTheSettingNames()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");
		config.setDialogueFont(DialogueFont.SMALL);

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(DialogueFont.SMALL, overlay.fontsAskedFor.get(0));
	}

	/**
	 * A projection that fails draws nothing and does not throw — using the real
	 * {@code Perspective} call rather than a stand-in for it. Behind the camera, off the
	 * edge of the viewport, or on a world view that has gone: all three happen constantly
	 * and none is an error. This runs once per frame per follower, so a throw here would
	 * be sixty stack traces a second.
	 */
	@Test
	public void aProjectionThatFailsDrawsNothingRatherThanThrowing()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");

		DrawRecordingOverlay overlay = new DrawRecordingOverlay();

		assertNull("the real projection has to fail for this fixture, or the test proves nothing",
			overlay.textLocation(graphics, follower.getRenderLocation(), "Busy today."));

		overlay.render(graphics);

		assertTrue("a failed projection draws nothing", overlay.drawn.isEmpty());
	}

	@Test
	public void anEmptyRosterDrawsNothing()
	{
		RecordingOverlay overlay = new RecordingOverlay();

		assertNull(overlay.render(graphics));

		assertTrue(scene.getFollowers().isEmpty());
		assertTrue(overlay.drawn.isEmpty());
		assertEquals(0, overlay.projections);
	}

	@Test
	public void bothSwitchesOffCostsNothingButTwoConfigReads()
	{
		Follower follower = spawn();
		say(follower, "Busy today.");
		config.setDialogue(false).setNameLabel(false);

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertTrue(overlay.drawn.isEmpty());
		assertEquals(0, overlay.projections);
		assertTrue("the font is not even asked for when nothing will be drawn",
			overlay.fontsAskedFor.isEmpty());
	}

	/**
	 * The overlay with every seam recorded and the projection replaced by a fixed point,
	 * so the loop's decisions are observable without a camera.
	 */
	private class RecordingOverlay extends EntourageOverlay
	{
		private final List<String> drawn = new ArrayList<>();
		private final List<Point> drawnAt = new ArrayList<>();
		private final List<Color> colours = new ArrayList<>();
		private final List<LocalPoint> projectedAt = new ArrayList<>();
		private final List<DialogueFont> fontsAskedFor = new ArrayList<>();

		private int projections;

		private RecordingOverlay()
		{
			super(null, client, scene, config);
		}

		@Override
		@Nullable
		Point textLocation(Graphics2D graphics, LocalPoint at, String text)
		{
			projections++;
			projectedAt.add(at);
			return PROJECTED;
		}

		@Override
		void drawText(Graphics2D graphics, Point at, String text, Color colour)
		{
			drawn.add(text);
			drawnAt.add(at);
			colours.add(colour);
		}

		@Override
		Font fontFor(DialogueFont font)
		{
			// Never DialogueFont.getFont(): that reaches FontManager. See the class javadoc.
			fontsAskedFor.add(font);
			return new Font(Font.SANS_SERIF, Font.PLAIN, 13);
		}
	}

	/**
	 * Only the draw and the font are replaced; the projection is the real one. Used by the
	 * single test that wants {@code Perspective} to actually run.
	 */
	private class DrawRecordingOverlay extends EntourageOverlay
	{
		private final List<String> drawn = new ArrayList<>();

		private DrawRecordingOverlay()
		{
			super(null, client, scene, config);
		}

		@Override
		void drawText(Graphics2D graphics, Point at, String text, Color colour)
		{
			drawn.add(text);
		}

		@Override
		Font fontFor(DialogueFont font)
		{
			return new Font(Font.SANS_SERIF, Font.PLAIN, 13);
		}
	}
}

package com.matthewmariner.entourage;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Every change the side panel can make, and the promise that all of it round-trips.
 *
 * <p><b>{@link FakeConfig} is both the writer and the reader here, on purpose.</b> A write
 * goes in through {@link ConfigWriter} exactly as it would through {@code ConfigManager} —
 * an enum by {@code name()}, an int as a string, {@code null} to remove the key — and then
 * comes back out through the same getters {@link EntourageSettings} reads on the game-tick
 * path. So "the setting the panel wrote is the setting the plugin uses" is asserted rather
 * than assumed, and a key spelled wrong fails here instead of in a live client.
 */
public class RosterEditTest
{
	private final FakeConfig config = new FakeConfig();

	/** @return the roster as the panel would next draw it */
	private RosterView view()
	{
		return config.view();
	}

	private void assertRoster(int followers, EntourageFigure... figures)
	{
		RosterView view = view();
		assertEquals("follower count", followers, view.getFollowers());
		for (int index = 0; index < figures.length; index++)
		{
			assertSame("slot " + (index + 1), figures[index], view.getSlot(index).getFigure());
		}
	}

