	/**
	 * The key-to-slot lookups are the inverse of the slot-to-key ones, for every slot, and
	 * answer -1 for everything else — including the other array's keys and no key at all,
	 * which is what a profile-level {@code ConfigChanged} carries.
	 */
	@Test
	public void aKeyFindsItsOwnSlotAndNothingElses()
	{
		for (int index = 0; index < RosterView.SLOTS; index++)
		{
			assertEquals(index, RosterEdit.slotOfFigureKey(RosterEdit.figureKey(index)));
			assertEquals(index, RosterEdit.slotOfCustomNpcIdKey(RosterEdit.customNpcIdKey(index)));
			assertEquals("a figure key is not an id key",
				-1, RosterEdit.slotOfCustomNpcIdKey(RosterEdit.figureKey(index)));
			assertEquals("and an id key is not a figure key",
				-1, RosterEdit.slotOfFigureKey(RosterEdit.customNpcIdKey(index)));
		}

		assertEquals(-1, RosterEdit.slotOfFigureKey(null));
		assertEquals(-1, RosterEdit.slotOfCustomNpcIdKey(null));
		assertEquals(-1, RosterEdit.slotOfFigureKey(EntourageConfig.KEY_FOLLOWERS));
		assertEquals(-1, RosterEdit.slotOfFigureKey("figure1"));
	}

