	/**
	 * <b>Everything else about the model is asserted on the way in.</b> The merge count,
	 * the recolours, the clone-before-recolour order and the lighting are all read off
	 * {@link FakeModelData} — which is to say off the thing that was <i>built</i>, not off
	 * the object that has to draw it. Nothing asked the object what it ended up holding,
	 * and a registered {@code RuneLiteObject} with a null base model is an entourage that
	 * draws nothing at all.
	 */
	@Test
	public void theLitModelReachesTheObject()
	{
		Follower follower = follower();
		follower.onGameTick(at(ANCHOR), view, defaults());

		assertTrue(follower.isActive());
		assertNotNull("a registered object with no base model is a figure that draws nothing",
			client.lastObject().getBaseModel());
	}

	/**
	 * <b>The follower is lit for the world, not for an interface.</b>
	 * {@code ModelData.light()} with no arguments is the widget rig — disassembled from
	 * the 1.12.38 injected client it is one call to {@code light(64, 768, -50, -10, -50)},
	 * which is {@code ModelData}'s own {@code DEFAULT_*} constants — and this plugin
	 * called it, so a figure walking through Varrock was lit like a model in a panel. The
	 * five below are what the same client lights a player and an NPC with: the
	 * {@code PlayerComposition} and {@code NPCComposition} implementations both call
	 * {@code light(64, 850, -30, -50, -30)}.
	 */
	@Test
	public void theModelIsLitTheWayTheClientLightsAFigureInTheWorld()
	{
		follower().onGameTick(at(ANCHOR), view, defaults());

		FakeModelData merged = client.lastMerged();
		assertNotNull(merged);
		assertTrue(merged.wasLit());
		assertNotNull("the no-argument overload is the interface rig, not the world one",
			merged.lighting());
		assertEquals("the world lighting rig, as the client itself uses it",
			Arrays.toString(new int[]{64, 850, -30, -50, -30}),
			Arrays.toString(merged.lighting()));
	}

	/**
	 * <b>Every other test in this class runs on plane 0, where the follower's plane and a
	 * hardcoded zero are the same number.</b> They are not the same number upstairs, and
	 * {@code setLocation}'s second argument is the level the client draws the object on —
	 * so a figure that follows you up a staircase and keeps being placed on the ground
	 * floor is a figure drawn through the floor you are standing on.
	 */
	@Test
	public void theObjectIsPlacedOnThePlaneTheFollowerIsOn()
	{
		WorldPoint upstairs = new WorldPoint(ANCHOR.getX(), ANCHOR.getY(), 2);
		FakeWorldView upstairsView = FakeWorldView.around(upstairs);
		client.setTopLevelWorldView(upstairsView);
		Follower follower = new Follower(client, FollowerBody.preset(EntourageFigure.ROGUE), 0, upstairs);

		follower.onGameTick(at(upstairs, upstairsView), upstairsView, walkOnly());

		assertTrue(follower.isActive());
		assertEquals("the spawn places it on its own plane, not on the ground floor",
			2, client.lastObject().getLevel());

		follower.onGameTick(at(upstairs.dx(7), upstairsView), upstairsView, walkOnly());
		assertTrue("this test needs it actually walking", follower.getWalk().isMoving());
		follower.advanceFrame(upstairsView, 0.5f);

		assertEquals("and so does every frame of the walk", 2, client.lastObject().getLevel());
	}

	// --- A cold cache --------------------------------------------------------

	@Test
	public void aColdCacheDefersTheSpawnWithoutBreakingTheFollower()
	{
		client.setCacheCold(true);
		Follower follower = follower();

		follower.onGameTick(at(ANCHOR), view, defaults());

		assertFalse("nothing to draw yet", follower.isActive());
		assertFalse("but nothing is wrong with it either", follower.isBroken());
		assertEquals(0, client.registeredCount());
	}

	@Test
	public void aColdCacheIsRetriedABoundedNumberOfTimesAndThenLeftAlone()
	{
		client.setCacheCold(true);
		Follower follower = follower();

		for (int i = 0; i < 400; i++)
		{
			follower.onGameTick(at(ANCHOR), view, defaults());
		}

		assertEquals("three attempts a scene load, not one a tick",
			Follower.MAX_ATTEMPTS, client.npcDefinitionsRequested().size());
	}

	@Test
	public void theRetriesAreSpacedRatherThanSpentInThreeConsecutiveTicks()
	{
		client.setCacheCold(true);
		Follower follower = follower();

		follower.onGameTick(at(ANCHOR), view, defaults());
		follower.onGameTick(at(ANCHOR), view, defaults());
		follower.onGameTick(at(ANCHOR), view, defaults());

		assertEquals("a cache that warms up over seconds is not re-tested three times in two",
			1, client.npcDefinitionsRequested().size());
	}

	@Test
	public void aSceneLoadHandsTheBudgetBack()
	{
		client.setCacheCold(true);
		Follower follower = follower();
		for (int i = 0; i < 400; i++)
		{
			follower.onGameTick(at(ANCHOR), view, defaults());
		}
		assertEquals(Follower.MAX_ATTEMPTS, client.npcDefinitionsRequested().size());

		follower.onSceneEntered();
		for (int i = 0; i < 400; i++)
		{
			follower.onGameTick(at(ANCHOR), view, defaults());
		}

		assertEquals("crossing a region border is the right moment to re-test a cold cache",
			Follower.MAX_ATTEMPTS * 2, client.npcDefinitionsRequested().size());
	}

	@Test
	public void aCacheThatWarmsUpProducesTheFigure()
	{
		client.setCacheCold(true);
		Follower follower = follower();
		follower.onGameTick(at(ANCHOR), view, defaults());
		assertFalse(follower.isActive());

		client.setCacheCold(false);
		for (int i = 0; i < Follower.RETRY_BACKOFF_TICKS + 2; i++)
		{
			follower.onGameTick(at(ANCHOR), view, defaults());
		}

		assertTrue(follower.isActive());
	}

	@Test
	public void aPartialModelLoadIsNotSpawnedAsAFigureWithMissingParts()
	{
		client = new FakeClient()
			.withNpc(EntourageFigure.ROGUE.getNpcId(), FakeNpcComposition.of("Rogue", 11, 22, 33))
			.withUnloadableModels(22);
		client.setTopLevelWorldView(view);
		Follower follower = follower();

		follower.onGameTick(at(ANCHOR), view, defaults());

		assertFalse("a figure with no torso is worse than no figure", follower.isActive());
		assertFalse(follower.isBroken());
		assertEquals("and nothing half-built was merged", 0, client.mergeCalls());
	}

	/**
	 * <b>The composition is resolved once and remembered, and the retry path is the only
	 * thing that can prove it.</b> Everywhere else, "what models does this figure wear?"
	 * is asked exactly once, because the answer is consumed straight into a model that is
	 * then cached — so a memo that did nothing would look identical. The case that tells
	 * them apart is an NPC that resolves while its <i>models</i> miss: the follower comes
	 * back for another go at the models, and it must not spend that go re-asking a
	 * question it already has the answer to.
	 *
	 * <p>Untested until a mutation pass deleted the memo and nothing went red.
	 */
	@Test
	public void anAppearanceThatResolvedIsNotResolvedAgainOnARetry()
	{
		client = new FakeClient()
			.withNpc(EntourageFigure.ROGUE.getNpcId(), FakeNpcComposition.of("Rogue", 11, 22, 33))
			.withUnloadableModels(22);
		client.setTopLevelWorldView(view);
		Follower follower = follower();

		follower.onGameTick(at(ANCHOR), view, defaults());
		assertEquals("the composition resolved", 1, client.npcDefinitionsRequested().size());
		int modelsAsked = client.modelsLoaded().size();

		for (int i = 0; i < Follower.RETRY_BACKOFF_TICKS + 2; i++)
		{
			follower.onGameTick(at(ANCHOR), view, defaults());
		}

		assertTrue("this test needs the models to have been retried",
			client.modelsLoaded().size() > modelsAsked);
		assertEquals("but the composition is remembered, not asked for again",
			1, client.npcDefinitionsRequested().size());
	}

	// --- Dressing ------------------------------------------------------------

	@Test
	public void everyModelPartTheCompositionNamesIsMerged()
	{
		client = new FakeClient()
			.withNpc(EntourageFigure.ROGUE.getNpcId(), FakeNpcComposition.of("Rogue", 11, 22, 33));
		client.setTopLevelWorldView(view);

		follower().onGameTick(at(ANCHOR), view, defaults());

		assertEquals(1, client.mergeCalls());
		assertEquals(3, client.lastMergePartCount());
	}

	/**
	 * {@code ModelData.recolor}'s own javadoc says to call {@code cloneColors()} first.
	 * "mergeModels hands back a fresh instance" is an observation about an obfuscated
	 * constructor, not a contract — and repainting a shared {@code faceColors} array
	 * would repaint every instance of that model in the world, through the client's own
	 * cache.
	 */
	@Test
	public void theCompositionsColoursAreAppliedAndOnlyAfterTheColoursAreCloned()
	{
		client = new FakeClient().withNpc(EntourageFigure.ROGUE.getNpcId(),
			FakeNpcComposition.recoloured("Rogue", new int[]{11},
				new short[]{4550, 900}, new short[]{100, 200}));
		client.setTopLevelWorldView(view);

		follower().onGameTick(at(ANCHOR), view, defaults());

		FakeModelData merged = client.lastMerged();
		assertNotNull(merged);
		assertTrue("cloneColors() first", merged.colorsCloned());
		assertFalse("and never a recolour before it", merged.recolouredBeforeClone());
		assertEquals(2, merged.recolours().size());
		assertEquals(4550, merged.recolours().get(0)[0]);
		assertEquals(100, merged.recolours().get(0)[1]);
		assertTrue("and it was lit", merged.wasLit());
	}

	@Test
	public void aFigureWithNoRecoloursIsNotCloned()
	{
		follower().onGameTick(at(ANCHOR), view, defaults());

		FakeModelData merged = client.lastMerged();
		assertNotNull(merged);
		assertFalse("cloning colours nothing is going to repaint is wasted work",
			merged.colorsCloned());
		assertTrue(merged.wasLit());
	}

	@Test
	public void theModelIsBuiltOnceAndKeptAcrossADespawn()
	{
		Follower follower = follower();
		follower.onGameTick(at(ANCHOR), view, defaults());
		follower.despawn();
		follower.onGameTick(at(ANCHOR), view, defaults());

		assertTrue(follower.isActive());
		assertEquals("walking out of the world and back is an activate, not a rebuild",
			1, client.mergeCalls());
	}

	/**
	 * A figure that is not the default, built end to end. Every other test in this class
	 * uses the rogue, whose animations are the human rig's own — so a follower that
	 * ignored its figure's declared pair and always played 808/819 would pass all of
	 * them.
	 */
	@Test
	public void aFigureWithItsOwnAnimationsPlaysThoseAndNotTheHumanOnes()
	{
		Follower follower = settled(EntourageFigure.NIEVE, walkOnly());
		follower.onGameTick(at(EAST), view, walkOnly());

		assertTrue(follower.isActive());
		assertTrue("her own stand", client.animationsLoaded()
			.contains(EntourageAnimation.STAFF_STAND.getId()));
		assertTrue("her own walk", client.animationsLoaded()
			.contains(EntourageAnimation.HALBERD_WALK.getId()));
		assertFalse("and not the human rig's", client.animationsLoaded()
			.contains(EntourageAnimation.HUMAN_WALK.getId()));
	}

	// --- Stay put ------------------------------------------------------------

	private static EntourageSettings parked()
	{
		return new FakeConfig().setStayPut(true).settings();
	}

	/**
	 * <b>Parking mid-walk drops straight into the idle pose.</b> The walk is over as far as
	 * this class is concerned — {@code isMoving()} is false — so {@code controllerFor} picks
	 * the idle controller, and it is the same one the follower held before it set off rather
	 * than a fresh one, which is what keeps the pose from restarting at frame zero.
	 */
	@Test
	public void parkingAWalkingFollowerPutsItBackIntoItsPose()
	{
		Follower follower = settled(walkOnly());
		AnimationController pose = follower.getInstalledController();
		assertNotNull("the fixture leaves it holding a pose", pose);

		follower.onGameTick(at(EAST), view, walkOnly());
		assertTrue("this test needs it actually walking", follower.getWalk().isMoving());
		assertNotSame(pose, follower.getInstalledController());

		follower.onGameTick(at(EAST), view, parked());

		assertFalse("it stopped", follower.getWalk().isMoving());
		assertSame("and went back to the pose it already had", pose,
			follower.getInstalledController());
	}

	/**
	 * <b>Parked is not frozen: a parked follower still turns to watch you.</b> That is the
	 * effect the feature was asked for — a group posted up along a wall that tracks you
	 * around the room — and it comes for free because the facing is applied whenever the
	 * follower is not moving. Which is exactly why it needs a test: it is a behaviour nothing
	 * here writes down, and a suppression written one line too wide would take it out.
	 */
	@Test
	public void aParkedFollowerStillTurnsToWatchYou()
	{
		Follower follower = settled(new FakeConfig()
			.setFacing(FollowerFacing.AT_ME).setStayPut(true).settings());
		EntourageSettings settings = new FakeConfig()
			.setFacing(FollowerFacing.AT_ME).setStayPut(true).settings();

		follower.onGameTick(at(ANCHOR.dx(4)), view, settings);
		int lookingEast = follower.getRenderOrientation();

		follower.onGameTick(at(ANCHOR.dy(4)), view, settings);
		int lookingNorth = follower.getRenderOrientation();

		assertEquals("it did not move", ANCHOR, follower.getWalk().currentTile());
		assertNotEquals("but it turned to follow the player round", lookingEast, lookingNorth);
	}

	/**
	 * <b>A parked follower that goes off screen comes back on its own tile, not on
	 * yours.</b> Every scene load deactivates the entourage, and the ordinary respawn path
	 * puts an inactive follower back on the player — which for a parked one would be a
	 * teleport home every time the player crossed a region boundary, i.e. the feature
	 * quietly not working over any distance worth using it for.
	 */
	@Test
	public void aParkedFollowerComesBackOnTheTileItWasParkedOn()
	{
		Follower follower = settled(parked());
		follower.onGameTick(at(PLAYER), view, parked());
		assertEquals(ANCHOR, follower.getFrozenTile());

		follower.despawn();
		assertFalse(follower.isActive());

		follower.onGameTick(at(EAST), view, parked());

		assertTrue("it came back", follower.isActive());
		assertEquals("on the tile it was parked on rather than on the player's",
			ANCHOR, follower.getWalk().currentTile());
	}

	/**
	 * <b>A parked tile outside the loaded scene draws nothing at all.</b> Not clamped to the
	 * scene edge and not moved to the player: either would be a figure standing somewhere
	 * nobody put it. It comes back the moment its tile is loaded again, which is what makes
	 * "walk out of the region and come back" work.
	 */
	@Test
	public void aParkedFollowerOutsideTheLoadedSceneIsNotDrawnAndThenComesBack()
	{
		Follower follower = settled(parked());
		follower.onGameTick(at(PLAYER), view, parked());
		follower.despawn();

		// A scene somewhere else entirely — the player has walked far enough that the tile
		// the group was parked on is no longer in the loaded map.
		FakeWorldView elsewhere = FakeWorldView.around(ANCHOR.dx(2_000));
		client.setTopLevelWorldView(elsewhere);
		follower.onGameTick(at(ANCHOR.dx(2_000), elsewhere), elsewhere, parked());

		assertFalse("nothing is drawn rather than something drawn in the wrong place",
			follower.isActive());
		assertEquals("and nothing is registered with the client", 0, client.registeredCount());
		assertEquals("the pin is kept, because a world tile still means that place",
			ANCHOR, follower.getFrozenTile());

		// And back again.
		client.setTopLevelWorldView(view);
		follower.onGameTick(at(PLAYER), view, parked());

		assertTrue("it is picked up again the moment its tile is loaded", follower.isActive());
		assertEquals(ANCHOR, follower.getWalk().currentTile());
	}

	/**
	 * <b>The pin does not cross an instance boundary.</b> Inside an instance the game builds
	 * a private copy of an area out of template chunks, so the tile the anchor derives names
	 * the template rather than the place the player is standing. Carried across the boundary
	 * it would usually be nowhere near the loaded scene — harmless — but occasionally inside
	 * it, which is a follower appearing in a corner of a raid nobody parked it in. So the pin
	 * is dropped and the group re-parks on the player.
	 */
	@Test
	public void theParkedTileIsDroppedWhenTheInstanceBoundaryIsCrossed()
	{
		Follower follower = settled(parked());
		follower.onGameTick(at(PLAYER), view, parked());
		assertEquals(ANCHOR, follower.getFrozenTile());

		follower.despawn();

		FakeWorldView raid = FakeWorldView.around(ANCHOR).asInstance();
		client.setTopLevelWorldView(raid);
		follower.onGameTick(at(PLAYER, raid), raid, parked());

		assertTrue(follower.isActive());
		assertEquals("re-parked where the player actually is",
			PLAYER, follower.getWalk().currentTile());
		assertEquals(PLAYER, follower.getFrozenTile());
	}

	/** Unparking forgets where they were told to stand, so the next respawn is the ordinary one. */
	@Test
	public void unparkingForgetsThePinnedTile()
	{
		Follower follower = settled(parked());
		follower.onGameTick(at(PLAYER), view, parked());
		assertNotNull(follower.getFrozenTile());

		follower.onGameTick(at(PLAYER), view, defaults());

		assertNull(follower.getFrozenTile());
	}

	/** A follower that has never spawned parks where it first appears, which is on the player. */
	@Test
	public void aFollowerThatHasNeverSpawnedParksWhereItFirstAppears()
	{
		Follower follower = follower();

		follower.onGameTick(at(PLAYER), view, parked());

		assertTrue(follower.isActive());
		assertEquals(PLAYER, follower.getWalk().currentTile());
		assertEquals(PLAYER, follower.getFrozenTile());
	}
}

package com.matthewmariner.entourage;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * What the side panel draws, without the panel.
 *
 * <p>Everything on a card comes from here, so everything on a card is testable on a build
 * machine with no display — which is the whole reason the read model is a separate class.
 */
public class RosterViewTest
{
	private final FakeConfig config = new FakeConfig();

	@Test
	public void aFreshInstallDrawsFiveCardsOfWhichOneIsWalkingWithYou()
	{
		RosterView view = config.view();

		assertEquals("five cards, always", 5, view.getSlots().size());
		assertEquals(1, view.getFollowers());

		assertTrue(view.getSlot(0).isActive());
		for (int index = 1; index < RosterView.SLOTS; index++)
		{
			assertFalse("slot " + index + " is past the count and must read as inactive",
				view.getSlot(index).isActive());
		}
	}

	/**
	 * <b>An inactive slot still names somebody.</b> The count and the roster are separate
	 * questions — RuneLite cannot blank a dropdown — so a card past the count shows the
	 * figure it is set to rather than vanishing, which is also the only way that figure
	 * stays visible and changeable.
	 */
	@Test
	public void aSlotPastTheCountStillShowsTheFigureItIsSetTo()
	{
		config.setFigureAt(4, EntourageFigure.GHOMMAL);

		RosterView.Slot slot = config.view().getSlot(4);

		assertFalse(slot.isActive());
		assertSame(EntourageFigure.GHOMMAL, slot.getFigure());
		assertEquals("Ghommal", slot.getTitle());
		assertEquals("Not walking — raise the count", slot.getSubtitle());
	}

	/** Each card reads a different key, and reading the wrong one is a card that lies. */
	@Test
	public void everySlotShowsItsOwnFigureRatherThanItsNeighboursIs()
	{
		config.setRoster(EntourageFigure.ROGUE, EntourageFigure.HANS, EntourageFigure.VANNAKA,
			EntourageFigure.PIRATE, EntourageFigure.TURAEL);

		RosterView view = config.view();

		assertSame(EntourageFigure.ROGUE, view.getSlot(0).getFigure());
		assertSame(EntourageFigure.HANS, view.getSlot(1).getFigure());
		assertSame(EntourageFigure.VANNAKA, view.getSlot(2).getFigure());
		assertSame(EntourageFigure.PIRATE, view.getSlot(3).getFigure());
		assertSame(EntourageFigure.TURAEL, view.getSlot(4).getFigure());
	}

	/** The heading counts the way a person does, not the way an array does. */
	@Test
	public void theCardsAreNumberedOneToFive()
	{
		RosterView view = config.view();

		assertEquals("Slot 1", view.getSlot(0).getHeading());
		assertEquals("Slot 5", view.getSlot(4).getHeading());
	}

	/**
	 * <b>A typed id shows as an id, because the name cannot be known here.</b> Resolving
	 * NPC 4931 to "Cave goblin guard" needs the client, and the client throws off the client
	 * thread — which is the thread every one of these cards is built on. A number is the
	 * true thing this can say.
	 */
	@Test
	public void aTypedIdIsDrawnAsAnIdWithTheFallbackNamedUnderIt()
	{
		config.setFigure(EntourageFigure.VANNAKA).setCustomNpcId(4931);

		RosterView view = config.view();
		RosterView.Slot first = view.getSlot(0);

		assertTrue(view.getSlot(0).isCustom());
		assertEquals(4931, view.getSlot(0).getCustomNpcId());
		assertTrue(first.isCustom());
		assertEquals("NPC 4931", first.getTitle());
		assertEquals("the fallback is what you see when the id is refused",
			"Typed id, or Vannaka if refused", first.getSubtitle());
		assertSame("and the fallback is still the dropdown's figure",
			EntourageFigure.VANNAKA, first.getFigure());
	}

	/**
	 * <b>A typed id in one slot stays in that slot.</b> This test used to be called
	 * {@code noSlotButTheFirstCanWearATypedId} and asserted the opposite half of the same
	 * concern — that the id belonged to slot 1 alone. There are five keys now, so the thing
	 * worth pinning is that they do not leak into one another: five cards all reading the same
	 * key would look right on whichever one was typed into last and wrong on the other four.
	 */
	@Test
	public void aTypedIdInOneSlotDoesNotAppearInAnyOther()
	{
		for (int wearing = 0; wearing < RosterView.SLOTS; wearing++)
		{
			FakeConfig one = new FakeConfig()
				.setRoster(EntourageFigure.ROGUE, EntourageFigure.HANS, EntourageFigure.PIRATE,
					EntourageFigure.VANNAKA, EntourageFigure.TURAEL)
				.setCustomNpcIdAt(wearing, 4931);

			RosterView view = one.view();
			for (int index = 0; index < RosterView.SLOTS; index++)
			{
				if (index == wearing)
				{
					assertTrue("slot " + index + " was given the id and does not have it",
						view.getSlot(index).isCustom());
					assertEquals(4931, view.getSlot(index).getCustomNpcId());
				}
				else
				{
					assertFalse("slot " + index + " picked up slot " + wearing + "'s id",
						view.getSlot(index).isCustom());
					assertEquals(FollowerBody.NO_CUSTOM_NPC,
						view.getSlot(index).getCustomNpcId());
				}
			}
		}
	}

	/** Five different ids in five slots, each drawn on its own card. */
	@Test
	public void everySlotDrawsItsOwnTypedId()
	{
		config.setRoster(EntourageFigure.ROGUE, EntourageFigure.HANS, EntourageFigure.PIRATE,
			EntourageFigure.VANNAKA, EntourageFigure.TURAEL);
		for (int index = 0; index < RosterView.SLOTS; index++)
		{
			config.setCustomNpcIdAt(index, 3000 + index);
		}

		RosterView view = config.view();

		for (int index = 0; index < RosterView.SLOTS; index++)
		{
			assertEquals(3000 + index, view.getSlot(index).getCustomNpcId());
			assertEquals("NPC " + (3000 + index), view.getSlot(index).getTitle());
		}
	}

	/** A slot past the count can hold an id too — it is a setting, not a follower. */
	@Test
	public void aSlotPastTheCountKeepsItsTypedIdTheWayItKeepsItsFigure()
	{
		config.setRoster(EntourageFigure.ROGUE).setCustomNpcIdAt(4, 4931);

		RosterView.Slot slot = config.view().getSlot(4);

		assertFalse(slot.isActive());
		assertTrue(slot.isCustom());
		assertEquals("Not walking — raise the count", slot.getSubtitle());
	}

	/** Every slot floors a hand-edited negative the same way, because there is one floor. */
	@Test
	public void aNegativeIsNotATypedIdInAnySlot()
	{
		for (int index = 0; index < RosterView.SLOTS; index++)
		{
			assertFalse("slot " + index + " read a negative as a typed id",
				new FakeConfig().setCustomNpcIdAt(index, -7).view().getSlot(index).isCustom());
		}
	}

	// --- the favourites ----------------------------------------------------------

	@Test
	public void aFreshInstallHasNoFavourites()
	{
		assertTrue(config.view().getFavourites().isEmpty());
		assertFalse(config.view().isFavourite(3598));
		assertTrue("and there is room for one", config.view().canFavourite());
	}

	@Test
	public void theFavouritesAreTheOnesTheProfileHolds()
	{
		config.setFavouriteNpcIds("3598,4931");

		RosterView view = config.view();

		assertEquals(java.util.Arrays.asList(3598, 4931), view.getFavourites());
		assertTrue(view.isFavourite(3598));
		assertTrue(view.isFavourite(4931));
		assertFalse(view.isFavourite(7));
	}

	/**
	 * <b>The panel draws the list the profile really means, not the string it really holds.</b>
	 * A hand-edited value with a name in it, a blank entry and a trailing comma has to come
	 * through as the ids that survived — the coercion is {@link Favourites}' and this is the
	 * assertion that the view actually goes through it rather than splitting the string
	 * itself.
	 */
	@Test
	public void aMalformedFavouritesValueStillDrawsTheIdsThatSurvivedIt()
	{
		config.setFavouriteNpcIds(" 3598 ,,Gummy,-7,0,4931,");

		assertEquals(java.util.Arrays.asList(3598, 4931), config.view().getFavourites());
	}

	@Test
	public void theFavouritesListIsFullAtTheCap()
	{
		StringBuilder ids = new StringBuilder();
		for (int index = 0; index < Favourites.MAX; index++)
		{
			ids.append(1_000 + index).append(',');
		}
		config.setFavouriteNpcIds(ids.toString());

		assertEquals(Favourites.MAX, config.view().getFavourites().size());
		assertFalse("and there is no room for another", config.view().canFavourite());
	}

	@Test
	public void theFavouritesCannotBeEditedUnderTheNextRedraw()
	{
		config.setFavouriteNpcIds("3598");

		try
		{
			config.view().getFavourites().add(1);
			fail("the favourites list must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// what an unmodifiable list does
		}
	}

	/** Zero means "use the dropdown", and so does anything a hand-edited profile floors past. */
	@Test
	public void zeroOrLessIsNotATypedIdAtAll()
	{
		assertFalse(config.setCustomNpcId(0).view().getSlot(0).isCustom());
		assertFalse("a hand-edited profile really can hold a negative",
			config.setCustomNpcId(-7).view().getSlot(0).isCustom());
		assertEquals("Rogue", config.setCustomNpcId(-7).view().getSlot(0).getTitle());
	}

	/**
	 * <b>The panel draws the roster the scene will actually spawn.</b> {@code @Range} bounds
	 * the settings spinner and nothing else, so a profile edited by hand can say
	 * {@code followers=9} — and a panel that believed it would draw nine active cards over a
	 * five-figure entourage.
	 */
	@Test
	public void aCountOutsideItsRangeIsClampedTheWayTheSceneClampsIt()
	{
		assertEquals(5, config.setFollowers(9).view().getFollowers());
		assertEquals(1, config.setFollowers(0).view().getFollowers());
		assertEquals(1, config.setFollowers(-4).view().getFollowers());

		assertEquals("and it is the scene's own answer rather than a second copy of it",
			config.setFollowers(9).settings().getRosterSize(),
			config.setFollowers(9).view().getFollowers());
	}

	@Test
	public void aFollowDistanceOutsideItsRangeIsClampedTheSameWay()
	{
		assertEquals(2, config.setFollowDistance(40).view().getFollowDistance());
		assertEquals("zero would be a follower standing inside the player",
			1, config.setFollowDistance(0).view().getFollowDistance());

		assertEquals(config.setFollowDistance(40).settings().getFollowDistance(),
			config.setFollowDistance(40).view().getFollowDistance());
	}

	@Test
	public void theFormationIsTheOneTheSettingNames()
	{
		assertSame(EntourageFormation.BEHIND, config.view().getFormation());
		assertSame(EntourageFormation.HANGOUT,
			config.setFormation(EntourageFormation.HANGOUT).view().getFormation());
	}

	/** The two ends of the roster, which decide whether the panel draws an add or a remove. */
	@Test
	public void addingIsOfferedBelowFiveAndRemovingAboveOne()
	{
		assertTrue("a fresh install has room for four more", config.setFollowers(1).view().canAdd());
		assertFalse("and one follower is the floor, because a roster of nobody is the "
			+ "plugin's own off switch", config.setFollowers(1).view().canRemove());

		assertFalse(config.setFollowers(5).view().canAdd());
		assertTrue(config.setFollowers(5).view().canRemove());

		assertTrue(config.setFollowers(3).view().canAdd());
		assertTrue(config.setFollowers(3).view().canRemove());
	}

	/**
	 * A mouse listener holding a stale index must not take the event dispatch thread down
	 * with it — the panel would stop responding rather than misdraw one card.
	 */
	@Test
	public void anIndexOffTheEndAnswersACardRatherThanThrowing()
	{
		RosterView view = config.view();

		assertEquals(0, view.getSlot(-3).getIndex());
		assertEquals(RosterView.SLOTS - 1, view.getSlot(99).getIndex());
	}

	@Test
	public void theSlotsCannotBeEditedUnderTheNextRedraw()
	{
		try
		{
			config.view().getSlots().clear();
			fail("the slot list must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// what an unmodifiable list does
		}
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The one rule {@link RosterSync} keeps — a slot wears a typed id if and only if its
 * dropdown says {@code CUSTOM} — for every way the two halves can disagree, and the
 * property that makes it safe to run from a {@code ConfigChanged} handler: every write it
 * makes is answered by silence.
 */
public class RosterSyncTest
{
	private final FakeConfig config = new FakeConfig();

	/** What the settings screen does: one key at a time, then the event. */
	private boolean changed(String key)
	{
		return RosterSync.onChanged(config, config, key);
	}

	@Test
	public void anIdTypedUnderAPresetSetsTheDropdownToCustom()
	{
		config.setFigure(EntourageFigure.WISE_OLD_MAN).setCustomNpcId(4931).clearWrites();

		assertTrue(changed(EntourageConfig.KEY_CUSTOM_NPC_ID));

		assertEquals(Collections.singletonList("figure=CUSTOM"), config.writes());
		assertSame(EntourageFigure.CUSTOM, EntourageSettings.storedFigureAt(config, 0));
		assertEquals("and the id is untouched", 4931, config.view().getSlot(0).getCustomNpcId());
	}

	/**
	 * <b>A preset written over an id is corrected back; the id is not cleared.</b> From
	 * inside a {@code ConfigChanged} on the dropdown's key there is no telling a preset
	 * picked in the settings screen from a profile switched underneath the plugin, and
	 * only one of those may lose the id — so neither does. The id wins, going back to a
	 * preset in the settings screen means emptying the box first, and the panel's picker
	 * clears the id itself in {@code RosterEdit#assign}.
	 */
	@Test
	public void aPresetWrittenOverAnIdIsCorrectedBackToCustom()
	{
		config.setFigure(EntourageFigure.CUSTOM).setCustomNpcId(4931);
		config.setFigure(EntourageFigure.GHOMMAL).clearWrites();

		assertTrue(changed(EntourageConfig.KEY_FIGURE));

		assertEquals(Collections.singletonList("figure=CUSTOM"), config.writes());
		assertEquals("the id is untouched", 4931, config.view().getSlot(0).getCustomNpcId());
		assertSame(EntourageFigure.CUSTOM, EntourageSettings.storedFigureAt(config, 0));
	}

	/**
	 * <b>The profile switch that used to lose an id.</b> {@code ConfigManager.switchProfile}
	 * posts one event per key that differs between the two profiles, in hash order, with
	 * the new profile already readable and before {@code ProfileChanged} — so a profile
	 * written before the marker existed, with a preset under an id, can announce its
	 * dropdown before its id or after it. Whichever lands first, the id has to survive
	 * and the dropdown has to end up saying Custom.
	 */
	@Test
	public void aProfileSwitchedUnderneathKeepsItsIdWhicheverKeyArrivesFirst()
	{
		String[][] orders = {
			{EntourageConfig.KEY_FIGURE, EntourageConfig.KEY_CUSTOM_NPC_ID},
			{EntourageConfig.KEY_CUSTOM_NPC_ID, EntourageConfig.KEY_FIGURE},
		};
		for (String[] order : orders)
		{
			FakeConfig switched = new FakeConfig()
				.setFigure(EntourageFigure.THIEF).setCustomNpcId(2215).clearWrites();

			for (String key : order)
			{
				RosterSync.onChanged(switched, switched, key);
			}

			String state = String.join(" then ", order);
			assertEquals(state + ": the id survives", 2215, switched.view().getSlot(0).getCustomNpcId());
			assertSame(state, EntourageFigure.CUSTOM, EntourageSettings.storedFigureAt(switched, 0));
			assertEquals(state, Collections.singletonList("figure=CUSTOM"), switched.writes());
		}
	}

	@Test
	public void emptyingTheBoxUnderCustomGivesTheSlotItsShippedFigureBack()
	{
		config.setFigure(EntourageFigure.CUSTOM).clearWrites();

		assertTrue(changed(EntourageConfig.KEY_CUSTOM_NPC_ID));

		assertEquals(Collections.singletonList("figure="), config.writes());
		assertSame(EntourageFigure.defaultAt(0), EntourageSettings.storedFigureAt(config, 0));
	}

	/**
	 * <b>Somebody who picks "Custom NPC id" in the dropdown is about to type a number.</b>
	 * Snapping the dropdown back the instant they pick it would fight them for the control;
	 * the slot draws its shipped figure in the meantime, which is honest.
	 */
	@Test
	public void pickingCustomInTheDropdownWithNoIdYetIsLeftAlone()
	{
		config.setFigure(EntourageFigure.CUSTOM).clearWrites();

		assertFalse(changed(EntourageConfig.KEY_FIGURE));

		assertTrue(config.writes().isEmpty());
		assertSame(EntourageFigure.CUSTOM, EntourageSettings.storedFigureAt(config, 0));
		assertSame("drawn as the default until an id arrives",
			EntourageFigure.defaultAt(0), config.settings().getBodies().get(0).getFigure());
		assertFalse(config.settings().getBodies().get(0).isCustom());
	}

	@Test
	public void aSlotThatAlreadyAgreesWithItselfWritesNothing()
	{
		config.setFigure(EntourageFigure.CUSTOM).setCustomNpcId(4931).clearWrites();
		assertFalse(changed(EntourageConfig.KEY_FIGURE));
		assertFalse(changed(EntourageConfig.KEY_CUSTOM_NPC_ID));

		config.setFigure(EntourageFigure.HANS).setCustomNpcId(0).clearWrites();
		assertFalse(changed(EntourageConfig.KEY_FIGURE));
		assertFalse(changed(EntourageConfig.KEY_CUSTOM_NPC_ID));

		assertTrue(config.writes().isEmpty());
	}

	/** Only the two halves of a slot are anybody's business; a disagreement is not chased on other keys. */
	@Test
	public void aKeyThatIsNotHalfOfASlotWritesNothing()
	{
		config.setCustomNpcId(4931).clearWrites();

		assertFalse(changed(null));
		assertFalse(changed(EntourageConfig.KEY_FOLLOWERS));
		assertFalse(changed("dialogue"));
		assertFalse(changed(EntourageConfig.KEY_FAVOURITE_NPC_IDS));

		assertTrue(config.writes().isEmpty());
	}

	@Test
	public void eachSlotIsReconciledUnderItsOwnKeysAndOnlyItsOwn()
	{
		for (int index = 0; index < RosterView.SLOTS; index++)
		{
			FakeConfig one = new FakeConfig().setCustomNpcIdAt(index, 3000 + index);
			one.setFollowers(RosterView.SLOTS).clearWrites();

			assertTrue(RosterSync.onChanged(one, one, RosterEdit.customNpcIdKey(index)));

			assertEquals("slot " + index,
				Collections.singletonList(RosterEdit.figureKey(index) + "=CUSTOM"), one.writes());
			for (int other = 0; other < RosterView.SLOTS; other++)
			{
				if (other != index)
				{
					assertSame("slot " + other + " was not the one that changed",
						EntourageFigure.defaultAt(other), EntourageSettings.storedFigureAt(one, other));
				}
			}
		}
	}

	/**
	 * <b>The migration, against the shape of a real profile.</b> Two ids typed before the
	 * dropdown could say "Custom NPC id", each under the preset the owner had picked earlier:
	 * after one start-up pass both dropdowns say what is in force and the third slot, which
	 * never had an id, is untouched.
	 */
	@Test
	public void startUpBringsAnOldProfileUpToDate()
	{
		config.setRoster(EntourageFigure.WISE_OLD_MAN, EntourageFigure.THIEF, EntourageFigure.SORCERESS)
			.setCustomNpcIdAt(0, 3162)
			.setCustomNpcIdAt(1, 2215)
			.clearWrites();

		assertTrue(RosterSync.onStartUp(config, config));

		assertEquals(Arrays.asList("figure=CUSTOM", "figure2=CUSTOM"), config.writes());
		assertEquals(3162, config.view().getSlot(0).getCustomNpcId());
		assertEquals(2215, config.view().getSlot(1).getCustomNpcId());
		assertSame(EntourageFigure.SORCERESS, EntourageSettings.storedFigureAt(config, 2));
	}

	@Test
	public void startUpLeavesAProfileThatAlreadyAgreesAlone()
	{
		config.setRoster(EntourageFigure.CUSTOM, EntourageFigure.HANS)
			.setCustomNpcIdAt(0, 4931)
			.clearWrites();

		assertFalse(RosterSync.onStartUp(config, config));
		assertTrue(config.writes().isEmpty());
	}

	@Test
	public void startUpLeavesCustomWithNoIdAlone()
	{
		config.setFigure(EntourageFigure.CUSTOM).clearWrites();

		assertFalse(RosterSync.onStartUp(config, config));
		assertTrue(config.writes().isEmpty());
	}

	/**
	 * <b>The property that makes this safe to run from inside {@code ConfigChanged}.</b>
	 * Every write posts an event that lands straight back in {@link RosterSync#onChanged};
	 * if any branch's write could trigger another branch's write the plugin would loop
	 * writing the profile forever. So for every dropdown state, every id state and every
	 * cause: reconcile once, replay each write as its own event, and demand silence. And
	 * whatever it wrote was the dropdown: the box is never this class's to unset.
	 */
	@Test
	public void everyWriteIsAnsweredBySilence()
	{
		EntourageFigure[] dropdowns = {EntourageFigure.ROGUE, EntourageFigure.HANS, EntourageFigure.CUSTOM};
		int[] ids = {0, 4931};

		for (EntourageFigure dropdown : dropdowns)
		{
			for (int id : ids)
			{
				for (RosterSync.Cause cause : RosterSync.Cause.values())
				{
					String state = dropdown + "/" + id + "/" + cause;
					FakeConfig one = new FakeConfig().setFigure(dropdown).setCustomNpcId(id).clearWrites();

					RosterSync.reconcile(one, one, 0, cause);
					List<String> written = new ArrayList<>(one.writes());
					assertTrue(state + ": at most one write per pass", written.size() <= 1);

					for (String write : written)
					{
						String key = write.substring(0, write.indexOf('='));
						assertTrue(state + ": the sync writes only the dropdown, never the box",
							RosterEdit.slotOfFigureKey(key) >= 0);
						one.clearWrites();
						assertFalse(state + ": the write " + write + " came back as another write",
							RosterSync.onChanged(one, one, key));
						assertTrue(one.writes().isEmpty());
					}

					// And whatever it did, the slot now agrees with itself — unless nothing
					// moved and the dropdown says Custom over an empty box, which is the one
					// disagreement left alone on purpose.
					boolean saysCustom = EntourageSettings.storedFigureAt(one, 0) == EntourageFigure.CUSTOM;
					boolean hasId = one.view().getSlot(0).isCustom();
					if (hasId || !saysCustom)
					{
						assertEquals(state + ": the halves disagree after the pass", saysCustom, hasId);
					}
				}
			}
		}
	}
}

package com.matthewmariner.entourage;

import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.fail;

/**
 * The roster: every NPC id and every animation on it, pinned twice over.
 *
 * <p><b>Twice, because a rename and a renumbering are different failures.</b> Naming
 * the {@code gameval} constant catches an entry being pointed at a different NPC by a
 * careless edit — the constant would still compile, but it would be the wrong one.
 * Naming the literal catches the id being <i>renumbered</i> underneath the constant,
 * which compiles, does not warn, and puts a different body on the follower. Neither
 * assertion is redundant with the other, and the second is the kind of failure that
 * killed {@code ../lively-cities}' predecessor plugin.
 *
 * <p>The two pinning tests also count what they pinned against
 * {@code EntourageFigure.presets().size()}, so a preset added without a line here is a
 * red test rather than an unpinned entry.
 */
public class EntourageFigureTest
{
	private final EnumSet<EntourageFigure> pinned = EnumSet.noneOf(EntourageFigure.class);

	// --- The bodies -----------------------------------------------------------

	@Test
	public void everyFigureWearsTheNpcItIsDocumentedAsWearing()
	{
		npc(EntourageFigure.ROGUE, NpcID.ROGUE, 526);
		npc(EntourageFigure.VANNAKA, NpcID.SLAYER_MASTER_3, 403);
		npc(EntourageFigure.NIEVE, NpcID.SLAYER_MASTER_NIEVE, 6797);
		npc(EntourageFigure.STEVE, NpcID.SLAYER_MASTER_STEVE, 6798);
		npc(EntourageFigure.TURAEL, NpcID.SLAYER_MASTER_1_TUREAL, 13618);
		npc(EntourageFigure.DURADEL, NpcID.SLAYER_MASTER_5_DURADEL, 13622);
		npc(EntourageFigure.MAZCHNA, NpcID.SLAYER_MASTER_2_MAZCHNA, 13620);
		npc(EntourageFigure.WISE_OLD_MAN, NpcID.WISE_OLD_MAN, 2108);
		npc(EntourageFigure.WHITE_KNIGHT, NpcID.WHITE_KNIGHT, 1798);
		npc(EntourageFigure.ELITE_BLACK_KNIGHT, NpcID.ELITE_BLACK_KNIGHT_1, 13463);
		npc(EntourageFigure.SIR_AMIK_VARZE, NpcID.SIR_AMIK_VARZE, 4771);
		npc(EntourageFigure.SIR_VYVIN, NpcID.SIR_VYVIN, 4736);
		npc(EntourageFigure.PALADIN, NpcID.ARDOUGNE_PALADIN2, 1144);
		npc(EntourageFigure.GRILL_KNIGHT, NpcID.GRILLKNIGHT, 4777);
		npc(EntourageFigure.GHOMMAL, NpcID.WARGUILD_GHOMMAL_NPC, 13613);
		npc(EntourageFigure.HERO, NpcID.HERO, 3295);
		npc(EntourageFigure.ZAMORAK_MAGE, NpcID.RCU_ZAMMY_MAGE1A, 2580);
		npc(EntourageFigure.NECROMANCER, NpcID.NECROMANCER, 1025);
		npc(EntourageFigure.SORCERESS, NpcID.ARABIAN_SORCERESS, 1807);
		npc(EntourageFigure.THIEF, NpcID.THIEF2, 3253);
		npc(EntourageFigure.PIRATE, NpcID.PIRATE1, 521);
		npc(EntourageFigure.HANS, NpcID.HANS, 3105);
		npc(EntourageFigure.FARMER, NpcID.FARMER1, 3114);

		assertEquals("a preset with no line above is a preset nobody has checked the id of",
			EntourageFigure.presets().size(), pinned.size());
	}

	private void npc(EntourageFigure figure, int constant, int literal)
	{
		assertEquals(figure.name() + " does not wear the NpcID constant it is documented as",
			constant, figure.getNpcId());
		assertEquals(figure.name() + ": that constant has been renumbered under the enum",
			literal, figure.getNpcId());
		assertTrue(figure.name() + " is pinned twice", pinned.add(figure));
	}

	/**
	 * <b>The exclusions, which are a finding rather than an omission.</b> Each of these
	 * was looked at for the roster and rejected for a reason that a later reader, seeing
	 * a plausible slayer master or a well-known face missing, would otherwise be likely
	 * to "fix". Krystilia is the sharpest: her stand and her walk are the same id, so she
	 * has no walk animation at all and would slide.
	 */
	@Test
	public void theRejectedNpcsStayRejected()
	{
		Set<Integer> ids = new HashSet<>();
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			ids.add(figure.getNpcId());
		}

		assertFalse("Chaeldar is on the fairy rig and has one model",
			ids.contains(NpcID.SLAYER_MASTER_4));
		assertFalse("Krystilia's stand and walk are the same id — she has no walk animation",
			ids.contains(NpcID.SLAYER_MASTER_7));
		assertFalse("Spria's animations are both -1", ids.contains(NpcID.SLAYER_MASTER_9_ACTIVE));
		assertFalse("the Gnome Child is on the gnome rig", ids.contains(NpcID.GNOMECHILDGREEN));
		assertFalse("Kamfreena was rejected on inspection", ids.contains(NpcID.WARGUILD_KAMFREENA));
		assertFalse("Sir Mordred was rejected on inspection", ids.contains(NpcID.SIR_MORDRED));
		assertFalse("6799 is the other Steve, not the slayer master",
			ids.contains(NpcID.WYVERN_CAVE_STEVE));
	}

	@Test
	public void noTwoFiguresWearTheSameBody()
	{
		Set<Integer> ids = new HashSet<>();
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			assertTrue(figure.name() + " duplicates an NPC id already in the enum",
				ids.add(figure.getNpcId()));
		}
	}

	// --- The animations -------------------------------------------------------

	/**
	 * The (idle, walk) pair each preset declares, from the cache. Tier A is the human
	 * rig's own 808/819; every Tier B entry below is here because it declares something
	 * else, and getting one of them wrong is a figure holding a polearm with its arms at
	 * its sides.
	 */
	@Test
	public void everyFigurePlaysThePairItsNpcDeclares()
	{
		human(EntourageFigure.ROGUE);
		human(EntourageFigure.DURADEL);
		human(EntourageFigure.MAZCHNA);
		human(EntourageFigure.SIR_AMIK_VARZE);
		human(EntourageFigure.SIR_VYVIN);
		human(EntourageFigure.PALADIN);
		human(EntourageFigure.GRILL_KNIGHT);
		human(EntourageFigure.GHOMMAL);
		human(EntourageFigure.HERO);
		human(EntourageFigure.ZAMORAK_MAGE);
		human(EntourageFigure.NECROMANCER);
		human(EntourageFigure.SORCERESS);
		human(EntourageFigure.THIEF);
		human(EntourageFigure.PIRATE);
		human(EntourageFigure.HANS);
		human(EntourageFigure.FARMER);

		pair(EntourageFigure.VANNAKA,
			EntourageAnimation.WEAPON_STAND, AnimationID.HUMAN_DH_WEAPON_READY, 2561,
			EntourageAnimation.HUMAN_WALK, AnimationID.HUMAN_WALK_F, 819);
		pair(EntourageFigure.NIEVE,
			EntourageAnimation.STAFF_STAND, AnimationID.HUMAN_STAFFREADY, 813,
			EntourageAnimation.HALBERD_WALK, AnimationID.HUMAN_HALBERDWALK_F, 1205);
		pair(EntourageFigure.STEVE,
			EntourageAnimation.STAFF_STAND, AnimationID.HUMAN_STAFFREADY, 813,
			EntourageAnimation.HALBERD_WALK, AnimationID.HUMAN_HALBERDWALK_F, 1205);
		pair(EntourageFigure.TURAEL,
			EntourageAnimation.STAFF_STAND, AnimationID.HUMAN_STAFFREADY, 813,
			EntourageAnimation.HALBERD_WALK, AnimationID.HUMAN_HALBERDWALK_F, 1205);
		pair(EntourageFigure.WISE_OLD_MAN,
			EntourageAnimation.STAFF_STAND, AnimationID.HUMAN_STAFFREADY, 813,
			EntourageAnimation.WALKING_STICK_WALK, AnimationID.WALK_WALKINGSTICK, 1146);
		pair(EntourageFigure.WHITE_KNIGHT,
			EntourageAnimation.WEAPON_STAND, AnimationID.HUMAN_DH_WEAPON_READY, 2561,
			EntourageAnimation.WEAPON_WALK, AnimationID.HUMAN_DH_WEAPON_WALK, 2562);
		pair(EntourageFigure.ELITE_BLACK_KNIGHT,
			EntourageAnimation.SWORD_STAND, AnimationID.DH_SWORD_UPDATE_READY, 7053,
			EntourageAnimation.SWORD_WALK, AnimationID.DH_SWORD_UPDATE_WALK, 7052);

		assertEquals("a preset with no line above is a preset nobody has checked the animations of",
			EntourageFigure.presets().size(), pinned.size());
	}

	private void human(EntourageFigure figure)
	{
		pair(figure,
			EntourageAnimation.HUMAN_STAND, AnimationID.HUMAN_READY, 808,
			EntourageAnimation.HUMAN_WALK, AnimationID.HUMAN_WALK_F, 819);
	}

	private void pair(EntourageFigure figure,
		EntourageAnimation idle, int idleConstant, int idleLiteral,
		EntourageAnimation walk, int walkConstant, int walkLiteral)
	{
		assertEquals(figure.name() + " does not idle with the animation it is documented as",
			idle, figure.getIdleAnimation());
		assertEquals(figure.name() + ": the idle names a different gameval constant",
			idleConstant, figure.getIdleAnimation().getId());
		assertEquals(figure.name() + ": the idle's constant has been renumbered",
			idleLiteral, figure.getIdleAnimation().getId());

		assertEquals(figure.name() + " does not walk with the animation it is documented as",
			walk, figure.getWalkAnimation());
		assertEquals(figure.name() + ": the walk names a different gameval constant",
			walkConstant, figure.getWalkAnimation().getId());
		assertEquals(figure.name() + ": the walk's constant has been renumbered",
			walkLiteral, figure.getWalkAnimation().getId());

		assertTrue(figure.name() + " is pinned twice", pinned.add(figure));
	}

	/**
	 * The run is the one animation in the enum that was not read off the NPC that plays
	 * it — nothing in the cache gives Nieve a run, because Nieve never runs — so it is
	 * the same id for everybody and the enum says so out loud.
	 */
	@Test
	public void everyFigureRunsWithTheHumanRigsOwnRun()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			assertEquals(figure.name(), EntourageAnimation.HUMAN_RUN, figure.getRunAnimation());
			assertEquals(figure.name(), AnimationID.HUMAN_RUNNING, figure.getRunAnimation().getId());
			assertEquals(figure.name() + ": HUMAN_RUNNING has been renumbered",
				824, figure.getRunAnimation().getId());
		}
	}

	/**
	 * A figure whose two movement animations are the same id is a figure that is not
	 * animated by moving — the sliding-mesh failure. Krystilia is exactly this case,
	 * which is why she is not in the enum.
	 */
	@Test
	public void noFigureIdlesAndWalksWithTheSameAnimation()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			assertNotEquals(figure.name() + " would slide along the ground",
				figure.getIdleAnimation(), figure.getWalkAnimation());
			assertNotEquals(figure.name() + " would slide at a run",
				figure.getWalkAnimation(), figure.getRunAnimation());
		}
	}

	@Test
	public void everyFigureHasAllThreeAnimations()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			assertTrue(figure.name() + " has no idle", figure.getIdleAnimation().getId() > 0);
			assertTrue(figure.name() + " has no walk", figure.getWalkAnimation().getId() > 0);
			assertTrue(figure.name() + " has no run", figure.getRunAnimation().getId() > 0);
		}
	}

	// --- Names ----------------------------------------------------------------

	@Test
	public void theLabelNamesTheNpcSoALogLineCanBeTracedToACacheId()
	{
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			assertTrue(figure.label(), figure.label().contains(String.valueOf(figure.getNpcId())));
		}
	}

	/**
	 * The dropdown reads {@code toString()}, so a figure with no display name would be
	 * an entry reading {@code GRILL_KNIGHT}, and two figures sharing one would be two
	 * indistinguishable rows.
	 */
	@Test
	public void everyFigureHasItsOwnPlayerFacingName()
	{
		Set<String> names = new HashSet<>();
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			String name = figure.getDisplayName();
			assertFalse(figure.name() + " has no display name", name.isEmpty());
			assertEquals(figure.name() + " is not rendered by its display name",
				name, figure.toString());
			assertNotEquals(figure.name() + " is showing its enum constant to the user",
				figure.name(), name);
			assertTrue(figure.name() + " shares a display name with another figure",
				names.add(name));
		}
	}

	@Test
	public void theDefaultIsTheRogue()
	{
		assertEquals("the config default and the roster have to agree on who ships",
			EntourageFigure.ROGUE, EntourageFigure.DEFAULT);
		assertEquals(EntourageFigure.DEFAULT, new FakeConfig().figure());
	}

	// --- The marker -----------------------------------------------------------

	/**
	 * <b>{@code CUSTOM} is the dropdown's word for a typed id, and nothing else.</b> Every
	 * accessor that would hand back a body throws, so a caller that bypassed
	 * {@link EntourageSettings#figureAt} fails loudly rather than drawing a wrong figure —
	 * and the presets list is what everything that walks bodies walks.
	 */
	@Test
	public void theMarkerIsNotABodyAndIsNotAmongThePresets()
	{
		assertFalse(EntourageFigure.CUSTOM.isPreset());
		assertFalse(EntourageFigure.presets().contains(EntourageFigure.CUSTOM));
		assertEquals("presets are everything but the marker",
			EntourageFigure.values().length - 1, EntourageFigure.presets().size());
		for (EntourageFigure figure : EntourageFigure.presets())
		{
			assertTrue(figure + " is on the presets list but is not one", figure.isPreset());
		}

		assertSame("last, so the default stays first in the dropdown",
			EntourageFigure.CUSTOM, EntourageFigure.values()[EntourageFigure.values().length - 1]);
		assertEquals("Custom NPC id", EntourageFigure.CUSTOM.toString());
		assertTrue(EntourageFigure.CUSTOM.label().contains("not a body"));

		assertRefused("getNpcId", () -> EntourageFigure.CUSTOM.getNpcId());
		assertRefused("getIdleAnimation", () -> EntourageFigure.CUSTOM.getIdleAnimation());
		assertRefused("getWalkAnimation", () -> EntourageFigure.CUSTOM.getWalkAnimation());
		assertRefused("getRunAnimation", () -> EntourageFigure.CUSTOM.getRunAnimation());
	}

	private static void assertRefused(String accessor, Runnable call)
	{
		try
		{
			call.run();
			fail(accessor + " on the marker should throw rather than answer for a body");
		}
		catch (UnsupportedOperationException expected)
		{
			assertTrue(expected.getMessage().contains("CUSTOM"));
		}
	}

	@Test
	public void thePresetsCannotBeEditedByTheirCallers()
	{
		try
		{
			EntourageFigure.presets().add(EntourageFigure.CUSTOM);
			fail("the presets list is shared and must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			assertFalse(EntourageFigure.presets().contains(EntourageFigure.CUSTOM));
		}
	}
}

package com.matthewmariner.entourage;

import java.util.ArrayList;
import java.util.List;

/**
 * A {@link LinkOpener} that remembers what it was asked to open instead of opening it.
 *
 * <p>The real one is {@code LinkBrowser.browse}, which needs a desktop and a browser and
 * is exactly the thing a build machine must never be asked for. This one turns "the footer
 * opens the wiki" into a list a test can read.
 */
final class FakeLinkOpener implements LinkOpener
{
	private final List<String> opened = new ArrayList<>();

	@Override
	public void open(String url)
	{
		opened.add(url);
	}

	/** Every URL asked for, in order. */
	List<String> opened()
	{
		return opened;
	}
}

package com.matthewmariner.entourage;

import net.runelite.api.Animation;

/**
 * A short looping animation, real enough for {@code AnimationController} to walk frames
 * through.
 *
 * <p>A null animation would be easier and would be a fixture too uniform to be worth
 * anything: {@code AnimationController.tick} returns immediately when its animation is
 * null, so every assertion about frames advancing would pass whether the plugin's
 * animation handling worked or not.
 *
 * <p>The numbers are chosen against {@code AnimationController}'s real arithmetic,
 * disassembled from the 1.12.38 API jar: the non-Maya path accumulates
 * {@code elapsedTicks} and advances while {@code elapsedTicks > frameLengths[frame]},
 * and {@code loop()} rewinds by {@code getFrameStep()} and resets to 0 if that leaves
 * the frame outside {@code getDuration()}. So a frame length of 3 client ticks means one
 * {@code tick(4)} advances exactly one frame, and a frame step equal to the frame count
 * makes the loop land back on frame 0.
 *
 * <p>All ten {@link Animation} methods are implemented rather than inheriting a throwing
 * stub: at ten methods a stub layer would be more code than the honest answers.
 */
final class FakeAnimation implements Animation
{
	static final int FRAMES = 8;
	static final int FRAME_LENGTH_CLIENT_TICKS = 3;

	/** Client ticks that advance the frame counter by exactly one. */
	static final int CLIENT_TICKS_PER_FRAME = FRAME_LENGTH_CLIENT_TICKS + 1;

	private final int id;
	private final int[] frameLengths;

	private int restartMode;

	FakeAnimation(int id)
	{
		this.id = id;
		this.frameLengths = new int[FRAMES];
		for (int i = 0; i < FRAMES; i++)
		{
			frameLengths[i] = FRAME_LENGTH_CLIENT_TICKS;
		}
	}

	@Override
	public int getId()
	{
		return id;
	}

	@Override
	public boolean isMayaAnim()
	{
		return false;
	}

	@Override
	public int getNumFrames()
	{
		return FRAMES;
	}

	@Override
	public int getRestartMode()
	{
		return restartMode;
	}

	@Override
	public void setRestartMode(int restartMode)
	{
		this.restartMode = restartMode;
	}

	@Override
	public int getDuration()
	{
		return FRAMES;
	}

	@Override
	public int getFrameStep()
	{
		return FRAMES;
	}

	@Override
	public int[] getFrameLengths()
	{
		return frameLengths;
	}

	@Override
	public int getLeftHandItem()
	{
		return -1;
	}

	@Override
	public int getRightHandItem()
	{
		return -1;
	}
}

package com.matthewmariner.entourage;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The settings surface as a fresh install sees it.
 *
 * <p><b>What is deliberately not tested here, and why.</b> The {@code @Range} bounds live
 * in annotations, and reading an annotation means reflection, which this repo forbids. So
 * the bounds are pinned through the constants the annotations are written in terms of —
 * {@link EntourageSettings#MIN_FOLLOW_DISTANCE} and friends — which is the whole of the
 * arithmetic either way. Writing a literal into a {@code @Range} instead of the constant
 * would slip past this file; that is the known gap, and it is cheaper than a reflective
 * test in a plugin that is not allowed to have one.
 *
 * <p><b>The {@code keyName}s used to be in that gap and are not any more.</b> Every one of
 * them is now a constant on {@link EntourageConfig} that its own annotation refers to, so
 * the strings are literals a test can hold — see
 * {@link #theKeyNamesAreTheOnesAlreadyWrittenIntoProfiles()}. The rename rule that used to
 * live only in a javadoc paragraph now goes red.
 */
public class EntourageConfigTest
{
	private final EntourageConfig config = new FakeConfig();

	/**
	 * <b>Every key, spelled out.</b> A {@code keyName} is what RuneLite writes into the
	 * user's profile: rename one and that setting silently resets to its default for
	 * everybody who had it, with no error and nothing in a log. There is no way to notice
	 * that from inside the plugin, because a profile with no value for a key and a profile
	 * that never had one are the same profile.
	 *
	 * <p>So the strings are written out here rather than compared against themselves. Two
	 * of them are deliberately not what their setting is called — {@code figure} is the
	 * first of five slots and {@code formationSlot} now holds a whole shape — and those two
	 * are exactly the ones a tidying pass would "fix".
	 */
	@Test
	public void theKeyNamesAreTheOnesAlreadyWrittenIntoProfiles()
	{
		assertEquals("followers", EntourageConfig.KEY_FOLLOWERS);
		assertEquals("the first slot's key predates the other four and cannot become figure1",
			"figure", EntourageConfig.KEY_FIGURE);
		assertEquals("figure2", EntourageConfig.KEY_FIGURE_2);
		assertEquals("figure3", EntourageConfig.KEY_FIGURE_3);
		assertEquals("figure4", EntourageConfig.KEY_FIGURE_4);
		assertEquals("figure5", EntourageConfig.KEY_FIGURE_5);
		assertEquals("the first slot's typed id predates the other four and cannot become "
			+ "customNpcId1", "customNpcId", EntourageConfig.KEY_CUSTOM_NPC_ID);
		assertEquals("customNpcId2", EntourageConfig.KEY_CUSTOM_NPC_ID_2);
		assertEquals("customNpcId3", EntourageConfig.KEY_CUSTOM_NPC_ID_3);
		assertEquals("customNpcId4", EntourageConfig.KEY_CUSTOM_NPC_ID_4);
		assertEquals("customNpcId5", EntourageConfig.KEY_CUSTOM_NPC_ID_5);
		assertEquals("favouriteNpcIds", EntourageConfig.KEY_FAVOURITE_NPC_IDS);
		assertEquals("followDistance", EntourageConfig.KEY_FOLLOW_DISTANCE);
		assertEquals("stayPut", EntourageConfig.KEY_STAY_PUT);
		assertEquals("this one holds a formation now and is still called formationSlot",
			"formationSlot", EntourageConfig.KEY_FORMATION);
	}

	/**
	 * The units suffix the settings spinner shows beside a distance.
	 *
	 * <p>{@code net.runelite.client.config.Units} has no tile, so this one is a literal
	 * rather than a client constant — and the leading space is load-bearing. Without it the
	 * spinner reads "2tiles".
	 */
	@Test
	public void aDistanceInTilesSaysSoTheWayTheClientSaysTicks()
	{
		assertEquals(" tiles", EntourageConfig.TILES);
		assertEquals("the client's own convention, which this one copies",
			" ticks", net.runelite.client.config.Units.TICKS);
	}

	/**
	 * The group is the prefix on every key in the user's profile. Renaming it resets
	 * every setting for everyone who has one, silently, so it is pinned as a literal
	 * rather than compared against itself.
	 */
	@Test
	public void theConfigGroupIsTheOneAlreadyWrittenIntoProfiles()
	{
		assertEquals("entourage", EntourageConfig.GROUP);
	}

	@Test
	public void aFreshInstallWalksARogueOneTileBehindAtARunHoldingItsOwnPose()
	{
		assertEquals("one follower, so a profile written before the roster existed still "
			+ "means what it meant", 1, config.followers());
		assertEquals(EntourageFigure.ROGUE, config.figure());
		assertEquals(1, config.followDistance());
		assertEquals(EntourageFormation.BEHIND, config.formation());
		assertEquals(12, config.recallDistance());
		assertEquals(EntouragePose.FIGURE_DEFAULT, config.idlePose());
		assertTrue("running is on by default — without it a running player is never kept up with",
			config.canRun());
		assertFalse("and a fresh install follows rather than standing still, because a plugin "
			+ "whose figures do not move is the plugin switched off", config.stayPut());
	}

	/**
	 * <b>Five different bodies in the five slots.</b> A default that put the same figure in
	 * all of them would make turning the roster up look like the setting had not worked —
	 * five identical figures reads as one figure drawn five times, which is also what the
	 * bug would look like.
	 */
	@Test
	public void theFiveFigureSlotsShipFiveDifferentFigures()
	{
		Set<EntourageFigure> shipped = new HashSet<>(Arrays.asList(
			config.figure(), config.figure2(), config.figure3(), config.figure4(),
			config.figure5()));

		assertEquals("five slots, five bodies", EntourageSettings.MAX_FOLLOWERS, shipped.size());
		assertEquals("the first slot is the one every existing profile has",
			EntourageFigure.DEFAULT, config.figure());

		for (EntourageFigure figure : shipped)
		{
			assertEquals(figure.name() + " is not on the human rig, so a default group would "
					+ "not move as one group",
				EntourageAnimation.HUMAN_WALK, figure.getWalkAnimation());
		}
	}

	/** And the enum's own answer is the one the dropdowns use, rather than a second copy. */
	@Test
	public void theShippedRosterComesFromTheFigureEnumRatherThanFromTheConfig()
	{
		assertEquals(EntourageFigure.defaultAt(0), config.figure());
		assertEquals(EntourageFigure.defaultAt(1), config.figure2());
		assertEquals(EntourageFigure.defaultAt(2), config.figure3());
		assertEquals(EntourageFigure.defaultAt(3), config.figure4());
		assertEquals(EntourageFigure.defaultAt(4), config.figure5());

		assertEquals("anything off the end of the roster is the first slot's figure",
			EntourageFigure.DEFAULT, EntourageFigure.defaultAt(-1));
		assertEquals(EntourageFigure.DEFAULT, EntourageFigure.defaultAt(9));
	}

	/**
	 * <b>The two keys that are not named the way their neighbours are, together in one
	 * place.</b> Both are the first of five and both are missing the {@code 1} the other four
	 * carry, and both are that way because they were written into profiles before there were
	 * four others — a rename resets that setting, silently, for exactly the people who used it
	 * most. This is the assertion a tidying pass has to go through.
	 */
	@Test
	public void theFirstSlotsTwoKeysKeepTheUnnumberedNamesTheyShippedWith()
	{
		assertFalse("figure1 would reset every profile that has ever set a figure",
			"figure1".equals(EntourageConfig.KEY_FIGURE));
		assertFalse("customNpcId1 would reset every profile that has ever typed an id",
			"customNpcId1".equals(EntourageConfig.KEY_CUSTOM_NPC_ID));

		assertEquals("and the other four are numbered from two, which is the price of that",
			"figure2", EntourageConfig.KEY_FIGURE_2);
		assertEquals("customNpcId2", EntourageConfig.KEY_CUSTOM_NPC_ID_2);
	}

	/** Nobody has a typed id or a favourite until they type one. */
	@Test
	public void aFreshInstallHasNoTypedIdInAnySlotAndNoFavourites()
	{
		assertEquals(0, config.customNpcId());
		assertEquals(0, config.customNpcId2());
		assertEquals(0, config.customNpcId3());
		assertEquals(0, config.customNpcId4());
		assertEquals(0, config.customNpcId5());
		assertEquals("", config.favouriteNpcIds());

		assertTrue("and the parsed answer is the empty list rather than a one-entry one",
			Favourites.parse(config.favouriteNpcIds()).isEmpty());
	}

	@Test
	public void aFreshInstallSaysSomethingOnceAMinuteInMagenta()
	{
		assertTrue("the feature the dialogue settings exist for is on by default",
			config.dialogue());
		assertEquals("", config.dialogueLines());
		assertEquals(100, config.dialogueIntervalTicks());
		assertEquals(8, config.dialogueDwellTicks());
		assertEquals(DialogueColour.MAGENTA, config.dialogueColour());
		assertEquals(DialogueFont.REGULAR, config.dialogueFont());
		assertFalse("a name over the head is opt-in", config.nameLabel());
		assertFalse("and so is vanishing inside an instance", config.hideInInstances());
		assertEquals(FollowerFacing.AT_ME, config.facing());
	}

	/**
	 * <b>A default outside its own bounds is silently overridden and nothing says so.</b>
	 * {@link EntourageSettings} clamps, so a default of 12 with a minimum raised to 14
	 * would leave the settings panel showing 12 while the follower used 14 — a number in
	 * the UI that is not the number in effect. This is the assertion that ties the two
	 * halves together.
	 */
	@Test
	public void everyDefaultSurvivesTheClampUnchanged()
	{
		EntourageSettings settings = EntourageSettings.from(config);

		assertEquals("the roster count default is outside its own range",
			config.followers(), settings.getRosterSize());
		assertEquals("the follow distance default is outside its own range",
			config.followDistance(), settings.getFollowDistance());
		assertEquals("the recall distance default is outside its own range",
			config.recallDistance(), settings.getRecallDistance());
		assertEquals("the dialogue interval default is outside its own range",
			config.dialogueIntervalTicks(), settings.getDialogueIntervalTicks());
		assertEquals("the dwell default is outside its own range, or longer than the interval",
			config.dialogueDwellTicks(), settings.getDialogueDwellTicks());
	}

	/**
	 * The cadence bounds in wall-clock terms, which is how the settings panel describes
	 * them and how anybody reasons about them. The units are the thing that has gone wrong
	 * before in this family of plugins: the client's other clock is the client tick, thirty
	 * to a game tick, and reading one figure as the other is a thirtyfold error.
	 */
	@Test
	public void theDialogueBoundsAreTheOnesTheDocumentationClaims()
	{
		assertEquals("six seconds", 6_000 / EntourageSettings.TICK_MILLIS,
			EntourageSettings.MIN_DIALOGUE_INTERVAL_TICKS);
		assertEquals("six minutes, past which the dial duplicates the off switch",
			360_000 / EntourageSettings.TICK_MILLIS, EntourageSettings.MAX_DIALOGUE_INTERVAL_TICKS);
		assertEquals("one minute", 60_000 / EntourageSettings.TICK_MILLIS,
			EntourageSettings.DEFAULT_DIALOGUE_INTERVAL_TICKS);

		assertEquals("three seconds, about one read of one line",
			3_000 / EntourageSettings.TICK_MILLIS, EntourageSettings.MIN_DIALOGUE_DWELL_TICKS);
		assertEquals("eighteen seconds", 18_000 / EntourageSettings.TICK_MILLIS,
			EntourageSettings.MAX_DIALOGUE_DWELL_TICKS);

		assertTrue("a range whose minimum exceeds its maximum clamps everything to one value",
			EntourageSettings.MIN_DIALOGUE_INTERVAL_TICKS
				< EntourageSettings.MAX_DIALOGUE_INTERVAL_TICKS);
		assertTrue(EntourageSettings.MIN_DIALOGUE_DWELL_TICKS
			< EntourageSettings.MAX_DIALOGUE_DWELL_TICKS);
		assertTrue("the shipped dwell has to be comfortably inside the shipped interval",
			EntourageSettings.DEFAULT_DIALOGUE_DWELL_TICKS
				< EntourageSettings.DEFAULT_DIALOGUE_INTERVAL_TICKS);
	}

	/**
	 * <b>The two caps on the custom-lines box, as literals.</b>
	 *
	 * <p>Everything that exercises them — the cut, the count, and the check that no
	 * shipped line is longer than a user's may be — is written in terms of these
	 * constants, which is right for a behavioural test and useless as a guard on the
	 * values themselves: raising {@code MAX_CUSTOM_LINE_LENGTH} to five thousand moves
	 * every one of those expectations with it and nothing goes red. This is the one place
	 * the numbers are written out, and they are the numbers the README quotes to the user.
	 */
	@Test
	public void theCustomLineCapsAreTheOnesTheReadmeQuotes()
	{
		assertEquals("the README says anything past sixty characters is cut",
			60, EntourageSettings.MAX_CUSTOM_LINE_LENGTH);
		assertEquals("and that the first twelve lines are used",
			12, EntourageSettings.MAX_CUSTOM_LINES);
		assertEquals("the box is comma-separated, which is what was asked for",
			',', EntourageSettings.CUSTOM_LINE_SEPARATOR);
	}

	@Test
	public void theBoundsAreTheOnesTheDocumentationClaims()
	{
		assertEquals("a zero follow distance is a follower standing inside the player",
			1, EntourageSettings.MIN_FOLLOW_DISTANCE);
		assertEquals("greedy stepping does not survive a slot further out than this",
			2, EntourageSettings.MAX_FOLLOW_DISTANCE);
		assertEquals("a column of five at the widest follow distance reaches this far back",
			6, EntourageSettings.MAX_STATION_DISTANCE);
		assertEquals("the furthest station plus two tiles of slack", 8,
			EntourageSettings.MIN_RECALL_DISTANCE);
		assertEquals("the loaded scene is 104 tiles, and a recall has to land inside it",
			20, EntourageSettings.MAX_RECALL_DISTANCE);

		assertTrue("a range whose minimum exceeds its maximum clamps everything to one value",
			EntourageSettings.MIN_FOLLOW_DISTANCE < EntourageSettings.MAX_FOLLOW_DISTANCE);
		assertTrue(EntourageSettings.MIN_RECALL_DISTANCE < EntourageSettings.MAX_RECALL_DISTANCE);
		assertTrue("a follower standing where it was told to must never be recalled for it",
			EntourageSettings.MAX_STATION_DISTANCE < EntourageSettings.MIN_RECALL_DISTANCE);
		assertTrue("a follower must never be told to stand further out than it is recalled from",
			EntourageSettings.MAX_FOLLOW_DISTANCE < EntourageSettings.MIN_RECALL_DISTANCE);
	}

	/**
	 * <b>The roster bounds, as literals, and the budget claim behind the upper one.</b>
	 * Everything that exercises the cap is written in terms of {@code MAX_FOLLOWERS},
	 * which is right for a behavioural test and useless as a guard on the value: raising it
	 * to nine moves every one of those loops with it and nothing goes red. This is the one
	 * place the number is written out.
	 *
	 * <p>Five is what the owner asked for and what the inherited budget clears —
	 * {@code ../lively-cities}' {@code RenderPolicy} allows 80 active objects and 9 model
	 * builds per frame, and five followers are five objects built once each. <b>No frame
	 * cost has been measured for this plugin</b>, so the ceiling is a deliberate stop
	 * rather than a profiled one, and moving it should be a decision somebody takes rather
	 * than a character they change.
	 */
	@Test
	public void theRosterBoundsAreTheOnesTheReadmeQuotes()
	{
		assertEquals("one follower, because a roster of nobody is the plugin's own off switch",
			1, EntourageSettings.MIN_FOLLOWERS);
		assertEquals("five, which is what was asked for and what the inherited budget clears",
			5, EntourageSettings.MAX_FOLLOWERS);
		assertEquals("and a fresh install is still the one figure it always was",
			1, EntourageSettings.DEFAULT_FOLLOWERS);

		assertTrue(EntourageSettings.MIN_FOLLOWERS < EntourageSettings.MAX_FOLLOWERS);
		assertTrue("the shipped roster has to be inside the range it is clamped to",
			EntourageSettings.DEFAULT_FOLLOWERS >= EntourageSettings.MIN_FOLLOWERS
				&& EntourageSettings.DEFAULT_FOLLOWERS <= EntourageSettings.MAX_FOLLOWERS);
	}
}

package com.matthewmariner.entourage;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Typing part of a name and getting the figure.
 *
 * <p>The queries below are the ones a person actually types — a half word, a word from the
 * middle of a name, and a name misremembered by a letter — rather than strings chosen to
 * suit the implementation.
 */
public class FigureSearchTest
{
	private static List<EntourageFigure> matching(String query)
	{
		return FigureSearch.matching(query);
	}

	private static EntourageFigure first(String query)
	{
		List<EntourageFigure> found = matching(query);
		assertFalse("\"" + query + "\" found nothing at all", found.isEmpty());
		return found.get(0);
	}

	/**
	 * An empty box is a browse, not a failed search. A panel that showed nothing until you
	 * typed would hide the list somebody opened it to read.
	 */
	@Test
	public void anEmptyQueryIsEveryFigureInTheOrderTheDropdownListsThem()
	{
		assertEquals(EntourageFigure.presets().size(), matching("").size());
		assertEquals(EntourageFigure.presets().size(), matching(null).size());
		assertEquals(EntourageFigure.presets().size(), matching("   ").size());

		assertSame("the enum's own order, which is the settings dropdown's order",
			EntourageFigure.presets().get(0), matching("").get(0));
		assertSame(EntourageFigure.presets().get(1), matching("").get(1));
	}

	/** Twenty-three is what the README promises, and the search walks all of them. */
	@Test
	public void everyFigureIsReachableByItsOwnName()
	{
		assertEquals("the README says twenty-three figures", 23, EntourageFigure.presets().size());

		for (EntourageFigure figure : EntourageFigure.presets())
		{
			assertSame(figure.getDisplayName() + " cannot be found by typing its own name",
				figure, first(figure.getDisplayName()));
		}
	}

	/**
	 * "Knight" is GRILL_KNIGHT's label and is also inside "White Knight" and "Elite Black
	 * Knight", both of which come earlier in the enum — so without the tiers the dropdown
	 * order would put one of those first.
	 *
	 * <p>The whole list rather than the first row, because the two behind it are what pins
	 * the <i>tie</i>: the sort is stable so that equally good answers keep the order the
	 * settings dropdown lists them in, and nothing else in this file would notice if they
	 * came back in some other order.
	 */
	@Test
	public void anExactNameOutranksTheLongerNamesThatContainIt()
	{
		assertEquals(Arrays.asList(
				EntourageFigure.GRILL_KNIGHT,
				EntourageFigure.WHITE_KNIGHT,
				EntourageFigure.ELITE_BLACK_KNIGHT),
			matching("Knight"));
	}

	/**
	 * <b>Chosen so that the tier is the only thing that can produce the answer.</b> "kn"
	 * starts "Knight", which is the fourteenth figure in the enum, and sits inside "White
	 * Knight" and "Elite Black Knight", which are the ninth and tenth. Sorted by tier the
	 * answer is Knight; sorted by nothing at all it is White Knight — so a version of this
	 * test built on a query where the best match happened to come first in the enum anyway
	 * could not fail, which is how the first draft of it read.
	 */
	@Test
	public void aPrefixOutranksAMatchInTheMiddleOfAName()
	{
		assertSame(EntourageFigure.GRILL_KNIGHT, first("kn"));
		assertTrue("the longer names are still offered, underneath",
			matching("kn").contains(EntourageFigure.WHITE_KNIGHT));

		// "man" starts nothing and sits inside "Wise Old Man" and "Necromancer".
		List<EntourageFigure> inTheMiddle = matching("man");
		assertTrue(inTheMiddle.contains(EntourageFigure.WISE_OLD_MAN));
		assertTrue(inTheMiddle.contains(EntourageFigure.NECROMANCER));
	}

	@Test
	public void aWordFromTheMiddleOfANameFindsIt()
	{
		assertSame(EntourageFigure.WISE_OLD_MAN, first("old man"));
		assertSame(EntourageFigure.ELITE_BLACK_KNIGHT, first("black"));
		assertSame(EntourageFigure.ZAMORAK_MAGE, first("mage"));
	}

	@Test
	public void searchIsNotCaseSensitiveEitherWay()
	{
		assertSame(EntourageFigure.VANNAKA, first("VANNAKA"));
		assertSame(EntourageFigure.VANNAKA, first("vAnNaKa"));
		assertSame(EntourageFigure.WISE_OLD_MAN, first("  Wise Old Man  "));
	}

	/**
	 * <b>The point of the near tier.</b> Each of these is a name off by one letter, which is
	 * the case a list this short makes most annoying: the figure is plainly in the dropdown
	 * and the box says nothing.
	 */
	@Test
	public void aNameMisrememberedByOneLetterStillFindsTheFigure()
	{
		assertSame("a dropped letter", EntourageFigure.VANNAKA, first("vanaka"));
		assertSame("a wrong vowel", EntourageFigure.DURADEL, first("duradal"));
		assertSame("a dropped letter mid-word", EntourageFigure.SORCERESS, first("sorcress"));
		assertSame("a doubled letter", EntourageFigure.NECROMANCER, first("neccromancer"));
	}

	/**
	 * And half a word with a typo in it, which is what typing fast actually produces.
	 *
	 * <p>"necrp" is the case the <i>opening</i> comparison exists for: it is one edit from
	 * the first five characters of "Necromancer" and seven from the whole word, so a
	 * near-match that only measured whole names would answer nothing. "vanaka" in the test
	 * above is the mirror image — one edit from the whole word and two from its opening —
	 * so between them the two comparisons cannot be removed without something going red.
	 */
	@Test
	public void aHalfTypedNameWithATypoInItStillFindsTheFigure()
	{
		assertSame(EntourageFigure.SORCERESS, first("sorcres"));
		assertSame("a slip in half a word, which no whole-word measure can reach",
			EntourageFigure.NECROMANCER, first("necrp"));
		assertSame(EntourageFigure.NECROMANCER, first("necro"));
		assertSame(EntourageFigure.PALADIN, first("palladin"));
	}

	/**
	 * <b>The floor, exercised at both sides of it.</b> Three characters have too many
	 * neighbours to be a spelling mistake, so "haz" must not become "Hans" — while the same
	 * kind of slip one character longer must.
	 */
	@Test
	public void aQueryTooShortToBeATypoIsNotTreatedAsOne()
	{
		assertEquals("four characters before a typo is forgiven at all — three has too many "
			+ "neighbours to be a spelling mistake", 4, FigureSearch.NEAR_MATCH_MINIMUM);

		assertTrue("\"haz\" is one edit from \"han\" and must not reach Hans",
			matching("haz").isEmpty());
		assertFalse("but four characters is over the floor", matching("hanz").isEmpty());
		assertSame(EntourageFigure.HANS, first("hanz"));
	}

	/**
	 * <b>Two edits are only forgiven once the query is long enough to carry them.</b>
	 * "Turael" mistyped twice in six characters must not match, because at that length two
	 * edits reaches names nobody meant; the same slack over the threshold must.
	 */
	@Test
	public void twoEditsAreForgivenOnlyFromSevenCharacters()
	{
		assertEquals("the threshold the near tier widens at", 7, FigureSearch.TWO_EDITS_FROM);

		assertTrue("six characters, two edits — \"turial\" is not offered Turael",
			matching("turial").isEmpty());
		assertSame("nine characters, two edits — \"necromencor\" is still Necromancer",
			EntourageFigure.NECROMANCER, first("necromencor"));
	}

	/**
	 * <b>A near match never outranks a real one, however close it is</b> — and these two
	 * queries are the ones where that is load-bearing rather than incidental.
	 *
	 * <p>"dura" starts "Duradel", the sixth figure, and is one substitution from "Turael",
	 * the fifth. "manc" sits inside "Necromancer", the eighteenth, and is one substitution
	 * from the opening of "Mazchna", the seventh. In both cases the figure that comes first
	 * in the enum is the wrong answer, so a search that ranked by nothing would hand back a
	 * near miss over a real hit — which is what somebody typing four letters of Duradel's
	 * name would see.
	 */
	@Test
	public void aNearMatchSortsBelowEveryRealMatch()
	{
		assertSame("a prefix beats a one-letter miss", EntourageFigure.DURADEL, first("dura"));
		assertTrue("and the near miss is still offered underneath",
			matching("dura").contains(EntourageFigure.TURAEL));

		assertSame("and so does a match in the middle of a name",
			EntourageFigure.NECROMANCER, first("manc"));
		assertTrue(matching("manc").contains(EntourageFigure.MAZCHNA));

		assertSame("an exact name most of all", EntourageFigure.DURADEL, first("duradel"));
	}

	@Test
	public void aNameNothingAnswersToFindsNothingRatherThanEverything()
	{
		assertTrue(matching("zulrah").isEmpty());
		assertTrue(matching("qqqqqqqq").isEmpty());
	}

	/** The list handed back is the caller's to read and nobody's to edit. */
	@Test
	public void theResultsCannotBeEditedUnderTheNextSearch()
	{
		try
		{
			matching("").add(EntourageFigure.ROGUE);
			fail("the result list must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// what an unmodifiable list does
		}
	}

	/** The dropdown marker is not a figure anybody can pick from the panel, so the search never offers it. */
	@Test
	public void theMarkerIsNotSearchable()
	{
		assertFalse(matching("").contains(EntourageFigure.CUSTOM));
		assertTrue("typing its own label finds nothing", matching("Custom NPC id").isEmpty());
		assertTrue(matching("custom").isEmpty());
	}
}

