		keyName = KEY_FIGURE,
		name = "Figure 1",
		description = "Whose body the first follower wears. Every one of these is built from the "
			+ "game's own cache, and each carries the stand and walk animations that NPC actually "
			+ "uses — so a figure holding a polearm walks like one. \"Custom NPC id\" means the box "
			+ "below holds the id that is in force, and the box wins: to go back to a figure here, "
			+ "empty the box first (the side panel does both in one click). This screen catches up "
			+ "next time it is opened. Changing this rebuilds the entourage on the next game tick.",
		position = 2,
		section = rosterSection
