package com.matthewmariner.entourage;

/**
 * Whose body one follower wears: one of {@link EntourageFigure}'s presets, or an NPC id
 * the user typed.
 *
 * <p><b>Why a value type, when {@link EntourageFigure#CUSTOM} exists.</b> That constant is
 * the <i>dropdown's</i> word for "the typed id is in force", added because the owner wanted
 * "Figure 1" to say so rather than go on naming a preset that was not walking with them.
 * It is not a body: it carries no NPC id and no animations, and every accessor that would
 * hand one back throws. A custom body has no fixed NPC id — that is the whole point of it —
 * and no fixed animations, because they are read out of the cache at spawn time. So the
 * body stays a value type, and the constructor below refuses the marker outright: a
 * {@code FollowerBody} holding {@code CUSTOM} as its fallback would throw the first time a
 * refused id asked for its lines, and that is a promise better broken in a test than in a
 * game tick. {@link EntourageSettings#figureAt} is the one place the substitution happens.
 *
 * <p><b>It carries a preset as well as the id, and that is not padding.</b> The preset is
 * what the follower falls back to when the id turns out not to work — see
 * {@link NpcRecord#hasWalkCycle()} for the three ways it can — and it is where the lines
 * over the figure's head come from, because {@link FigureLines} has nothing to say about
 * an arbitrary NPC and inventing it something would be writing dialogue for a body this
 * plugin has never seen.
 *
 * <p><b>Immutable, with value equality, because the roster is compared by value.</b>
 * {@link EntourageScene} notices a settings change by comparing this tick's list of
 * bodies against the one the followers were built for. A custom id changed from 1234 to
 * 5678 has to be a different roster, or the follower would go on wearing the old NPC
 * until something else forced a rebuild — and it is, because these are equal only when
 * both halves are.
 */
final class FollowerBody
{
	/**
	 * The value of the custom-id setting that means "use the dropdown": zero.
	 *
	 * <p>Zero rather than {@code -1} because the setting is a number typed into a spinner
	 * that starts at nothing, and because zero is not an NPC id anybody wants — file 0 of
	 * the NPC archive exists, but it is not a body a person picks on purpose. A separate
	 * on/off switch beside the number was the alternative, and it would only ever be a way
	 * for the two controls to disagree.
	 */
	static final int NO_CUSTOM_NPC = 0;

	private final EntourageFigure figure;

	/** {@link #NO_CUSTOM_NPC} when this is a plain preset. */
	private final int customNpcId;

	private FollowerBody(EntourageFigure figure, int customNpcId)
	{
		if (!figure.isPreset())
		{
			throw new IllegalArgumentException(
				"a body needs a preset to fall back on, and " + figure.name() + " is not one");
		}

		this.figure = figure;
		this.customNpcId = customNpcId;
	}

	/** @param figure the preset this follower wears */
	static FollowerBody preset(EntourageFigure figure)
	{
		return new FollowerBody(figure, NO_CUSTOM_NPC);
	}

	/**
	 * A body built from an id the user typed.
	 *
	 * <p><b>This is the one place a typed id is floored</b>, and it is here rather than in
	 * {@link EntourageSettings} because it is the factory every caller goes through:
	 * {@code @Range} bounds the settings spinner and nothing else, so a hand-edited profile
	 * really can hold a negative number, and a second floor at the reading end would be the
	 * same rule written twice with neither copy falsifiable on its own. Deliberately no
	 * ceiling — the NPC archive's highest file id moves with every game update, and
	 * {@link NpcArchive} asks the archive itself rather than a number written down here.
	 *
	 * @param npcId  the NPC to wear. Anything at or below {@link #NO_CUSTOM_NPC} is not a
	 *               custom body at all and gives the preset back, so a caller does not
	 *               have to test the setting before calling this.
	 * @param figure the preset to fall back on, and the source of this follower's lines
	 */
	static FollowerBody custom(int npcId, EntourageFigure figure)
	{
		return new FollowerBody(figure, Math.max(NO_CUSTOM_NPC, npcId));
	}

	/** @return whether this body is an id the user typed rather than a preset */
	boolean isCustom()
	{
		return customNpcId != NO_CUSTOM_NPC;
	}

	/**
	 * @return the preset behind this body: the figure itself when this is a preset, and
	 * the fallback when it is not. Never {@code null}, which is what lets
	 * {@link FigureLines} and {@link EntouragePose} go on taking an
	 * {@link EntourageFigure} rather than growing a second code path for a body that has
	 * no lines and no declared stand.
	 */
	EntourageFigure getFigure()
	{
		return figure;
	}

	/**
	 * @return the NPC whose models and recolours this follower wears — the typed id for a
	 * custom body, and the preset's own for everything else
	 */
	int getNpcId()
	{
		return isCustom() ? customNpcId : figure.getNpcId();
	}

	/**
	 * @return what this body is called in a log line. Deliberately not
	 * {@link EntourageFigure#getDisplayName()}: a log wants the id, so that a warning
	 * about a figure that would not resolve can be traced back to a cache entry.
	 */
	String label()
	{
		return isCustom() ? "custom (npc " + customNpcId + ")" : figure.label();
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof FollowerBody))
		{
			return false;
		}

		FollowerBody that = (FollowerBody) other;
		return customNpcId == that.customNpcId && figure == that.figure;
	}

	/**
	 * Present because {@link #equals(Object)} is, and mixing the id in because a hash that
	 * ignored half the state would be a legal hash and a bad one — see
	 * {@code FollowerBodyTest}, which pins two bodies differing only in their id to two
	 * different values so that this line is something a test can break.
	 */
	@Override
	public int hashCode()
	{
		return 31 * figure.hashCode() + customNpcId;
	}

	/** Matches {@link #label()}: this is what a roster-change log line prints. */
	@Override
	public String toString()
	{
		return label();
	}
}

package com.matthewmariner.entourage;

/**
 * Which way a figure faces when it takes one of the eight steps it can take.
 *
 * <p>The convention is the client's own, taken from
 * {@code Angle.getNearestDirection()}: 0 = south, 1 = west, 2 = north, 3 = east —
 * i.e. the angle rises as the facing turns clockwise from south, through a full turn
 * of {@link #TURN_UNITS}. {@code RuneLiteObjectController.setOrientation(int)} takes
 * a value in that space.
 *
 * <p><b>The method, disassembled, is three steps and not one.</b> An earlier version
 * of this javadoc quoted it as {@code (angle >> 9) & 3}, which is the bucketing
 * without the rounding — the part that makes it a <em>nearest</em>-direction:
 * <pre>
 *   int d = angle &gt;&gt;&gt; 9;              // unsigned, not &gt;&gt;
 *   if ((angle &amp; 256) != 0) d++;       // round to the nearer of the two
 *   switch (d &amp; 3) { 0 SOUTH, 1 WEST, 2 NORTH, 3 EAST }
 * </pre>
 * At the four cardinals (0, 512, 1024, 1536) bit 256 is clear, the increment never
 * fires, and the two forms agree — which is why the mapping above was right anyway,
 * and why nothing here behaves differently. They disagree at exactly the four
 * diagonals this table ships: 256 is WEST under the real method and SOUTH under the
 * truncating one, and 768, 1280 and 1792 are each off by one bucket the same way.
 * Nothing in this plugin calls {@code getNearestDirection}, so the cost of the wrong
 * quotation was to anybody checking the table against it.
 *
 * <p>A lookup table rather than {@code atan2(-dx, -dy)} because there are only eight
 * answers, every one of them exact, and a table cannot be a rounding bug.
 *
 * <p><b>Where the table came from, accurately.</b> The same array is
 * {@code CitizenWalk.STEP_ORIENTATION} in {@code ../lively-cities}, and this is a
 * copy of it, not a re-derivation: the literal is identical down to all three
 * trailing comments, with only the field name and {@code -1} spelled as
 * {@link #NOT_MOVING} to tell them apart. It is private there, which is why there
 * are two of it rather than one. The defence against the copy being wrong is not the
 * copying, it is {@code StepOrientationTest}, which checks every entry against the
 * geometry — the four cardinals from the convention above, and each diagonal against
 * the two cardinals it sits between — rather than against the other copy. That test
 * would fail if both copies were wrong together, which is the only property worth
 * having here.
 *
 * <p>Nothing here touches the client, so the whole of it is testable with no game
 * running.
 */
final class StepOrientation
{
	/** A full turn, in the units {@code setOrientation} takes: 0..2047. */
	static final int TURN_UNITS = 2048;

	/** The answer for {@code (0, 0)}: a figure that is not moving is not turning. */
	static final int NOT_MOVING = -1;

	/**
	 * Indexed {@code [dx + 1][dy + 1]}, with {@code dy} increasing to the north —
	 * which is the direction world and local coordinates both grow in.
	 */
	private static final int[][] BY_STEP = {
		//        dy = -1 (south)  dy = 0        dy = +1 (north)
		/* dx=-1 */ {256, 512, 768},      // south-west, west, north-west
		/* dx= 0 */ {0, NOT_MOVING, 1024}, // south, (not moving), north
		/* dx=+1 */ {1792, 1536, 1280},   // south-east, east, north-east
	};

	private StepOrientation()
	{
	}

	/**
	 * @param dx the west/east component of the step, of any magnitude
	 * @param dy the south/north component of the step, of any magnitude
	 * @return the orientation to face, in 0..2047, or {@link #NOT_MOVING} when both
	 * components are zero
	 */
	static int forStep(int dx, int dy)
	{
		// Reduced to signs here rather than at every call site. There are eight
		// directions whatever the magnitude, and a caller that has a two-tile delta
		// in hand should not have to remember to narrow it before asking.
		return BY_STEP[Integer.signum(dx) + 1][Integer.signum(dy) + 1];
	}

	/**
	 * Brings an angle from anywhere into 0..2047.
	 *
	 * <p>For the one orientation this plugin does not compute itself: the player's own,
	 * copied when {@link FollowerFacing#AS_I_AM} is picked. The injected client masks that
	 * field with {@code & 2047} before it stores it, so in practice it arrives in range —
	 * but {@code Actor} is an interface this plugin does not implement, and the cost of
	 * being wrong is a figure handed an orientation the renderer was never given.
	 *
	 * <p>{@code Math.floorMod} rather than {@code %}, because {@code -512 % 2048} is
	 * {@code -512} and a negative orientation is exactly the value this exists to rule
	 * out.
	 *
	 * @param angle any angle, in the same units
	 * @return the same facing expressed in 0..2047
	 */
	static int normalise(int angle)
	{
		return Math.floorMod(angle, TURN_UNITS);
	}
}

package com.matthewmariner.entourage;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * What each figure has to say, before the user has typed anything of their own.
 *
 * <p><b>Two kinds of line live here and they are not mixed within a figure.</b> Where the
 * NPC has recorded dialogue on the Old School RuneScape Wiki, the lines are that
 * dialogue, quoted exactly — the block below says which page each set came from. Where
 * the figure is a generic body out of the cache with no recorded speech at all (a rogue,
 * a farmer, a paladin), the lines are <b>written for this plugin</b> and are marked as
 * such. Nothing here is a paraphrase presented as a quote, and no figure carries a mix of
 * the two, so "is this the game's wording or ours?" is always answerable per figure
 * rather than per line. The README says the same thing to the user.
 *
 * <p><b>The six slayer masters really do share a script.</b> {@code 'Ello, and what are
 * you after then?}, {@code Good luck with that.} and {@code That's the spirit.} are
 * word-for-word identical on Vannaka's, Nieve's, Steve's, Turael's, Duradel's and
 * Mazchna's transcripts — it is one template the game reuses. Nieve, Duradel and Mazchna
 * have almost nothing else short enough to draw over a head, so their sets are mostly
 * that template. That is a fact about the game rather than a shortcut here, and the
 * alternative — inventing them a personality and calling it canon — is the thing this
 * class exists not to do.
 *
 * <p><b>Nothing here is longer than {@link EntourageSettings#MAX_CUSTOM_LINE_LENGTH}.</b>
 * The overlay draws a line centred over the figure's head without wrapping, so length is
 * a layout constraint rather than a style preference, and {@code FigureLinesTest} holds
 * every shipped line to the same bound a user's own line is cut at.
 *
 * <p><b>Lines may contain commas; a user's own may not.</b> These are Java string
 * literals and never go through {@link EntourageSettings#parseLines}, which splits on
 * every comma with no escape. So a preset can say {@code Well done, here you go.} and a
 * custom line cannot — that asymmetry is real, and the README states it rather than
 * leaving somebody to discover it by typing one.
 *
 * <p>Client-thread-free, allocation-free after class load: the lists are built once and
 * handed out unmodifiable.
 */
final class FigureLines
{
	/** The fewest lines a figure may ship with — the brief's floor, held by a test. */
	static final int MIN_LINES = 3;

	/**
	 * The most: seven. Past that a follower stops having a handful of things it says and
	 * starts having a script, and the odds of hearing any particular line get small
	 * enough that the writing stops mattering.
	 */
	static final int MAX_LINES = 7;

	/**
	 * The shared slayer-master template, named once rather than retyped six times — see
	 * the class javadoc. Sourced from every one of their transcripts.
	 */
	private static final String SLAYER_GREETING = "'Ello, and what are you after then?";
	private static final String SLAYER_GOOD_LUCK = "Good luck with that.";
	private static final String SLAYER_SPIRIT = "That's the spirit.";

	/** The shared Astral Contact greeting, likewise. */
	private static final String CONTACT_GREETING = "'Ello, can I help you?";

	private static final Map<EntourageFigure, List<String>> BY_FIGURE =
		new EnumMap<>(EntourageFigure.class);

	static
	{
		// --- Ours: figures with no recorded dialogue ---------------------------
		//
		// Every set in this block was written for this plugin. These are generic bodies
		// out of the cache — a rogue, a thief, a farmer — and the game gives them nothing
		// to say, so writing them something in keeping is the honest option and claiming
		// the wiki said it would not be.

		put(EntourageFigure.ROGUE,
			"Keep your voice down.",
			"Nobody saw us.",
			"Mind your purse.",
			"I know a shortcut.");

		put(EntourageFigure.WHITE_KNIGHT,
			"The White Knights stand ready.",
			"Falador is safe enough tonight.",
			"Keep to the path.",
			"I have my orders.");

		put(EntourageFigure.ELITE_BLACK_KNIGHT,
			"The Kinshra do not forget.",
			"Strength is its own argument.",
			"We are watching.",
			"Stay behind me.");

		put(EntourageFigure.PALADIN,
			"Ardougne is quieter than it looks.",
			"Stand fast.",
			"Trouble travels in threes.",
			"Keep moving.");

		put(EntourageFigure.GRILL_KNIGHT,
			"At your side.",
			"Lead on.",
			"A quiet patrol is a good patrol.",
			"My blade is sharp.");

		put(EntourageFigure.HERO,
			"They still tell that story wrong.",
			"I have seen worse.",
			"Another day. Onward.",
			"After you.");

		put(EntourageFigure.ZAMORAK_MAGE,
			"The Abyss is closer than you think.",
			"Mind the rifts.",
			"Power has a price.",
			"Do not touch that.");

		put(EntourageFigure.NECROMANCER,
			"The dead keep better secrets.",
			"Bones remember.",
			"I felt something move.",
			"Stand still a moment.");

		put(EntourageFigure.SORCERESS,
			"My garden is not for trespassers.",
			"Magic is not a parlour trick.",
			"Do stop fidgeting.",
			"The desert keeps its own counsel.");

		put(EntourageFigure.THIEF,
			"Nothing to see here.",
			"That pocket looked heavy.",
			"I was never here.",
			"Look busy.");

		put(EntourageFigure.PIRATE,
			"I have seen bigger waves.",
			"Land makes me queasy.",
			"Keep your rum close.",
			"There be worse company.");

		put(EntourageFigure.FARMER,
			"The crops need rain.",
			"Mind the drills.",
			"Best keep off the allotments.",
			"Nothing grows in a hurry.");

		// --- The game's own words ----------------------------------------------
		//
		// Each set below was read off the wiki transcript named above it and is quoted
		// exactly, punctuation and all — including the leading apostrophe in "'Ello" and
		// Sir Vyvin's ellipses, both of which are how the transcripts have them.

		// https://oldschool.runescape.wiki/wiki/Transcript:Vannaka
		put(EntourageFigure.VANNAKA,
			SLAYER_GREETING,
			SLAYER_GOOD_LUCK,
			SLAYER_SPIRIT,
			CONTACT_GREETING,
			"Here, have this.");

		// https://oldschool.runescape.wiki/wiki/Transcript:Nieve
		// and https://oldschool.runescape.wiki/wiki/Transcript:Monkey_Madness_II
		put(EntourageFigure.NIEVE,
			SLAYER_GREETING,
			SLAYER_GOOD_LUCK,
			"What in Gielinor is that thing?",
			"What's wrong?");

		// https://oldschool.runescape.wiki/wiki/Transcript:Steve — one page covers both
		// the Wyvern Cave gatekeeper and the slayer master he becomes.
		put(EntourageFigure.STEVE,
			"Welcome to my private little wyvern area.",
			"I love farming, but I need some help!",
			SLAYER_GREETING,
			SLAYER_SPIRIT);

		// https://oldschool.runescape.wiki/wiki/Transcript:Turael
		put(EntourageFigure.TURAEL,
			"I'm one of the elite Slayer Masters.",
			"Suit yourself.",
			"Hmmm well I'm not so sure...",
			"I suppose you want a new axe?",
			"Very well done, take this.");

		// https://oldschool.runescape.wiki/wiki/Transcript:Duradel — the template and
		// nothing else short enough. See the class javadoc.
		put(EntourageFigure.DURADEL,
			SLAYER_GREETING,
			SLAYER_GOOD_LUCK,
			SLAYER_SPIRIT);

		// https://oldschool.runescape.wiki/wiki/Transcript:Mazchna — likewise.
		put(EntourageFigure.MAZCHNA,
			SLAYER_GREETING,
			SLAYER_GOOD_LUCK,
			SLAYER_SPIRIT,
			CONTACT_GREETING);

		// https://oldschool.runescape.wiki/wiki/Transcript:Wise_Old_Man
		put(EntourageFigure.WISE_OLD_MAN,
			"Less of the 'old' man, if you please!",
			"Deary deary me...",
			"I know what I know.",
			"Spot on!",
			"Bah!");

		// https://oldschool.runescape.wiki/wiki/Transcript:Hans
		put(EntourageFigure.HANS,
			"Hello. What are you doing here?",
			"Oooh! Who are you?",
			"Well done, here you go.",
			"Help! Help!");

		// Sir Amik's own transcript is flagged incomplete and has almost nothing in it;
		// these are from the quests he speaks in —
		// https://oldschool.runescape.wiki/wiki/Transcript:Black_Knights%27_Fortress
		// and https://oldschool.runescape.wiki/wiki/Transcript:Wanted!
		put(EntourageFigure.SIR_AMIK_VARZE,
			"Subtlety isn't exactly our strong point.",
			"Ok. Please don't break anything.",
			"How's the mission going?",
			"Call me Sir Amik, or liege.");

		// https://oldschool.runescape.wiki/wiki/Transcript:Sir_Vyvin — the ellipses are
		// the transcript's, from the painting exchange.
		put(EntourageFigure.SIR_VYVIN,
			"Greetings traveller.",
			"... ...what?",
			"... ...you are very odd.",
			"Excellent work!");

		// https://oldschool.runescape.wiki/wiki/Transcript:Ghommal
		put(EntourageFigure.GHOMMAL,
			"Can I help you?",
			"Your gear is adequate, I'm impressed.",
			"Oh, how have you been getting on?");
	}

	private FigureLines()
	{
	}

	/**
	 * @param figure whose lines are wanted
	 * @return everything this figure can say, never {@code null} and never empty —
	 * {@code FigureLinesTest} holds every figure in the roster to at least
	 * {@link #MIN_LINES}. Unmodifiable: one list is shared by every follower that ever
	 * wears this figure, and a caller that could edit it would be editing the roster.
	 */
	static List<String> of(EntourageFigure figure)
	{
		List<String> lines = BY_FIGURE.get(figure);
		return lines == null ? Collections.emptyList() : lines;
	}

	private static void put(EntourageFigure figure, String... lines)
	{
		BY_FIGURE.put(figure, Collections.unmodifiableList(Arrays.asList(lines)));
	}
}

package com.matthewmariner.entourage;

import javax.annotation.Nullable;

/**
 * The two-and-a-bit fields this plugin needs out of one NPC's cache record: what it
 * stands with, what it walks with, and what it runs with.
 *
 * <p><b>Why this class exists at all.</b> {@link FollowerAppearance} can dress a figure
 * from any NPC id, because {@code NPCComposition} hands over {@code getModels()} and the
 * recolour pairs. It cannot animate one: that interface has no sequence accessor —
 * {@link EntourageAnimation}'s javadoc lists every method it does have — so
 * {@link EntourageFigure}'s twenty-three presets each carry a hand-verified pair instead.
 * An id typed into the settings box has no such pair, and a figure with no walk animation
 * is a body sliding across the ground, which is the single most visible way a follower
 * plugin can look broken. The cache record does carry the numbers. This reads them.
 *
 * <p><b>A pure function over {@code byte[]}, and that is the design rather than a
 * convenience.</b> Nothing here touches the client, allocates a client object or needs a
 * game running, so every branch below — including the malformed ones a live cache will
 * never produce — is reachable from a unit test. {@link NpcArchive} is the half that
 * talks to the client, and it is deliberately tiny for the same reason.
 *
 * <p><b>Transcribed from {@code net.runelite.cache.definitions.loaders.NpcLoader} at
 * 1.12.38</b>, read out of {@code net.runelite:cache:1.12.38}'s own sources jar rather
 * than from memory, with {@code EntityOpsLoader} and {@code net.runelite.cache.io.InputStream}
 * for the payload widths. The whole opcode table is here even though only four numbers
 * are kept, and it has to be: the record is a flat stream of opcode-then-payload with no
 * lengths and no index, so <b>the only way to reach opcode 13 is to have consumed every
 * byte in front of it correctly</b>. "Decode just the animations" is not an option the
 * format offers. That is also why every opcode below either reads its payload or is
 * explicitly a zero-byte flag — a missing {@code case} is not a field we ignore, it is
 * every later field misread.
 *
 * <p><b>The loader's revision switches are pinned to their defaults, which are the live
 * ones.</b> {@code NpcLoader} carries {@code rev210HeadIcons = true} and
 * {@code rev233 = true} unless {@code configureForRevision} says otherwise, so opcode 102
 * is the bitfield form and opcode 111 is the zero-byte {@code renderPriority} flag rather
 * than the pre-220 follower flag. Both of those are byte-width decisions, not semantic
 * ones: 111 reads nothing either way, and 102 has only the one live encoding.
 *
 * <p><b>An unrecognised opcode stops the parse where it stands.</b> The upstream loader
 * logs and carries on, which reads the next byte as an opcode and turns one unknown field
 * into a stream of nonsense. A future game update that adds an opcode would then be a
 * <i>wrong</i> animation pair rather than a missing one, and a wrong pair is a follower
 * that looks broken while the plugin believes it succeeded. Stopping keeps whatever was
 * read before the unknown byte — the animation opcodes are 13, 14, 17, 114 and 115, low
 * in the table — and anything incomplete fails {@link #hasWalkCycle()} and is refused out
 * loud. The same applies to a truncated record: reads past the end return zero and set
 * {@link #isComplete()} false rather than throwing, because this is called from a
 * game-tick handler.
 *
 * <p><b>Nothing here ever throws.</b> Not on {@code null}, not on an empty array, not on
 * a record that ends mid-field.
 */
final class NpcRecord
{
	/**
	 * What an animation field holds when the record does not declare one: {@code -1},
	 * which is {@code NpcDefinition}'s own default for all four of them.
	 */
	static final int NO_ANIMATION = -1;

	/**
	 * The largest animation id this plugin will hand to {@code Client.loadAnimation}:
	 * 65534.
	 *
	 * <p>Every animation opcode reads an <i>unsigned</i> short, so 65535 is representable
	 * and is the wire spelling of "none" everywhere else in this format — the config
	 * opcodes at 106 and 118 read it and write {@code -1}, in the loader, three lines
	 * apart from these. The animation opcodes do not do that conversion, so a record that
	 * declared 65535 would arrive here as a positive number that no sequence archive has
	 * an entry for. Left unbounded that is a follower whose walk silently fails to load
	 * and which therefore slides, which is exactly the outcome this class exists to
	 * prevent. Bounding it turns the same case into a refusal with a warning.
	 */
	static final int MAX_ANIMATION_ID = 65_534;

	private final int standingAnimation;
	private final int walkingAnimation;
	private final int runAnimation;
	private final boolean complete;

	private NpcRecord(int standingAnimation, int walkingAnimation, int runAnimation,
		boolean complete)
	{
		this.standingAnimation = standingAnimation;
		this.walkingAnimation = walkingAnimation;
		this.runAnimation = runAnimation;
		this.complete = complete;
	}

	/**
	 * Reads one NPC's cache record.
	 *
	 * @param data the record's bytes, already decompressed and decrypted by the client —
	 *             see {@link NpcArchive}. May be {@code null} or empty; both give a record
	 *             that declares nothing and is not {@link #isComplete()}.
	 * @return what the record says, never {@code null} and never a throw
	 */
	static NpcRecord decode(@Nullable byte[] data)
	{
		if (data == null)
		{
			return new NpcRecord(NO_ANIMATION, NO_ANIMATION, NO_ANIMATION, false);
		}

		Cursor in = new Cursor(data);

		int standing = NO_ANIMATION;
		int walking = NO_ANIMATION;
		int running = NO_ANIMATION;
		boolean complete = false;

		while (true)
		{
			int opcode = in.u8();
			if (!in.ok())
			{
				// Ran off the end looking for the next opcode. Checked before the
				// terminator test on purpose: an exhausted cursor answers zero, and zero
				// is also the terminator, so testing the value first would read a truncated
				// record as a well-formed one.
				break;
			}

			if (opcode == 0)
			{
				complete = true;
				break;
			}

			// Assigned rather than returned so that a later opcode overwrites an earlier
			// one, which is what the upstream loader does — opcodes 14 and 17 both write
			// the walk, and 114 and 115 both write the run.
			switch (opcode)
			{
				case 1: // models, one unsigned short each
					in.skipShorts(in.u8());
					break;

				case 2: // name
					in.skipString();
					break;

				case 12: // size, in tiles
					in.u8();
					break;

				case 13:
					standing = in.u16();
					break;

				case 14:
					walking = in.u16();
					break;

				case 15: // idle rotate left
				case 16: // idle rotate right
					in.u16();
					break;

				case 17: // walk, plus the three turning variants of it
					walking = in.u16();
					in.skipShorts(3);
					break;

				case 18: // category
					in.u16();
					break;

				case 30: // op 1..5. Each is a string; "Hidden" is a value, not a marker,
				case 31: // so it costs the same bytes as any other.
				case 32:
				case 33:
				case 34:
					in.skipString();
					break;

				case 40: // recolour: n (find, replace) pairs of shorts
				case 41: // retexture: the same shape
					in.skipShorts(in.u8() * 2);
					break;

				case 60: // chathead models, unsigned shorts
					in.skipShorts(in.u8());
					break;

				case 61: // models, ints — the wide form, for ids past 16 bits
				case 62: // chathead models, ints
					in.skipInts(in.u8());
					break;

				case 74: // the six combat stats
				case 75:
				case 76:
				case 77:
				case 78:
				case 79:
					in.u16();
					break;

				case 93: // not drawn on the minimap
					break;

				case 95: // combat level
				case 97: // width scale
				case 98: // height scale
					in.u16();
					break;

				case 99: // render priority 1
					break;

				case 100: // ambient, a signed byte
				case 101: // contrast, a signed byte
					in.u8();
					break;

				case 102:
					in.skipHeadIcons();
					break;

				case 103: // rotation speed
					in.u16();
					break;

				case 106: // varbit, varp, and the transform table
					in.skipShorts(2);
					in.skipShorts(in.u8() + 1);
					break;

				case 107: // not interactable
				case 109: // does not rotate
				case 111: // render priority 2 at rev233, which is the live default
					break;

				case 114:
					running = in.u16();
					break;

				case 115: // run, plus the three turning variants of it
					running = in.u16();
					in.skipShorts(3);
					break;

				case 116: // crawl
					in.u16();
					break;

				case 117: // crawl, plus its three turning variants
					in.skipShorts(4);
					break;

				case 118: // varbit, varp, a default, and the transform table
					in.skipShorts(3);
					in.skipShorts(in.u8() + 1);
					break;

				case 122: // is a follower
				case 123: // low priority follower ops
					break;

				case 124: // height
				case 126: // footprint size
					in.u16();
					break;

				case 129: // unknown flag
				case 130: // idle animation restarts
				case 145: // may hide when overlapped
					break;

				case 146: // overlap tint
					in.u16();
					break;

				case 147: // no z-buffer
					break;

				case 249:
					in.skipParams();
					break;

				case 251: // sub-op: index, sub id, text — two single bytes, then a string
					in.u8();
					in.u8();
					in.skipString();
					break;

				case 252: // conditional op: index, varp, varb, min, max, text
					in.u8();
					in.skipShorts(2);
					in.skipInts(2);
					in.skipString();
					break;

				case 253: // conditional sub-op: index, sub id, varp, varb, min, max, text
					in.u8();
					in.skipShorts(3);
					in.skipInts(2);
					in.skipString();
					break;

				default:
					// Unrecognised. Everything after this byte is unreadable — see the
					// class javadoc — so stop rather than guess. `complete` stays false.
					return new NpcRecord(standing, walking, running, false);
			}
		}

		// `complete` and not `complete && in.ok()`: the exhausted-cursor case is already the
		// break above, and saying it twice makes both copies unfalsifiable — mutate either
		// one and the other still answers. The loop is the single place that decides.
		return new NpcRecord(standing, walking, running, complete);
	}

	/** @return the sequence it holds while standing, or {@link #NO_ANIMATION} */
	int getStandingAnimation()
	{
		return standingAnimation;
	}

	/** @return the sequence it plays while walking, or {@link #NO_ANIMATION} */
	int getWalkingAnimation()
	{
		return walkingAnimation;
	}

	/**
	 * @return the sequence it plays while running, or {@link #NO_ANIMATION}. Plenty of
	 * NPCs declare none — they never run — and {@link Follower} falls back to the walk for
	 * those, which is what the client itself does.
	 */
	int getRunAnimation()
	{
		return runAnimation;
	}

	/**
	 * @return whether the parse reached the record's own terminator without running out
	 * of bytes or meeting an opcode it could not size. False means the numbers above are
	 * whatever was read before the parse stopped — they are never <i>wrong</i>, because
	 * everything in front of them was consumed correctly, but there may be more the record
	 * declared that this could not reach.
	 */
	boolean isComplete()
	{
		return complete;
	}

	/**
	 * Whether an NPC dressed from this record can be made to walk convincingly.
	 *
	 * <p><b>The three ways of failing are all real NPCs, not hypotheticals.</b> Spria
	 * declares neither a stand nor a walk — both are {@code -1} — and Krystilia declares
	 * the same id for both, which is a figure holding its standing pose while it covers
	 * ground. {@link EntourageFigure} rejects presets like those by name; an id typed into
	 * a settings box can be any of them, and the plugin has to notice on its own.
	 *
	 * @return true when both a stand and a walk are declared, they are different
	 * sequences, and both are ids {@code Client.loadAnimation} could resolve — see
	 * {@link #MAX_ANIMATION_ID}
	 */
	boolean hasWalkCycle()
	{
		return isLoadable(standingAnimation)
			&& isLoadable(walkingAnimation)
			&& standingAnimation != walkingAnimation;
	}

	/**
	 * @param animationId a sequence id out of this record
	 * @return whether it is one worth handing to {@code Client.loadAnimation}. Asking for
	 * a sequence outside this range costs a retry attempt in {@link Follower} and can
	 * never succeed.
	 */
	static boolean isLoadable(int animationId)
	{
		return animationId >= 0 && animationId <= MAX_ANIMATION_ID;
	}

	@Override
	public String toString()
	{
		return "NpcRecord{stand=" + standingAnimation
			+ ", walk=" + walkingAnimation
			+ ", run=" + runAnimation
			+ (complete ? "}" : ", incomplete}");
	}

	/**
	 * A read head over the record's bytes that answers zero instead of throwing.
	 *
	 * <p>Big-endian, matching {@code net.runelite.cache.io.InputStream}, which is a
	 * {@code ByteBuffer} in its default order. The difference from that class is the
	 * failure mode: a {@code ByteBuffer} throws {@code BufferUnderflowException} at the
	 * end of a truncated record, and this is reached from a game-tick handler where a
	 * throw costs the whole pass. {@link #ok()} is how the caller finds out instead.
	 *
	 * <p>Once exhausted it stays exhausted: every later read is refused rather than
	 * wrapping back into the buffer.
	 */
	private static final class Cursor
	{
		private final byte[] data;
		private int pos;
		private boolean underrun;

		Cursor(byte[] data)
		{
			this.data = data;
		}

		/** @return whether every read so far had the bytes it asked for */
		boolean ok()
		{
			return !underrun;
		}

		/**
		 * @return whether {@code bytes} more may be read, latching the underrun when they
		 * cannot. {@code pos} never exceeds {@code data.length}, so the sum cannot
		 * overflow.
		 *
		 * <p><b>Deliberately no {@code underrun ||} short-circuit.</b> A cursor that
		 * refused every later read once it had failed one would be a second copy of the
		 * rule the parse loop already enforces — it stops at the top of the next iteration
		 * on {@link #ok()} — and two copies of one guard means neither can be broken by
		 * itself, so neither can be tested. The loop is where "once exhausted, stop" is
		 * said, once. {@link #underrun} itself still latches: nothing ever clears it.
		 */
		private boolean take(int bytes)
		{
			if (pos + bytes > data.length)
			{
				underrun = true;
				return false;
			}
			return true;
		}

		/**
		 * @return the next byte, unsigned. Also used for the signed one-byte fields
		 * (ambient, contrast), whose values this plugin discards — only the width matters.
		 */
		int u8()
		{
			if (!take(1))
			{
				return 0;
			}
			return data[pos++] & 0xFF;
		}

		/** @return the next two bytes, big-endian, unsigned */
		int u16()
		{
			if (!take(2))
			{
				return 0;
			}
			int value = ((data[pos] & 0xFF) << 8) | (data[pos + 1] & 0xFF);
			pos += 2;
			return value;
		}

		/**
		 * @return the next byte without consuming it, signed, as {@code peek()} is
		 * upstream. Zero when there is no next byte, and deliberately <b>without</b>
		 * latching the underrun: every caller follows a peek with the {@link #skip} whose
		 * width the peek decided, and that skip cannot succeed on a buffer with nothing
		 * left in it. Latching here as well would be the same rule written twice, and
		 * neither copy could then be broken on its own.
		 */
		private int peek()
		{
			if (pos >= data.length)
			{
				return 0;
			}
			return data[pos];
		}

		private void skip(int bytes)
		{
			if (take(bytes))
			{
				pos += bytes;
			}
		}

		/**
		 * @param count how many unsigned shorts to discard. A count out of a one-byte
		 *              length is at most 256, so the multiplication cannot overflow.
		 */
		void skipShorts(int count)
		{
			skip(count * 2);
		}

		/** @param count how many four-byte ints to discard */
		void skipInts(int count)
		{
			skip(count * 4);
		}

		/**
		 * Discards a null-terminated string.
		 *
		 * <p>The upstream reader maps bytes 128..159 onto a Windows-1252 table; that
		 * changes the characters and not the length, and nothing here keeps the
		 * characters. A string with no terminator exhausts the cursor, which is the
		 * truncated-record case.
		 */
		void skipString()
		{
			while (ok() && u8() != 0)
			{
				// The terminator is the only byte that means anything here.
			}
		}

		/**
		 * Discards opcode 102's head icons.
		 *
		 * <p>A one-byte bitfield, then one entry per bit position <i>up to and including
		 * the highest set bit</i> — the upstream loop counts shifts until the field is
		 * zero, which is the bit length rather than the population count, and the two
		 * differ for any bitfield with a gap in it. Only the set positions carry bytes.
		 *
		 * <p>Each of those is a {@code readBigSmart2} — two bytes, or four when the first
		 * has its high bit set — followed by a {@code readUnsignedShortSmartMinusOne},
		 * which is one byte below 128 and two at or above it. Both are variable width, so
		 * this is the one opcode whose length cannot be worked out without reading it.
		 */
		void skipHeadIcons()
		{
			int bitfield = u8();

			int length = 0;
			for (int remaining = bitfield; remaining != 0; remaining >>= 1)
			{
				length++;
			}

			for (int i = 0; i < length && ok(); i++)
			{
				if ((bitfield & (1 << i)) == 0)
				{
					continue;
				}

				skip(peek() < 0 ? 4 : 2);
				skip((peek() & 0xFF) < 128 ? 1 : 2);
			}
		}

		/**
		 * Discards opcode 249's parameter map.
		 *
		 * <p>A one-byte count, then per entry a one-byte type, a three-byte id and a value
		 * whose width the type decides: a string, eight bytes for type 2, four otherwise.
		 * Transcribed from {@code InputStream.readParams} rather than from the shorter
		 * two-branch form the client's own reader is often described with — if those ever
		 * disagree this is the one the rest of this class was read from.
		 */
		void skipParams()
		{
			int count = u8();
			for (int i = 0; i < count && ok(); i++)
			{
				int type = u8();
				skip(3);

				if (type == 1)
				{
					skipString();
				}
				else
				{
					skip(type == 2 ? 8 : 4);
				}
			}
		}
	}
}

package com.matthewmariner.entourage;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JComponent;
